class PhaseErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, info) {
    console.error("Phase component error:", error, info);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: 24, borderRadius: 18, background: "rgba(254,242,242,0.98)", border: `1px solid ${T.red200}`, color: T.red500 }}>
          <h3 style={{ fontSize: 16, fontWeight: 700, marginBottom: 8, color: T.red500 }}>Something went wrong in this section</h3>
          <p style={{ fontSize: 12.5, marginBottom: 12, color: T.gray700 }}>{this.state.error?.message}</p>
          <button
            type="button"
            style={{ fontSize: 12.5, textDecoration: "underline", color: T.red500, background: "transparent", border: "none", padding: 0, cursor: "pointer" }}
            onClick={() => this.setState({ hasError: false, error: null })}
          >
            Try again
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

function delay(ms = 0) {
  return new Promise((resolve) => globalThis.setTimeout(resolve, ms));
}

