function enqueueAICall(fn, description = "unknown") {
  return new Promise((resolve, reject) => {
    _aiCallQueue.queue.push({ fn, resolve, reject, description, retryCount: 0 });
    drainAICallQueue();
  });
}

async function drainAICallQueue() {
  if (_aiCallQueue.running) return;
  _aiCallQueue.running = true;
  try {
    while (_aiCallQueue.queue.length > 0) {
      const call = _aiCallQueue.queue.shift();
      if (!call) continue;
      try {
        const result = await call.fn();
        call.resolve(result);
      } catch (error) {
        const retryCount = (call.retryCount || 0) + 1;
        const deadLetter = {
          id: globalThis.crypto?.randomUUID?.() || `dl-${Math.random().toString(36).slice(2, 10)}`,
          timestamp: new Date().toISOString(),
          description: call.description || "unknown",
          error: error?.message || String(error),
          retryCount,
        };
        const existing = JSON.parse(safeLocalStorageGet("adam_dead_letters") || "[]");
        existing.push(deadLetter);
        safeLocalStorageSet("adam_dead_letters", JSON.stringify(existing.slice(-50)));
        if (retryCount <= 2) {
          await delay(Math.min(1000 * (2 ** retryCount), 30000));
          _aiCallQueue.queue.push({ ...call, retryCount });
          continue;
        }
        showGlobalNotice(`AI task failed after retries: ${deadLetter.description}`, 5200);
        call.reject(error);
      }
    }
  } finally {
    _aiCallQueue.running = false;
  }
}

async function requestAIText(system, user, options = {}) {
  const runtime = getActiveAIRuntimeConfig();
  if (!runtime.available) {
    throw new Error(runtime.message || "Live AI runtime is not configured.");
  }
  const maxTokens = Number(options?.max_tokens || options?.max_output_tokens || AI_MAX_TOKENS_TEXT) || AI_MAX_TOKENS_TEXT;
  return enqueueAICall(async () => {
    let attempt = 0;
    const maxAttempts = 3;
    while (attempt < maxAttempts) {
      try {
        if (runtime.protocol === "anthropic") {
          const res = await fetch(runtime.endpoint, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "x-api-key": runtime.apiKey,
              "anthropic-version": "2023-06-01",
              "anthropic-dangerous-direct-browser-access": "true",
            },
            body: JSON.stringify({
              model: runtime.model,
              max_tokens: maxTokens,
              system,
              messages: [{ role: "user", content: user }],
            }),
          });
          if (res.ok) return extractAnthropicText(await res.json().catch(() => null));
          if (res.status === 429 || res.status >= 500) {
            attempt += 1;
            if (attempt < maxAttempts) await delay(1000 * attempt);
            continue;
          }
          let detail = "";
          try {
            detail = await res.text();
          } catch {}
          throw new Error(detail || `AI request failed with status ${res.status}`);
        }

        if (runtime.protocol === "openai-responses") {
          const res = await fetch(runtime.endpoint, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${runtime.apiKey}`,
            },
            body: JSON.stringify({
              model: runtime.model,
              input: [
                { role: "system", content: system },
                { role: "user", content: user },
              ],
              max_output_tokens: maxTokens,
            }),
          });
          if (res.ok) return extractOpenAIText(await res.json().catch(() => null));
          if (res.status === 429 || res.status >= 500) {
            attempt += 1;
            if (attempt < maxAttempts) await delay(1000 * attempt);
            continue;
          }
          let detail = "";
          try {
            detail = await res.text();
          } catch {}
          throw new Error(detail || `AI request failed with status ${res.status}`);
        }

        if (runtime.protocol === "openai-chat") {
          const res = await fetch(runtime.endpoint, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${runtime.apiKey}`,
            },
            body: JSON.stringify({
              model: runtime.model,
              messages: [
                { role: "system", content: system },
                { role: "user", content: user },
              ],
              max_tokens: maxTokens,
            }),
          });
          if (res.ok) return extractOpenAIText(await res.json().catch(() => null));
          if (res.status === 429 || res.status >= 500) {
            attempt += 1;
            if (attempt < maxAttempts) await delay(1000 * attempt);
            continue;
          }
          let detail = "";
          try {
            detail = await res.text();
          } catch {}
          throw new Error(detail || `AI request failed with status ${res.status}`);
        }

        if (runtime.protocol === "gemini") {
          const endpoint = `${runtime.endpoint.replace(/\/$/, "")}/${runtime.model}:generateContent?key=${encodeURIComponent(runtime.apiKey)}`;
          const res = await fetch(endpoint, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              contents: [{ parts: [{ text: `${system}\n\n${user}` }] }],
            }),
          });
          if (res.ok) return extractGeminiText(await res.json().catch(() => null));
          if (res.status === 429 || res.status >= 500) {
            attempt += 1;
            if (attempt < maxAttempts) await delay(1000 * attempt);
            continue;
          }
          let detail = "";
          try {
            detail = await res.text();
          } catch {}
          throw new Error(detail || `AI request failed with status ${res.status}`);
        }

        throw new Error(`Unsupported AI runtime protocol: ${runtime.protocol}`);
      } catch (error) {
        attempt += 1;
        if (attempt >= maxAttempts) throw error;
        await delay(1000 * attempt);
      }
    }
    throw new Error("AI request failed after retries.");
  }, options?.description || "AI text request");
}

function dataUrlToBase64(dataUrl = "") {
  return String(dataUrl).split(",")[1] || "";
}

function fileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(new Error("Unable to read attachment as data URL."));
    reader.readAsDataURL(file);
  });
}

async function requestAIImageText(file, dataUrl) {
  const runtime = getActiveAIRuntimeConfig();
  if (!runtime.available) {
    throw new Error(runtime.message || "Live AI runtime is not configured.");
  }
  const isLikelyDiagram = /\.(png|jpg|jpeg|gif|webp|bmp|tiff?|svg)$/i.test(file.name)
    && !/photo|screenshot|screen.?shot/i.test(file.name);
  const system = isLikelyDiagram
    ? "You are Brillio ADAM™ file intelligence specialising in business diagrams. For architecture diagrams, process flows, org charts, swim-lane diagrams, and capability maps: extract (1) all node/box labels, (2) all connector/arrow labels, (3) the hierarchy or sequence implied by the layout, (4) any legend entries. For slides or screenshots: extract all visible text preserving heading hierarchy. Return plain structured text only."
    : "You are Brillio ADAM™ file intelligence. Extract all visible text, headings, labels, table values, and materially useful business context from this image. Preserve line breaks between distinct text blocks. Return plain text only.";
  const userPrompt = `File: ${file.name}\nExtract all business-relevant content for ADAM Copilot context. If this is a diagram, extract node labels, connector labels, and layout hierarchy. If this is a document page, extract text preserving section structure.`;
  const extMimeMap = { ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".png": "image/png", ".gif": "image/gif", ".webp": "image/webp", ".bmp": "image/png", ".tif": "image/png", ".tiff": "image/png", ".heic": "image/jpeg", ".heif": "image/jpeg", ".svg": "image/png" };
  const extMatch = file.name.toLowerCase().match(/\.[a-z0-9]+$/)?.[0] || "";
  const mimeType = (file.type && file.type.startsWith("image/") && file.type !== "image/x-bmp") ? file.type : (extMimeMap[extMatch] || "image/png");
  const base64 = dataUrlToBase64(dataUrl);

  if (runtime.protocol === "anthropic") {
    const res = await fetch(runtime.endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": runtime.apiKey,
        "anthropic-version": "2023-06-01",
        "anthropic-dangerous-direct-browser-access": "true",
      },
      body: JSON.stringify({
        model: runtime.model,
        max_tokens: AI_MAX_TOKENS_IMAGE,
        system,
        messages: [{
          role: "user",
          content: [
            {
              type: "image",
              source: {
                type: "base64",
                media_type: mimeType,
                data: base64,
              },
            },
            { type: "text", text: userPrompt },
          ],
        }],
      }),
    });
    if (!res.ok) {
      let detail = "";
      try {
        detail = await res.text();
      } catch {}
      throw new Error(detail || `AI OCR request failed with status ${res.status}`);
    }
    return extractAnthropicText(await res.json().catch(() => null));
  }

  if (runtime.protocol === "openai-responses") {
    const res = await fetch(runtime.endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${runtime.apiKey}`,
      },
      body: JSON.stringify({
        model: runtime.model,
        input: [
          { role: "system", content: system },
          {
            role: "user",
            content: [
              { type: "input_text", text: userPrompt },
              { type: "input_image", image_url: dataUrl },
            ],
          },
        ],
      }),
    });
    if (!res.ok) {
      let detail = "";
      try {
        detail = await res.text();
      } catch {}
      throw new Error(detail || `AI OCR request failed with status ${res.status}`);
    }
    return extractOpenAIText(await res.json().catch(() => null));
  }

  if (runtime.protocol === "openai-chat") {
    const res = await fetch(runtime.endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${runtime.apiKey}`,
      },
      body: JSON.stringify({
        model: runtime.model,
        messages: [
          { role: "system", content: system },
          {
            role: "user",
            content: [
              { type: "text", text: userPrompt },
              { type: "image_url", image_url: { url: dataUrl } },
            ],
          },
        ],
      }),
    });
    if (!res.ok) {
      let detail = "";
      try {
        detail = await res.text();
      } catch {}
      throw new Error(detail || `AI OCR request failed with status ${res.status}`);
    }
    return extractOpenAIText(await res.json().catch(() => null));
  }

  if (runtime.protocol === "gemini") {
    const endpoint = `${runtime.endpoint.replace(/\/$/, "")}/${runtime.model}:generateContent?key=${encodeURIComponent(runtime.apiKey)}`;
    const res = await fetch(endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        contents: [{
          parts: [
            { text: `${system}\n\n${userPrompt}` },
            {
              inline_data: {
                mime_type: mimeType,
                data: base64,
              },
            },
          ],
        }],
      }),
    });
    if (!res.ok) {
      let detail = "";
      try {
        detail = await res.text();
      } catch {}
      throw new Error(detail || `AI OCR request failed with status ${res.status}`);
    }
    return extractGeminiText(await res.json().catch(() => null));
  }

  throw new Error(`Unsupported AI runtime protocol for OCR: ${runtime.protocol}`);
}

function extractXmlTagText(xmlText = "", tagName) {
  if (!xmlText || !tagName) return [];
  const parser = new DOMParser();
  const doc = parser.parseFromString(xmlText, "application/xml");
  return Array.from(doc.getElementsByTagName(tagName))
    .map((node) => node.textContent || "")
    .map((text) => text.replace(/\s+/g, " ").trim())
    .filter(Boolean);
}

function xmlDocumentHasParseError(doc) {
  return !!doc?.querySelector?.("parsererror");
}

function inferDocumentPhase(filename = "", text = "") {
  const name = filename.toLowerCase();
  const content = String(text || "").toLowerCase().slice(0, 2000);
  if (/strategy|vision|roadmap|executive|narrative|business.case|value.hypothesis|outcome/i.test(name + content)) return "discover";
  if (/architecture|design|capability|decision|agent|skill|workforce|blueprint/i.test(name + content)) return "design";
  if (/build|engineering|specification|test|api|deployment|mvp|pilot|sprint/i.test(name + content)) return "build";
  if (/governance|risk|compliance|audit|control|hitl|runbook|registry/i.test(name + content)) return "operate";
  if (/value|roi|benefits|optimization|lessons|maturity|qbr/i.test(name + content)) return "optimize";
  if (/roster|team|staffing|resource|people/i.test(name + content)) return "mobilise";
  return null;
}

let _pdfjsLibPromise = null;
let _mammothPromise = null;
let _jszipPromise = null;

async function loadPdfJsLib() {
  if (!_pdfjsLibPromise) {
    _pdfjsLibPromise = import("pdfjs-dist/legacy/build/pdf");
  }
  return _pdfjsLibPromise;
}

async function loadMammoth() {
  if (!_mammothPromise) {
    _mammothPromise = import("mammoth/mammoth.browser");
  }
  return _mammothPromise;
}

async function loadJsZip() {
  if (!_jszipPromise) {
    _jszipPromise = import("jszip");
  }
  return _jszipPromise;
}

async function extractPdfText(arrayBuffer) {
  const pdfjsLib = await loadPdfJsLib();
  const loadingTask = pdfjsLib.getDocument({
    data: arrayBuffer,
    useWorkerFetch: false,
    isEvalSupported: false,
    disableFontFace: true,
  });
  const pdf = await loadingTask.promise;
  const MAX_PAGES = 40;
  const pages = [];
  const totalPages = Math.min(pdf.numPages, MAX_PAGES);
  for (let pageNumber = 1; pageNumber <= totalPages; pageNumber += 1) {
    const page = await pdf.getPage(pageNumber);
    const content = await page.getTextContent();
    const lineMap = new Map();
    for (const item of content.items || []) {
      if (!item?.str?.trim()) continue;
      const y = Math.round((item.transform?.[5] || 0) / 5) * 5;
      if (!lineMap.has(y)) lineMap.set(y, []);
      lineMap.get(y).push(item.str);
    }
    const lines = Array.from(lineMap.entries())
      .sort((a, b) => b[0] - a[0])
      .map(([, parts]) => parts.join(" ").trim())
      .filter(Boolean);
    if (lines.length) {
      pages.push(totalPages > 1 ? `[Page ${pageNumber}]\n${lines.join("\n")}` : lines.join("\n"));
    }
  }
  const text = pages.join("\n\n");
  if (pdf.numPages > MAX_PAGES) {
    return `${text}\n\n[Note: Document has ${pdf.numPages} pages — first ${MAX_PAGES} extracted]`;
  }
  return text;
}

async function renderPdfPageAsPng(arrayBuffer) {
  const pdfjsLib = await loadPdfJsLib();
  const loadingTask = pdfjsLib.getDocument({ data: new Uint8Array(arrayBuffer) });
  const pdf = await loadingTask.promise;
  const page = await pdf.getPage(1);
  const viewport = page.getViewport({ scale: 2.0 });
  const canvas = document.createElement("canvas");
  canvas.width = viewport.width;
  canvas.height = viewport.height;
  const ctx = canvas.getContext("2d");
  await page.render({ canvasContext: ctx, viewport }).promise;
  return canvas.toDataURL("image/png");
}

async function extractDocxText(arrayBuffer) {
  const mammoth = (await loadMammoth()).default;
  let result;
  try {
    result = await mammoth.convertToHtml({ arrayBuffer });
  } catch {
    result = await mammoth.extractRawText({ arrayBuffer }).catch(() => ({ value: "" }));
    return (result?.value || "").replace(/\s+\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
  }
  const html = result?.value || "";
  if (!html.trim()) return "";
  const withHeadings = html
    .replace(/<h1[^>]*>(.*?)<\/h1>/gi, "\n\n# $1\n")
    .replace(/<h2[^>]*>(.*?)<\/h2>/gi, "\n\n## $1\n")
    .replace(/<h3[^>]*>(.*?)<\/h3>/gi, "\n\n### $1\n")
    .replace(/<h[4-6][^>]*>(.*?)<\/h[4-6]>/gi, "\n\n#### $1\n")
    .replace(/<li[^>]*>(.*?)<\/li>/gi, "\n- $1")
    .replace(/<\/p>/gi, "\n")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&nbsp;/g, " ").replace(/&#\d+;/g, "")
    .replace(/[ \t]+/g, " ")
    .replace(/\n{4,}/g, "\n\n\n")
    .trim();
  return withHeadings;
}

async function extractPptxText(arrayBuffer) {
  const JSZip = (await loadJsZip()).default;
  const zip = await JSZip.loadAsync(arrayBuffer);
  const allSlideFiles = Object.keys(zip.files)
    .filter((name) => /^ppt\/slides\/slide\d+\.xml$/i.test(name))
    .sort((a, b) => {
      const na = parseInt(a.match(/\d+/)?.[0] ?? "0", 10);
      const nb = parseInt(b.match(/\d+/)?.[0] ?? "0", 10);
      return na - nb;
    });
  const slideFiles = allSlideFiles.slice(0, 30);

  const parts = [];
  for (const [i, name] of slideFiles.entries()) {
    const xml = await zip.files[name].async("string");
    const doc = new DOMParser().parseFromString(xml, "application/xml");

    const texts = [...doc.getElementsByTagName("a:t")].map((node) => node.textContent).filter(Boolean);

    const slideNum = name.match(/slide(\d+)/)?.[1];
    const notesName = `ppt/notesSlides/notesSlide${slideNum}.xml`;
    let notes = "";
    if (zip.files[notesName]) {
      const nxml = await zip.files[notesName].async("string");
      const ndoc = new DOMParser().parseFromString(nxml, "application/xml");
      notes = [...ndoc.getElementsByTagName("a:t")].map((node) => node.textContent).filter(Boolean).join(" ");
    }

    let slide = `--- Slide ${i + 1} ---\n${texts.join(" ")}`;
    if (notes) slide += `\nNotes: ${notes}`;
    parts.push(slide);
  }

  const result = parts.join("\n\n");
  if (allSlideFiles.length > 30) return `${result}\n\n[Truncated at 30 slides]`;
  return result;
}

function spreadsheetColumnRefToIndex(ref = "") {
  const letters = String(ref).toUpperCase().replace(/[^A-Z]/g, "");
  if (!letters) return -1;
  let index = 0;
  for (const char of letters) {
    index = (index * 26) + (char.charCodeAt(0) - 64);
  }
  return index - 1;
}

function extractSpreadsheetCellText(cell, sharedStrings = []) {
  const type = cell.getAttribute("t");
  if (type === "inlineStr") {
    return extractXmlTagText(cell.innerHTML || "", "t").join(" ").trim();
  }
  if (type === "s") {
    const raw = cell.getElementsByTagName("v")[0]?.textContent || "";
    return sharedStrings[Number(raw)] || "";
  }
  if (type === "b") {
    const raw = cell.getElementsByTagName("v")[0]?.textContent || "";
    return raw === "1" ? "TRUE" : raw === "0" ? "FALSE" : raw;
  }
  return cell.getElementsByTagName("v")[0]?.textContent || "";
}

async function extractXlsxText(arrayBuffer) {
  const JSZip = (await loadJsZip()).default;
  const zip = await JSZip.loadAsync(arrayBuffer);
  const rosterHeaderPriority = [
    "name", "person", "employee", "resource",
    "title", "role", "designation", "position",
    "allocation", "capacity", "utilization", "fte",
    "workstream", "stream", "track",
    "phase", "stage",
    "responsibility", "responsibilities", "scope",
    "email", "phone", "location", "country",
  ];
  const scoreHeaderCell = (value = "") => {
    const normalized = String(value || "").trim().toLowerCase();
    if (!normalized) return 0;
    let score = 0;
    rosterHeaderPriority.forEach((token, index) => {
      if (normalized.includes(token)) score += (rosterHeaderPriority.length - index) * 3;
    });
    if (/^[a-z][a-z0-9 _/-]{1,40}$/i.test(normalized)) score += 1;
    return score;
  };
  const getHeaderPriority = (header = "", index = 0) => {
    const normalized = String(header || "").trim().toLowerCase();
    const hit = rosterHeaderPriority.findIndex((token) => normalized.includes(token));
    return hit >= 0 ? hit : rosterHeaderPriority.length + index;
  };
  const sharedStringsXml = await zip.files["xl/sharedStrings.xml"]?.async("string");
  const sharedStrings = [];
  if (sharedStringsXml) {
    const doc = new DOMParser().parseFromString(sharedStringsXml, "application/xml");
    for (const si of doc.getElementsByTagName("si")) {
      sharedStrings.push([...si.getElementsByTagName("t")].map((node) => node.textContent).join(""));
    }
  }

  const workbookXml = await zip.files["xl/workbook.xml"]?.async("string");
  const relsXml = await zip.files["xl/_rels/workbook.xml.rels"]?.async("string");
  const rIdToFile = {};
  if (relsXml) {
    const relsDoc = new DOMParser().parseFromString(relsXml, "application/xml");
    for (const rel of relsDoc.getElementsByTagName("Relationship")) {
      const target = rel.getAttribute("Target") ?? "";
      if (/worksheets\/sheet\d+\.xml/i.test(target)) {
        const normalizedTarget = target.replace(/^\//, "").replace(/^xl\//, "");
        rIdToFile[rel.getAttribute("Id")] = `xl/${normalizedTarget}`;
      }
    }
  }

  const MAX_SHEETS = 5;
  const MAX_ROWS = 300;
  const MAX_COLS = 26;
  const parts = [];
  const colRefToIndex = (ref = "") => {
    const letters = String(ref).replace(/\d/g, "").toUpperCase();
    let index = 0;
    for (const ch of letters) {
      index = index * 26 + (ch.charCodeAt(0) - 64);
    }
    return index - 1;
  };
  const orderedSheets = [];
  if (workbookXml) {
    const doc = new DOMParser().parseFromString(workbookXml, "application/xml");
    for (const sheet of doc.getElementsByTagName("sheet")) {
      const sheetLabel = sheet.getAttribute("name") ?? "Sheet";
      const relationId = sheet.getAttributeNS("http://schemas.openxmlformats.org/officeDocument/2006/relationships", "id")
        || sheet.getAttribute("r:id")
        || "";
      const file = rIdToFile[relationId];
      if (file && zip.files[file]) {
        orderedSheets.push({ file, label: sheetLabel });
      }
    }
  }
  const fallbackSheets = Object.keys(zip.files)
    .filter((name) => /^xl\/worksheets\/sheet\d+\.xml$/i.test(name))
    .sort((a, b) => {
      const na = parseInt(a.match(/\d+/)?.[0] ?? "0", 10);
      const nb = parseInt(b.match(/\d+/)?.[0] ?? "0", 10);
      return na - nb;
    })
    .map((file, index) => ({ file, label: `Sheet ${index + 1}` }));
  const allSheets = orderedSheets.length ? orderedSheets : fallbackSheets;
  const sheetsToProcess = allSheets.slice(0, MAX_SHEETS);

  for (const { file, label } of sheetsToProcess) {
    const xml = await zip.files[file].async("string");
    const doc = new DOMParser().parseFromString(xml, "application/xml");
    const allRows = [...doc.getElementsByTagName("row")];
    const rows = allRows.slice(0, MAX_ROWS);
    const structuredRows = rows.map((row) => {
      const rowValues = new Array(MAX_COLS).fill("");
      for (const cell of [...row.getElementsByTagName("c")]) {
        const colIdx = colRefToIndex(cell.getAttribute("r") ?? "");
        if (colIdx < 0 || colIdx >= MAX_COLS) continue;
        const type = cell.getAttribute("t");
        const value = cell.getElementsByTagName("v")[0]?.textContent ?? "";
        rowValues[colIdx] = type === "s"
          ? (sharedStrings[parseInt(value, 10)] ?? "")
          : (type === "str" || type === "inlineStr")
            ? (cell.getElementsByTagName("t")[0]?.textContent ?? value)
            : type === "b"
              ? (value === "1" ? "TRUE" : "FALSE")
            : value;
      }
      return rowValues.map((value) => String(value || "").trim());
    });
    const headerCandidates = structuredRows
      .slice(0, Math.min(10, structuredRows.length))
      .map((cells, index) => ({
        index,
        cells,
        score: cells.reduce((sum, cell) => sum + scoreHeaderCell(cell), 0),
        populatedCount: cells.filter(Boolean).length,
      }))
      .filter((candidate) => candidate.populatedCount >= 2);
    const bestHeaderCandidate = headerCandidates.sort((a, b) => b.score - a.score || b.populatedCount - a.populatedCount || a.index - b.index)[0];
    const headerIndex = bestHeaderCandidate?.score > 0 ? bestHeaderCandidate.index : 0;
    const headerRow = structuredRows[headerIndex] || [];
    const normalizedHeaders = headerRow.map((value, index) => value || `Column ${index + 1}`);
    const prioritizedHeaderIndexes = normalizedHeaders
      .map((header, index) => ({ index, priority: getHeaderPriority(header, index) }))
      .sort((a, b) => a.priority - b.priority)
      .map(({ index }) => index);
    const renderedRows = structuredRows.slice(headerIndex + 1).map((cells, index) => {
      const sheetRowNumber = headerIndex + index + 2;
      const populated = prioritizedHeaderIndexes
        .map((headerIndex) => `${normalizedHeaders[headerIndex]}: ${cells[headerIndex] || ""}`.trim())
        .filter((entry) => !entry.endsWith(":"));
      if (populated.length >= 2) return `Row ${sheetRowNumber} — ${populated.join(" | ")}`;
      return `Row ${sheetRowNumber} — ${(cells || []).filter(Boolean).join(" | ")}`.trim();
    }).filter(Boolean);
    parts.push([
      `=== ${label} ===`,
      normalizedHeaders.length ? `Columns: ${normalizedHeaders.join(" | ")}` : "",
      ...renderedRows,
    ].filter(Boolean).join("\n"));
    if (allRows.length > MAX_ROWS) parts.push(`[Truncated at ${MAX_ROWS} rows]`);
  }

  if (allSheets.length > MAX_SHEETS) parts.push(`[Truncated at ${MAX_SHEETS} sheets]`);
  return parts.join("\n\n");
}

async function extractZipText(arrayBuffer, hint = "") {
  const JSZip = (await loadJsZip()).default;
  const zip = await JSZip.loadAsync(arrayBuffer);
  const allReadable = Object.keys(zip.files)
    .filter((name) => !zip.files[name].dir && /\.(txt|md|csv|json|xml|yaml|yml|log|ts|js|jsx|tsx|py|sql|html|htm)$/i.test(name))
    .sort((a, b) => a.split("/").length - b.split("/").length || a.localeCompare(b));
  const readable = allReadable.slice(0, 15);

  const parts = [];
  for (const name of readable) {
    const text = await zip.files[name].async("string");
    const excerpt = text.slice(0, 2500);
    parts.push(`--- ${name} ---\n${excerpt}${text.length > 2500 ? "\n[truncated]" : ""}`);
  }
  if (allReadable.length > readable.length) {
    parts.push(`[${allReadable.length - readable.length} more text files not shown]`);
  }
  const result = parts.join("\n\n").slice(0, 20000);
  return result || "(no readable text files found in archive)";
}

async function extractOdtText(arrayBuffer) {
  const JSZip = (await loadJsZip()).default;
  const zip = await JSZip.loadAsync(arrayBuffer);
  const contentXml = await zip.files["content.xml"]?.async("string");
  if (!contentXml) return "";
  const doc = new DOMParser().parseFromString(contentXml, "application/xml");
  if (xmlDocumentHasParseError(doc)) return contentXml.slice(0, 15000);
  return [...doc.getElementsByTagName("*")]
    .filter((node) => node.localName === "h" || node.localName === "p")
    .map((node) => node.textContent?.trim())
    .filter(Boolean)
    .join("\n\n");
}

async function extractVsdxText(arrayBuffer) {
  const JSZip = (await loadJsZip()).default;
  const zip = await JSZip.loadAsync(arrayBuffer);
  const pageFiles = Object.keys(zip.files)
    .filter((name) => /^visio\/pages\/page\d+\.xml$/i.test(name))
    .sort((a, b) => {
      const na = parseInt(a.match(/\d+/)?.[0] ?? "0", 10);
      const nb = parseInt(b.match(/\d+/)?.[0] ?? "0", 10);
      return na - nb;
    })
    .slice(0, 10);

  const parts = [];
  for (const name of pageFiles) {
    const xml = await zip.files[name].async("string");
    const doc = new DOMParser().parseFromString(xml, "application/xml");
    if (xmlDocumentHasParseError(doc)) {
      parts.push(xml.slice(0, 4000));
      continue;
    }
    const labels = [...doc.getElementsByTagName("Text")]
      .map((node) => node.textContent?.trim())
      .filter(Boolean);
    if (labels.length) parts.push(labels.join("\n"));
  }
  return parts.join("\n\n");
}

async function extractEpubText(arrayBuffer) {
  const JSZip = (await loadJsZip()).default;
  const zip = await JSZip.loadAsync(arrayBuffer);
  const chapterFiles = Object.keys(zip.files)
    .filter((name) => /\.(xhtml|html|htm)$/i.test(name) && !/__MACOSX/.test(name))
    .sort((a, b) => {
      const numA = parseInt(a.match(/\d+/)?.[0] ?? "0", 10);
      const numB = parseInt(b.match(/\d+/)?.[0] ?? "0", 10);
      return numA - numB || a.localeCompare(b);
    })
    .slice(0, 8);

  const parts = [];
  for (const name of chapterFiles) {
    const html = await zip.files[name].async("string");
    const doc = new DOMParser().parseFromString(html, "text/html");
    doc.querySelectorAll("script, style, noscript, template").forEach((el) => el.remove());
    doc.querySelectorAll("p, div, h1, h2, h3, h4, h5, h6, li, br, tr").forEach((el) => el.insertAdjacentText("afterend", "\n"));
    const text = doc.body?.textContent ?? doc.documentElement?.textContent ?? "";
    const cleaned = text
      .replace(/[^\S\n]+/g, " ")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
    if (cleaned.length > 50) parts.push(cleaned);
  }
  return parts.join("\n\n");
}

function extractEmlText(rawText = "") {
  const decodeEmlBody = (body = "", encoding = "") => {
    const normalizedEncoding = encoding.toLowerCase();
    if (normalizedEncoding === "base64") {
      try {
        return atob(body.replace(/\s/g, ""));
      } catch {
        return body;
      }
    }
    if (normalizedEncoding === "quoted-printable") {
      return body
        .replace(/=\r?\n/g, "")
        .replace(/=([0-9A-Fa-f]{2})/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)));
    }
    return body;
  };
  const lines = rawText.split(/\r?\n/);
  const headers = [];
  let bodyStart = 0;
  for (let i = 0; i < lines.length; i += 1) {
    if (lines[i] === "") { bodyStart = i + 1; break; }
    headers.push(lines[i]);
  }
  const important = headers.filter((header) => /^(From|To|Cc|Subject|Date):/i.test(header));
  const encodingHeader = headers.find((header) => /^Content-Transfer-Encoding:/i.test(header));
  const encoding = encodingHeader?.split(":")[1]?.trim() ?? "";
  const body = lines.slice(bodyStart).join("\n")
    .replace(/^Content-[A-Za-z-]+:[^\n]*/gm, "")
    .replace(/^--[\w\-=.+/]+\s*$/gm, "")
    .trim();
  return `${important.join("\n")}\n\n${decodeEmlBody(body, encoding)}`.trim();
}

const IMAGE_EXTENSIONS = new Set([
  "jpg", "jpeg", "png", "gif", "webp",
  "heic", "heif", "bmp", "tiff", "tif", "ico", "avif",
]);

async function transcodeImageToPng(file) {
  const bitmap = await createImageBitmap(file);
  const canvas = document.createElement("canvas");
  canvas.width = bitmap.width;
  canvas.height = bitmap.height;
  const ctx = canvas.getContext("2d");
  ctx.drawImage(bitmap, 0, 0);
  return canvas.toDataURL("image/png");
}

async function readCopilotAttachment(file) {
  if (!file) return null;

  const ext = (file.name?.split(".").pop() ?? "").toLowerCase();
  const rawMime = file.type ?? "";
  const MIME_OVERRIDE = {
    heic: "image/jpeg",
    heif: "image/jpeg",
    bmp: "image/png",
    tiff: "image/png",
    tif: "image/png",
    avif: "image/avif",
    ico: "image/png",
  };
  const mime = MIME_OVERRIDE[ext] ?? rawMime;

  const compat = (text = "", type = "unknown", extras = {}) => {
    const normalizedText = typeof text === "string" ? normalizeCopilotCaptureText(text) : "";
    const excerptText = normalizedText.length > 60000
      ? [
          normalizedText.slice(0, 15000),
          normalizedText.slice(Math.floor(normalizedText.length * 0.4), Math.floor(normalizedText.length * 0.4) + 10000),
          normalizedText.slice(-10000),
        ].join("\n...[excerpt]...\n")
      : normalizedText;
    const usableText = !!normalizedText.trim() && type !== "unsupported" && type !== "error" && type !== "media";
    const readMode = extras.readMode || (
      type === "error" ? "parse-error"
        : usableText ? (type === "image" ? "ocr-text" : type === "zip" ? "zip-text" : "inline-text")
          : type === "unsupported" || type === "media" ? "reference-only"
            : "empty-text"
    );
    return {
      text: excerptText,
      fullText: normalizedText,
      excerptText,
      type,
      name: file.name,
      usableText,
      readMode,
      parseError: extras.parseError || "",
      suggestedPhase: extras.suggestedPhase || inferDocumentPhase(file.name, normalizedText),
    };
  };

  if (file.size > 50 * 1024 * 1024) {
    return compat(
      `[File too large: ${file.name} (${(file.size / 1e6).toFixed(1)} MB) — reduce to under 50 MB for extraction]`,
      "oversized",
      { readMode: "reference-only" }
    );
  }

  try {
    if (ext === "svg" || mime === "image/svg+xml") {
      const raw = await file.text();
      const doc = new DOMParser().parseFromString(raw, "image/svg+xml");
      const text = xmlDocumentHasParseError(doc)
        ? raw.slice(0, 15000)
        : (doc.documentElement?.textContent?.replace(/\s+/g, " ").trim() ?? raw.slice(0, 15000));
      return compat(text || raw.slice(0, 15000), "svg");
    }

    if (IMAGE_EXTENSIONS.has(ext) || mime.startsWith("image/")) {
      let dataUrl = "";
      if (["heic", "heif"].includes(ext)) {
        return compat("", "image", {
          readMode: "reference-only",
          parseError: `${ext}-unsupported: HEIC/HEIF images are not browser-transcodable here. Re-save as PNG or JPEG to enable extraction.`,
        });
      }
      if (["bmp", "tiff", "tif", "ico"].includes(ext)) {
        try {
          dataUrl = await transcodeImageToPng(file);
        } catch {
          return compat("", "image", {
            readMode: "reference-only",
            parseError: `${ext}-transcode-failed: could not convert image to PNG for OCR. Re-save as PNG or JPEG to enable extraction.`,
          });
        }
      } else {
        dataUrl = await fileToDataUrl(file);
      }
      const ocrText = await requestAIImageText(file, dataUrl);
      return compat(ocrText, "image");
    }

    if (ext === "pdf" || mime === "application/pdf") {
      const arrayBuffer = await file.arrayBuffer();
      let text = await extractPdfText(arrayBuffer);
      if (!text || text.trim().length < 80) {
        try {
          const pngDataUrl = await renderPdfPageAsPng(arrayBuffer);
          const syntheticFile = new File([], file.name, { type: "image/png" });
          text = await requestAIImageText(syntheticFile, pngDataUrl);
        } catch {}
      }
      return compat(text, "pdf");
    }

    if (ext === "csv" || mime === "text/csv" || mime === "application/csv") {
      const raw = await file.text();
      const allLines = raw.split(/\r?\n/);
      const lines = allLines.slice(0, 500);
      const truncated = allLines.length > 500;
      return compat(
        lines.join("\n") + (truncated ? `\n[Truncated at 500 rows — ${allLines.length} total]` : ""),
        "csv"
      );
    }

    if (["docx", "doc"].includes(ext)
      || ["application/vnd.openxmlformats-officedocument.wordprocessingml.document", "application/msword"].includes(mime)) {
      try {
        const text = await extractDocxText(await file.arrayBuffer());
        return compat(text, "docx");
      } catch {
        return compat(`[Could not extract text from ${file.name} — legacy .doc format may not be supported]`, "docx", {
          readMode: "reference-only",
        });
      }
    }

    if (["pptx", "ppt"].includes(ext)
      || ["application/vnd.openxmlformats-officedocument.presentationml.presentation", "application/vnd.ms-powerpoint"].includes(mime)) {
      try {
        const text = await extractPptxText(await file.arrayBuffer());
        return compat(text, "pptx");
      } catch {
        return compat(`[Could not extract text from ${file.name} — legacy .ppt format may not be supported]`, "pptx", {
          readMode: "reference-only",
        });
      }
    }

    if (["xlsx", "xls", "xlsm"].includes(ext)
      || ["application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "application/vnd.ms-excel"].includes(mime)) {
      try {
        const text = await extractXlsxText(await file.arrayBuffer());
        return compat(text, "xlsx");
      } catch {
        return compat(`[Could not extract text from ${file.name} — legacy .xls format may not be supported]`, "xlsx", {
          readMode: "reference-only",
        });
      }
    }

    if (ext === "odt" || mime === "application/vnd.oasis.opendocument.text") {
      const text = await extractOdtText(await file.arrayBuffer());
      return compat(text, "odt");
    }

    if (["vsdx", "vsd"].includes(ext)
      || ["application/vnd.ms-visio.drawing", "application/vnd.visio"].includes(mime)) {
      const text = await extractVsdxText(await file.arrayBuffer());
      return compat(text, "vsdx");
    }

    if (ext === "epub" || mime === "application/epub+zip") {
      const text = await extractEpubText(await file.arrayBuffer());
      return compat(text, "epub");
    }

    if (ext === "eml" || mime === "message/rfc822") {
      const raw = await file.text();
      return compat(extractEmlText(raw), "eml");
    }

    if (ext === "msg") {
      return compat(
        `[Outlook MSG file: ${file.name} — save as .eml or copy the email body as text to enable extraction]`,
        "msg",
        { readMode: "reference-only" }
      );
    }

    if (ext === "zip" || ["application/zip", "application/x-zip-compressed"].includes(mime)) {
      const text = await extractZipText(await file.arrayBuffer(), file.name);
      return compat(text, "zip");
    }

    if (["7z", "tar", "gz", "rar"].includes(ext)) {
      return compat(
        `[Archive format not supported: ${file.name} — convert to .zip to enable extraction]`,
        "unsupported",
        { readMode: "reference-only" }
      );
    }

    if (ext === "json" || mime === "application/json") {
      const raw = await file.text();
      try {
        const parsed = JSON.parse(raw);
        return compat(JSON.stringify(parsed, null, 2).slice(0, 15000), "json");
      } catch {
        return compat(raw.slice(0, 15000), "json");
      }
    }

    if (["xml", "xhtml"].includes(ext) || mime === "application/xml" || mime === "text/xml" || mime === "application/xhtml+xml") {
      const raw = await file.text();
      const doc = new DOMParser().parseFromString(raw, "application/xml");
      const text = xmlDocumentHasParseError(doc)
        ? raw.slice(0, 15000)
        : (doc.documentElement?.textContent?.replace(/\s+/g, " ").trim() ?? raw.slice(0, 15000));
      return compat(text, "xml");
    }

    if (["html", "htm"].includes(ext) || mime === "text/html") {
      const raw = await file.text();
      const doc = new DOMParser().parseFromString(raw, "text/html");
      doc.querySelectorAll("script, style, noscript, template").forEach((el) => el.remove());
      const text = doc.body?.textContent?.replace(/\s+/g, " ").trim() ?? raw.slice(0, 15000);
      return compat(text, "html");
    }

    if (["yaml", "yml", "toml", "ini", "env", "cfg", "conf"].includes(ext)) {
      const raw = await file.text();
      return compat(raw.slice(0, 15000), "config");
    }

    if (["md", "txt", "rst", "log", "rtf", "tex"].includes(ext) || mime.startsWith("text/")) {
      const raw = await file.text();
      return compat(raw.slice(0, 20000), "text");
    }

    if (["ts", "tsx", "js", "jsx", "py", "java", "cs", "cpp", "c", "go", "rb", "php", "swift", "kt", "rs", "sh", "bash", "sql", "graphql", "proto"].includes(ext)) {
      const raw = await file.text();
      return compat(raw.slice(0, 20000), "code");
    }

    if (mime.startsWith("audio/") || mime.startsWith("video/")) {
      return compat(`[Media file: ${file.name} — content not extractable]`, "media", { readMode: "reference-only" });
    }

    try {
      const raw = await file.text();
      if (raw && /[a-zA-Z]{3}/.test(raw)) {
        return compat(raw.slice(0, 15000), "unknown");
      }
    } catch {}

    return compat(`[Unsupported file type: ${file.name} (${mime || ext})]`, "unsupported", { readMode: "reference-only" });
  } catch (error) {
    return compat(`[Error reading ${file.name}: ${error?.message ?? "unknown error"}]`, "error", {
      readMode: "parse-error",
      parseError: `${ext || "unknown"}-parse-error: ${error?.message ?? "unknown error"}`,
    });
  }
}

async function callAI(system, user, onChunk) {
  const text = await requestAIText(system, user);
  if (!text) {
    throw new Error("AI response was empty.");
  }
  onChunk?.(text);
}

const callClaude = callAI;

function detectCopilotRequestMode(userText = "") {
  const text = String(userText || "").toLowerCase();
  if (/\b(draft|generate|create|write|produce|artifact)\b/.test(text)) {
    return {
      mode: "artifact",
      responseInstructions: `Max ${AI_COPILOT_RESPONSE_MAX_WORDS_ARTIFACT} words, use structured sections with headers.`,
      maxWords: AI_COPILOT_RESPONSE_MAX_WORDS_ARTIFACT,
    };
  }
  if (/\b(explain|why|what is|how does|how do|how to)\b/.test(text)) {
    return {
      mode: "explain",
      responseInstructions: `Max ${AI_COPILOT_RESPONSE_MAX_WORDS_EXPLAIN} words.`,
      maxWords: AI_COPILOT_RESPONSE_MAX_WORDS_EXPLAIN,
    };
  }
  return {
    mode: "conversational",
    responseInstructions: `Max ${AI_COPILOT_RESPONSE_MAX_WORDS_CONVERSATIONAL} words.`,
    maxWords: AI_COPILOT_RESPONSE_MAX_WORDS_CONVERSATIONAL,
  };
}

