function createMethodologyBaseObject(name = "", type = "", phaseCreated = "", overrides = {}) {
  return {
    id: overrides.id || `${type || "obj"}-${Math.random().toString(36).slice(2, 10)}`,
    name: name || overrides.name || "",
    type: type || overrides.type || "",
    phaseCreated: phaseCreated || overrides.phaseCreated || "",
    owner: overrides.owner || "",
    evidenceStrength: overrides.evidenceStrength || "stated",
    linkedObjects: Array.isArray(overrides.linkedObjects) ? overrides.linkedObjects : [],
    assumptions: Array.isArray(overrides.assumptions) ? overrides.assumptions : [],
    status: overrides.status || "active",
    notes: overrides.notes || "",
    reusable: !!overrides.reusable,
    sourceProgramId: overrides.sourceProgramId || "",
    importedFrom: overrides.importedFrom || "",
    reuseConstraints: overrides.reuseConstraints || "",
    version: overrides.version || 1,
    lastModifiedDate: overrides.lastModifiedDate || stampNow(),
    lastModifiedBy: overrides.lastModifiedBy || "ADAM",
    ...overrides,
  };
}

