function getAutonomyMeta(levelId = "L0") {
  return ADAM_METHODOLOGY.autonomyLevels.find((level) => level.id === levelId) || ADAM_METHODOLOGY.autonomyLevels[0];
}

function highestAutonomyLevelAcrossCapabilities(project) {
  const caps = project?.data?.design?.capabilities || project?.data?.capabilities || [];
  const order = ADAM_METHODOLOGY.autonomyLevels.map((level) => level.id);
  return caps.reduce((max, capability) => {
    const next = capability?.autonomyLevel || "L0";
    return order.indexOf(next) > order.indexOf(max) ? next : max;
  }, "L0");
}

