function buildTestingCoverageSummary(testing = createEmptyTestingData()) {
  const suites = Array.isArray(testing.testSuites) ? testing.testSuites : [];
  const avg = (items, field = "coverageScore") => {
    if (!items.length) return 0;
    return Math.round(items.reduce((sum, item) => sum + Number(item?.[field] || 0), 0) / items.length);
  };
  const byType = (type) => suites.filter((suite) => (suite.testTypesIncluded || []).includes(type) || suite.testType === type || suite.name?.toLowerCase().includes(type));
  const functional = avg(byType("functional"), "coverageScore");
  const safety = Math.max(avg(byType("safety"), "safetyRuleCoverage"), avg(byType("safety"), "coverageScore"));
  const adversarial = Math.max(avg(byType("adversarial"), "adversarialCoverage"), avg(byType("adversarial"), "coverageScore"));
  const nfr = Math.max(avg(byType("performance"), "nfrCoverage"), avg(byType("performance"), "coverageScore"));
  const compliance = avg(byType("compliance"), "coverageScore");
  const overall = Math.round((functional * 0.25) + (safety * 0.2) + (adversarial * 0.2) + (nfr * 0.2) + (compliance * 0.15));
  return { functional, safety, adversarial, nfr, compliance, overall };
}

function buildPhaseTestingActivitiesSnapshot(phaseId, testing = createEmptyTestingData()) {
  const normalizedPhase = phaseId === "operate" ? "govern" : phaseId;
  const suites = (testing.testSuites || []).filter((suite) => (suite.phase || "").toLowerCase() === normalizedPhase);
  const suiteIds = new Set(suites.map((suite) => suite.id));
  const testCaseIds = new Set(suites.flatMap((suite) => suite.testCases || []));
  const results = (testing.testResults || []).filter((result) => suiteIds.has(result.linkedTestSuite) || testCaseIds.has(result.linkedTestCase));
  const testsPassed = results.filter((result) => result.outcome === "pass").length;
  const openFailures = [...new Set(results.filter((result) => result.outcome === "fail").map((result) => result.linkedTestCase).filter(Boolean))];
  return {
    testsDesigned: [...testCaseIds].length,
    testsExecuted: results.length,
    testsPassed,
    coverage: suites.length ? Math.round(suites.reduce((sum, suite) => sum + Number(suite.coverageScore || 0), 0) / suites.length) : 0,
    openFailures,
  };
}

