/* ─── Shared micro-components ────────────────────────────────────── */

function Pill({ children, color = T.blue600, bg = T.blue50, border }) {
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 5,
      fontSize: 10.25, fontWeight: 700, letterSpacing: "0.02em", textTransform: "none",
      color, background: bg, border: `1px solid ${border || color + "30"}`,
      borderRadius: 999, padding: "5px 10px", whiteSpace: "nowrap",
      boxShadow: `${T.shadowInset}, 0 6px 14px rgba(15,23,42,0.04)`,
    }}>{children}</span>
  );
}

function StatusPill({ status }) {
  const map = {
    green:  { label: "On Track",  color: T.green500, bg: T.green50 },
    yellow: { label: "At Risk",   color: T.amber500, bg: T.amber50 },
    red:    { label: "Blocked",   color: T.red500,   bg: T.red50   },
  };
  const s = map[status] || map.yellow;
  return <Pill color={s.color} bg={s.bg}>{s.label}</Pill>;
}

function ReadinessBar({ value, height = 5 }) {
  const c = T.purple500;
  return (
    <div style={{ background: T.gray200, borderRadius: 99, height, overflow: "hidden", width: "100%" }}>
      <div style={{ background: c, width: `${value}%`, height: "100%", borderRadius: 99, transition: "width 0.6s cubic-bezier(.4,0,.2,1)" }} />
    </div>
  );
}

function ScoreRing({ value, size = 48, stroke = 4 }) {
  const r = (size - stroke) / 2;
  const circ = 2 * Math.PI * r;
  const offset = circ * (1 - value / 100);
  const c = value >= 75 ? T.green500 : value >= 50 ? T.amber500 : T.red500;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ transform: "rotate(-90deg)" }}>
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={T.gray200} strokeWidth={stroke} />
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={c} strokeWidth={stroke}
        strokeDasharray={circ} strokeDashoffset={offset} strokeLinecap="round"
        style={{ transition: "stroke-dashoffset 0.8s cubic-bezier(.4,0,.2,1)" }} />
      <text x={size/2} y={size/2} textAnchor="middle" dominantBaseline="central"
        style={{ fontSize: size * 0.24, fontWeight: 700, fill: c, transform: "rotate(90deg)", transformOrigin: `${size/2}px ${size/2}px` }}>
        {value}%
      </text>
    </svg>
  );
}

function Tooltip({ tip, children }) {
  const [show, setShow] = useState(false);
  const [coords, setCoords] = useState({ top: 0, left: 0, placement: "top" });
  const [active, setActive] = useState(false);
  const anchorRef = useRef(null);

  useEffect(() => {
    if (!show) return;
    const updatePosition = () => {
      const rect = anchorRef.current?.getBoundingClientRect();
      if (!rect) return;
      const preferBottom = rect.top < 84;
      setCoords({
        top: preferBottom ? rect.bottom + 10 : rect.top - 10,
        left: Math.min(window.innerWidth - 24, Math.max(24, rect.left + rect.width / 2)),
        placement: preferBottom ? "bottom" : "top",
      });
    };
    updatePosition();
    window.addEventListener("scroll", updatePosition, true);
    window.addEventListener("resize", updatePosition);
    return () => {
      window.removeEventListener("scroll", updatePosition, true);
      window.removeEventListener("resize", updatePosition);
    };
  }, [show]);

  const popup = show ? (
    <span
      style={{
        position: "fixed",
        top: coords.top,
        left: coords.left,
        transform: coords.placement === "top" ? "translate(-50%, -100%)" : "translate(-50%, 0)",
        background: "linear-gradient(180deg, rgba(20,29,52,0.98) 0%, rgba(12,19,37,0.98) 100%)",
        color: T.white,
        fontSize: 11,
        fontWeight: 600,
        lineHeight: 1.55,
        letterSpacing: "0.01em",
        padding: "9px 12px",
        borderRadius: 12,
        border: "1px solid rgba(255,255,255,0.10)",
        maxWidth: 260,
        whiteSpace: "normal",
        boxShadow: "0 18px 40px rgba(15,23,42,0.28), inset 0 1px 0 rgba(255,255,255,0.06)",
        zIndex: 1200,
        pointerEvents: "none",
        textAlign: "center",
      }}
    >
      {tip}
    </span>
  ) : null;

  return (
    <span
      ref={anchorRef}
      style={{ position: "relative", display: "inline-flex" }}
      onMouseEnter={() => { setShow(true); setActive(true); }}
      onMouseLeave={() => { setShow(false); setActive(false); }}
      onFocus={() => { setShow(true); setActive(true); }}
      onBlur={() => { setShow(false); setActive(false); }}
    >
      <span style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        transform: active ? "translateY(-1px)" : "translateY(0)",
        transition: "transform 0.16s ease, filter 0.16s ease",
        filter: active ? "brightness(1.03)" : "none",
      }}>
        {children}
      </span>
      {typeof document !== "undefined" && popup ? createPortal(popup, document.body) : popup}
    </span>
  );
}

function InfoIcon({ tip }) {
  return (
    <Tooltip tip={tip}>
      <span style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        width: 17,
        height: 17,
        borderRadius: "50%",
        background: "rgba(244,247,252,0.98)",
        border: `1px solid ${T.blue100}`,
        boxShadow: "0 6px 14px rgba(15,23,42,0.06), inset 0 1px 0 rgba(255,255,255,0.82)",
        fontSize: 9.5,
        fontWeight: 900,
        color: T.blue700,
        cursor: "help",
        lineHeight: 1,
        userSelect: "none",
      }}>?</span>
    </Tooltip>
  );
}

function normalizePlanningField(value) {
  return value === "To be defined through ADAM" ? "" : (value || "");
}

function Card({ children, style, hover, onClick, highlight }) {
  const [hov, setHov] = useState(false);
  return (
    <div onClick={onClick}
      onMouseEnter={() => setHov(true)} onMouseLeave={() => setHov(false)}
      style={{
        background: "linear-gradient(180deg, rgba(255,255,255,0.998) 0%, rgba(247,249,252,0.992) 100%)",
        border: `1px solid ${highlight ? T.blue300 : hov && hover ? T.blue100 : T.panelBorder}`,
        borderRadius: 22, padding: "18px 20px",
        boxShadow: hov && hover
          ? "0 26px 54px rgba(15,23,42,0.11), 0 12px 28px rgba(15,23,42,0.06), inset 0 1px 0 rgba(255,255,255,0.94)"
          : "0 16px 34px rgba(15,23,42,0.06), 0 6px 14px rgba(15,23,42,0.035), inset 0 1px 0 rgba(255,255,255,0.94)",
        cursor: onClick ? "pointer" : "default",
        transition: "transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease",
        transform: hov && hover ? "translateY(-2px)" : "translateY(0)",
        ...style,
      }}>{children}</div>
  );
}

function BrandMark({ size = 28, compact }) {
  return (
    <div style={{
      width: size,
      height: size,
      borderRadius: Math.round(size * 0.28),
      background: `linear-gradient(145deg, ${T.blue600} 0%, ${T.blue800} 100%)`,
      boxShadow: `inset 0 1px 0 rgba(255,255,255,0.22), 0 ${Math.max(4, Math.round(size * 0.18))}px ${Math.max(12, Math.round(size * 0.54))}px rgba(46,58,135,0.28)`,
      position: "relative",
      flexShrink: 0,
      overflow: "hidden",
    }}>
      <div style={{
        position: "absolute",
        inset: 0,
        background: "radial-gradient(circle at 20% 18%, rgba(255,255,255,0.24), transparent 32%)",
      }} />
      <div style={{
        position: "absolute",
        left: compact ? "31%" : "29%",
        top: compact ? "22%" : "18%",
        width: compact ? "38%" : "42%",
        height: compact ? "56%" : "62%",
        borderLeft: `${Math.max(3, Math.round(size * 0.12))}px solid ${T.white}`,
        borderRight: `${Math.max(3, Math.round(size * 0.12))}px solid ${T.white}`,
        transform: "skewX(-24deg)",
        opacity: 0.98,
      }} />
      <div style={{
        position: "absolute",
        right: compact ? "-6%" : "-2%",
        bottom: compact ? "-10%" : "-6%",
        width: compact ? "45%" : "48%",
        height: compact ? "45%" : "48%",
        borderRadius: "50%",
        background: T.cyan500,
        opacity: 0.95,
      }} />
    </div>
  );
}

function KpiCard({ label, value, sub, delta, color, tip, icon, onClick }) {
  const accentColor = color || T.blue600;
  const isGreen  = accentColor === T.green500;
  const isAmber  = accentColor === T.amber500;
  const isRed    = accentColor === T.red500;
  const isCyan   = accentColor === T.cyan500;
  const isPurple = accentColor === T.purple500;
  const isBlue   = accentColor === T.blue600 || accentColor === T.blue700 || accentColor === T.blue800 || accentColor === T.blue900;
  const bg = isGreen ? T.green50 : isAmber ? T.amber50 : isRed ? T.red50
           : isCyan ? "#E0F7FA" : isPurple ? T.purple100 : T.blue50;
  const labelColor = isGreen ? "#065F46" : isAmber ? "#92400E" : isRed ? "#991B1B"
                   : isCyan ? "#0E4D5C" : isPurple ? "#4C1D95" : T.blue700;
  const valueColor = isGreen ? "#022C22" : isAmber ? "#451A03" : isRed ? "#4C0519"
                   : isCyan ? "#083344" : isPurple ? "#2E1065" : T.blue900;
  // For custom/arbitrary hex accent colors (e.g. industry accelerator colors)
  const useCustom = !isGreen && !isAmber && !isRed && !isCyan && !isPurple && !isBlue;
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
      appearance: "none",
      textAlign: "left",
      width: "100%",
      minWidth: 0,
      background: useCustom ? `${accentColor}14` : bg,
      borderRadius: 18,
      border: `1px solid ${useCustom ? accentColor + "22" : accentColor + "1A"}`,
      padding: "15px 16px 14px",
      boxShadow: `${T.shadowSm}, ${T.shadowInset}`,
      cursor: onClick ? "pointer" : "default",
      transition: "transform 0.16s ease, box-shadow 0.16s ease, border-color 0.16s ease",
    }}
      onMouseEnter={(e) => {
        if (!onClick) return;
        e.currentTarget.style.transform = "translateY(-1px)";
        e.currentTarget.style.boxShadow = T.shadowMd;
      }}
      onMouseLeave={(e) => {
        if (!onClick) return;
        e.currentTarget.style.transform = "translateY(0)";
        e.currentTarget.style.boxShadow = `${T.shadowSm}, ${T.shadowInset}`;
      }}
    >
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 9 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, minWidth: 0 }}>
          {icon && (
            <div style={{
              width: 28, height: 28, borderRadius: 10,
              background: useCustom ? accentColor + "18" : "rgba(255,255,255,0.98)",
              border: `1px solid ${useCustom ? accentColor + "26" : accentColor + "18"}`,
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: 12,
              boxShadow: T.shadowInset,
            }}>{icon}</div>
          )}
          <div style={{ fontSize: 10, fontWeight: 800, color: useCustom ? accentColor : labelColor, textTransform: "uppercase", letterSpacing: "0.08em" }}>{label}</div>
        </div>
        {tip && <InfoIcon tip={tip} />}
      </div>
      <div style={{ width: 36, height: 3, borderRadius: 999, background: accentColor, marginBottom: 10, opacity: 0.9 }} />
      <div style={{ fontSize: 21, fontWeight: 900, color: useCustom ? accentColor : valueColor, letterSpacing: "-0.8px", lineHeight: 1 }}>{value}</div>
      {(sub || delta) && (
        <div style={{ marginTop: 8, display: "flex", alignItems: "center", gap: 5, flexWrap: "wrap" }}>
          {delta && <span style={{ fontSize: 10.5, fontWeight: 700, color: useCustom ? accentColor : labelColor }}>{delta}</span>}
          {sub && <span style={{ fontSize: 10.5, color: useCustom ? accentColor : labelColor, opacity: 0.75 }}>{sub}</span>}
        </div>
      )}
      {onClick && (
        <div style={{ marginTop: 9, fontSize: 10, fontWeight: 700, color: useCustom ? accentColor : labelColor, opacity: 0.72 }}>
          Open details →
        </div>
      )}
    </button>
  );
}

