function useAsyncAction(actionFn, { onSuccess, onError, errorLabel = "Action", undoLabel } = {}) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const run = useCallback(async (...args) => {
    if (loading) return;
    setLoading(true);
    setError(null);
    const previousUndoLabel = _pendingUndoLabel;
    _pendingUndoLabel = undoLabel || errorLabel || "Action";
    try {
      const result = await actionFn(...args);
      onSuccess?.(result);
      return result;
    } catch (err) {
      const message = err?.message || `${errorLabel} could not be completed.`;
      setError(message);
      onError?.(err);
      console.error(`${errorLabel} failed`, err);
    } finally {
      _pendingUndoLabel = previousUndoLabel;
      setLoading(false);
    }
  }, [loading, actionFn, errorLabel, onSuccess, onError, undoLabel]);

  return { run, loading, error, clearError: () => setError(null) };
}

function useAsyncActions() {
  const [loadingKeys, setLoadingKeys] = useState(new Set());
  const [errors, setErrors] = useState({});

  const run = useCallback(async (key, actionFn, { onSuccess, onError, undoLabel } = {}) => {
    if (loadingKeys.has(key)) return;
    setLoadingKeys((prev) => new Set([...prev, key]));
    setErrors((prev) => {
      const next = { ...prev };
      delete next[key];
      return next;
    });
    const previousUndoLabel = _pendingUndoLabel;
    _pendingUndoLabel = undoLabel || key;
    try {
      const result = await actionFn();
      onSuccess?.(result);
      return result;
    } catch (err) {
      const message = err?.message || `${key} could not be completed.`;
      setErrors((prev) => ({ ...prev, [key]: message }));
      onError?.(err);
      console.error(`${key} failed`, err);
    } finally {
      _pendingUndoLabel = previousUndoLabel;
      setLoadingKeys((prev) => {
        const next = new Set(prev);
        next.delete(key);
        return next;
      });
    }
  }, [loadingKeys]);

  return {
    run,
    isLoading: (key) => loadingKeys.has(key),
    getError: (key) => errors[key] || null,
    clearError: (key) => setErrors((prev) => {
      const next = { ...prev };
      delete next[key];
      return next;
    }),
    anyLoading: loadingKeys.size > 0,
  };
}

function useUndoState() {
  const [, setTick] = useState(0);
  const forceUpdate = useCallback(() => setTick((value) => value + 1), []);
  const projectId = _activeProjectId;

  const undo = useCallback(() => {
    if (applyUndo(projectId)) {
      forceUpdate();
      return true;
    }
    return false;
  }, [projectId, forceUpdate]);

  const redo = useCallback(() => {
    if (applyRedo(projectId)) {
      forceUpdate();
      return true;
    }
    return false;
  }, [projectId, forceUpdate]);

  return {
    undo,
    redo,
    canUndo: canUndo(projectId),
    canRedo: canRedo(projectId),
    lastActionLabel: getLastActionLabel(projectId),
  };
}

function AsyncButton({
  children,
  onClick,
  loading = false,
  error = null,
  disabled = false,
  variant = "ghost",
  hasExisting = false,
  icon,
  onClearError,
  style: extraStyle = {},
}) {
  const [hov, setHov] = useState(false);

  const variantStyles = {
    ghost: {
      color: disabled ? T.gray400 : hasExisting ? T.purple600 : T.blue600,
      background: hov && !disabled ? (hasExisting ? T.purple50 : "rgba(255,255,255,0.99)") : "rgba(255,255,255,0.88)",
      border: `1px solid ${hov && !disabled ? (hasExisting ? T.purple200 : T.blue200) : error ? T.red300 : T.gray200}`,
      borderRadius: 999,
      minHeight: 36,
      padding: "0 15px",
      fontSize: 12,
      fontWeight: 700,
      boxShadow: `${T.shadowInset}, 0 8px 18px rgba(15,23,42,0.04)`,
    },
    primary: {
      color: T.white,
      background: disabled ? T.gray300 : hov ? `linear-gradient(180deg, ${T.blue700} 0%, ${T.blue800} 100%)` : `linear-gradient(180deg, ${T.blue600} 0%, ${T.blue700} 100%)`,
      border: `1px solid ${T.blue700}`,
      borderRadius: 999,
      minHeight: 36,
      padding: "0 15px",
      fontSize: 12,
      fontWeight: 700,
      boxShadow: !disabled ? T.shadowBlue : "none",
    },
    generate: {
      display: "flex",
      alignItems: "center",
      gap: 8,
      width: "100%",
      textAlign: "left",
      fontSize: 12,
      fontWeight: 600,
      color: loading ? T.gray400 : hasExisting ? T.purple700 : T.blue700,
      background: hov && !loading ? (hasExisting ? T.purple50 : T.blue50) : T.gray50,
      border: `1px solid ${error ? T.red300 : hov && !loading ? (hasExisting ? T.purple200 : T.blue200) : T.gray200}`,
      borderRadius: 12,
      padding: "11px 13px",
      marginBottom: 6,
      boxShadow: "0 10px 18px rgba(15,23,42,0.035), inset 0 1px 0 rgba(255,255,255,0.9)",
    },
    inline: {
      color: disabled ? T.gray400 : hasExisting ? T.purple600 : T.blue700,
      background: hov && !disabled ? (hasExisting ? T.purple50 : T.blue50) : "transparent",
      border: `1px solid ${hov && !disabled ? (hasExisting ? T.purple200 : T.blue200) : error ? T.red300 : T.gray200}`,
      borderRadius: 8,
      padding: "0 13px",
      height: 34,
      fontSize: 12,
      fontWeight: 700,
    },
  };

  const effectiveIcon = loading ? "⟳"
    : error ? "⚠"
    : hasExisting ? "↻"
    : icon || (variant === "generate" ? "✦" : undefined);

  const effectiveLabel = loading
    ? (variant === "generate" ? "Working…" : typeof children === "string" ? `${children}…` : children)
    : error
      ? (
        <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <span style={{ color: T.red500, fontSize: 10, fontWeight: 700 }}>Failed</span>
          <span>{children}</span>
          {onClearError ? (
            <span
              role="button"
              tabIndex={0}
              onClick={(e) => { e.stopPropagation(); onClearError(); }}
              style={{ fontSize: 10, color: T.gray400, cursor: "pointer", marginLeft: 4 }}
            >✕</span>
          ) : null}
        </span>
      )
      : hasExisting && variant === "generate"
        ? `Refine ${children}`
        : children;

  return (
    <button
      type="button"
      onClick={error ? (onClearError || onClick) : onClick}
      disabled={disabled || loading}
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}
      title={error || undefined}
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 6,
        cursor: disabled || loading ? "not-allowed" : "pointer",
        opacity: disabled ? 0.5 : 1,
        transition: "transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease, background 0.15s ease",
        transform: hov && !(disabled || loading) ? "translateY(-1px)" : "translateY(0)",
        ...(variantStyles[variant] || variantStyles.ghost),
        ...extraStyle,
      }}
    >
      {effectiveIcon ? (
        <span style={{ fontSize: variant === "generate" ? 13 : 12, color: error ? T.red500 : loading ? T.gray300 : hasExisting ? T.purple500 : undefined, flexShrink: 0 }}>
          {effectiveIcon}
        </span>
      ) : null}
      <span style={{ flex: variant === "generate" ? 1 : undefined }}>{effectiveLabel}</span>
      {variant === "generate" && !loading && !error ? (
        <span style={{ fontSize: 10, color: hasExisting ? T.purple400 : T.gray400 }}>{hasExisting ? "Refine" : "AI"}</span>
      ) : null}
    </button>
  );
}

