function ADAMCompilerPanel({ defaultTargetId }) {
  const targets = getCompilerTargets();
  const [targetId, setTargetId] = useState(defaultTargetId || getSuggestedTargetPhase());
  const [loading, setLoading] = useState(false);
  const [sequenceLoading, setSequenceLoading] = useState(false);
  const [status, setStatus] = useState("");
  const [activeArtifact, setActiveArtifact] = useState("");
  const [preview, setPreview] = useState("");
  const gate = buildStageGate(targetId);
  const sources = getApprovedArtifactSourcesUpToPhase(targetId);
  const run = async () => {
    setLoading(true);
    setStatus("");
    setPreview("");
    try {
      const generated = await generatePhaseDrafts(targetId, {
        onStart: (artifact) => {
          setActiveArtifact(artifact.label);
          setStatus(`Generating ${artifact.label}...`);
        },
        onProgress: (artifact, text) => {
          setActiveArtifact(artifact.label);
          setPreview(text);
        },
        onComplete: (artifact) => {
          setStatus(`${artifact.label} drafted`);
        },
      });
      setStatus(`Generated ${generated.length} draft artifact${generated.length === 1 ? "" : "s"} for ${getPhaseDisplayLabel(targetId)}.`);
    } catch (err) {
      setStatus(err?.message || "The ADAM compiler could not generate this stage.");
    }
    setLoading(false);
  };
  const runSequence = async () => {
    setSequenceLoading(true);
    setStatus("");
    setPreview("");
    try {
      const phases = await generatePhaseSequence(targetId, {
        onPhaseStart: (phaseId) => setStatus(`Compiling ${getPhaseDisplayLabel(phaseId)}...`),
        onArtifactStart: (phaseId, artifact) => setActiveArtifact(`${getPhaseDisplayLabel(phaseId)} · ${artifact.label}`),
        onArtifactProgress: (phaseId, artifact, text) => {
          setActiveArtifact(`${getPhaseDisplayLabel(phaseId)} · ${artifact.label}`);
          setPreview(text);
        },
        onPhaseComplete: (phaseId, artifacts) => setStatus(`${getPhaseDisplayLabel(phaseId)} complete (${artifacts.length} artifacts)`),
      });
      setStatus(`Compiled ${phases.length} ADAM stage${phases.length === 1 ? "" : "s"} through ${getPhaseDisplayLabel(targetId)}.`);
    } catch (err) {
      setStatus(err?.message || "The ADAM compiler could not run the sequence.");
    }
    setSequenceLoading(false);
  };

  return (
    <Card style={{ marginBottom: 18, background: "linear-gradient(135deg, rgba(92,104,170,0.08) 0%, rgba(255,255,255,0.96) 100%)", border: `1px solid ${T.purple100}` }}>
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 16, marginBottom: 12 }}>
        <div>
          <div style={{ fontSize: 10, fontWeight: 800, color: T.purple500, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 4 }}>ADAM Generator</div>
          <div style={{ fontSize: 18, fontWeight: 800, color: T.gray900, marginBottom: 6 }}>Generate the next stage from approved prior-stage evidence</div>
          <div style={{ fontSize: 12.5, color: T.gray600, lineHeight: 1.6 }}>The generator reads approved artifacts, discovery context, and stage guidance to create a first-pass working set for the next ADAM stage.</div>
        </div>
        <div style={{ minWidth: 210 }}>
          <select value={targetId} onChange={(e) => setTargetId(e.target.value)} style={{ width: "100%", fontSize: 12.5, padding: "10px 12px", border: `1px solid ${T.gray200}`, borderRadius: 12, background: "rgba(255,255,255,0.92)", color: T.gray900, boxSizing: "border-box", boxShadow: T.shadowInset }}>
            {targets.map((target) => (
              <option key={target.id} value={target.id}>{target.label}</option>
            ))}
          </select>
          <div style={{ fontSize: 10.5, color: T.gray500, marginTop: 6 }}>{sources.length} approved source artifact(s) available</div>
        </div>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "0.95fr 1.05fr", gap: 14, marginBottom: 12 }}>
        <div style={{ background: "rgba(255,255,255,0.88)", border: `1px solid ${T.gray200}`, borderRadius: 14, padding: "12px 14px" }}>
          <div style={{ fontSize: 10, fontWeight: 800, color: T.gray400, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 8 }}>Source Evidence</div>
          {(sources.length ? sources : [{ title: "No approved prior-stage artifacts yet", phaseId: "discover" }]).slice(0, 6).map((source, idx) => (
            <div key={idx} style={{ fontSize: 11.5, color: T.gray700, lineHeight: 1.5, marginBottom: 6 }}>
              {sources.length ? `• ${getPhaseDisplayLabel(source.phaseId)} · ${source.title}` : `• ${source.title}`}
            </div>
          ))}
        </div>
        <div style={{ background: "rgba(255,255,255,0.88)", border: `1px solid ${T.gray200}`, borderRadius: 14, padding: "12px 14px" }}>
          <div style={{ fontSize: 10, fontWeight: 800, color: T.gray400, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 8 }}>Target Gate</div>
          <div style={{ fontSize: 11.5, fontWeight: 700, color: T.purple500, marginBottom: 6 }}>
            Vision → Design → Build → Validate → Deploy
          </div>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: gate.readiness >= 70 ? T.green500 : gate.readiness >= 45 ? T.amber500 : T.red500, marginBottom: 6 }}>{gate.readiness}% gate strength</div>
          {(gate.blockers.length ? gate.blockers : ["Compiler is ready to draft this phase."]).slice(0, 4).map((item, idx) => (
            <div key={idx} style={{ fontSize: 11.5, color: T.gray700, lineHeight: 1.5, marginBottom: 6 }}>• {item}</div>
          ))}
        </div>
      </div>
      <div style={{ background: "rgba(255,255,255,0.88)", border: `1px solid ${T.gray200}`, borderRadius: 14, padding: "12px 14px", marginBottom: 12 }}>
        <div style={{ fontSize: 10, fontWeight: 800, color: T.gray400, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 8 }}>Phase Dependency Map</div>
        {ADAM_PHASE_SEQUENCE.slice(0, ADAM_PHASE_SEQUENCE.indexOf(normalizeGuideViewId(targetId)) + 1).map((phaseId, idx, arr) => (
          <span key={phaseId} style={{ fontSize: 11.5, color: phaseId === normalizeGuideViewId(targetId) ? T.purple500 : T.gray700, fontWeight: phaseId === normalizeGuideViewId(targetId) ? 700 : 600 }}>
            {getPhaseDisplayLabel(phaseId)}
            {idx < arr.length - 1 ? <span style={{ color: T.gray400 }}> → </span> : null}
          </span>
        ))}
      </div>
      <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap", marginBottom: status || preview ? 12 : 0 }}>
        <GhostButton primary onClick={run} disabled={loading}>{loading ? `Compiling ${activeArtifact || getPhaseDisplayLabel(targetId)}...` : `Generate ${getPhaseDisplayLabel(targetId)} Drafts`}</GhostButton>
        <GhostButton onClick={runSequence} disabled={sequenceLoading}>{sequenceLoading ? `Running sequence to ${getPhaseDisplayLabel(targetId)}...` : `Generate Full Sequence To ${getPhaseDisplayLabel(targetId)}`}</GhostButton>
        {status && <span style={{ fontSize: 11.5, color: status.toLowerCase().includes("could not") || status.toLowerCase().includes("approve") ? T.red500 : T.green500, fontWeight: 700 }}>{status}</span>}
      </div>
      {!!preview && (
        <div style={{ background: T.white, border: `1px solid ${T.gray200}`, borderRadius: 14, overflow: "hidden" }}>
          <div style={{ padding: "10px 14px", borderBottom: `1px solid ${T.gray100}`, background: T.gray50, fontSize: 11, fontWeight: 800, color: T.purple500, letterSpacing: "0.06em", textTransform: "uppercase" }}>
            Live Draft Preview · {activeArtifact}
          </div>
          <div style={{ padding: "14px 16px", maxHeight: 240, overflowY: "auto" }}>
            <FormattedDocument content={preview} compact />
          </div>
        </div>
      )}
    </Card>
  );
}

