function createEmptyPhaseGuidance() {
  return Object.fromEntries(Object.entries(ADAM_PHASE_PLAYBOOK).map(([key, phase]) => [
    key,
    {
      aiBrief: "",
      lastUpdated: "",
      startedAt: null,
      targetGateDate: null,
      fields: Object.fromEntries(phase.fields.map((field) => [field.id, ""])),
    },
  ]));
}

function createEmptyPhaseSuggestions() {
  return Object.fromEntries(
    Object.keys(ADAM_PHASE_PLAYBOOK).map((phaseId) => [
      phaseId,
      {
        items: [],
        updatedAt: "",
        source: "pending",
      },
    ]),
  );
}

