const EXECUTIVE_BRIEFING_ELIGIBLE_PHASES = [
  "strategy",
  "mobilise",
  "discover",
  "design",
  "build",
  "operate",
  "govern",
  "optimize",
  "valuerealize",
];

function upsertPhaseArtifactDefinition(phaseId, definition) {
  const list = PHASE_ARTIFACT_LIBRARY[phaseId] || [];
  const nextList = [...list];
  const index = nextList.findIndex((item) => item.id === definition.id);
  if (index >= 0) nextList[index] = { ...nextList[index], ...definition };
  else nextList.push(definition);
  PHASE_ARTIFACT_LIBRARY[phaseId] = nextList;
}

