function getStageFramework(viewId) {
  return ADAM_STAGE_FRAMEWORK[ADAM_METHOD_STAGE_MAP[normalizeGuideViewId(viewId)] || normalizeGuideViewId(viewId)] || null;
}

function getArtifactLevelMeta(level) {
  return ADAM_ARTIFACT_LEVELS.find((item) => item.id === level) || ADAM_ARTIFACT_LEVELS[0];
}

function summarizeAttachmentText(text = "") {
  const normalized = normalizeCopilotCaptureText(text || "");
  if (!normalized) return "";
  const sentences = normalized
    .split(/(?<=[.!?])\s+/)
    .map((sentence) => sentence.trim())
    .filter(Boolean);
  return sentences.slice(0, 2).join(" ").slice(0, 320);
}

function extractAttachmentEntities(text = "") {
  const normalized = text || "";
  const entities = new Set();
  const moneyMatches = normalized.match(/\$[\d,.]+(?:\s?[MBKmbk])?/g) || [];
  const percentMatches = normalized.match(/\b\d+(?:\.\d+)?%/g) || [];
  const capitalizedMatches = normalized.match(/\b[A-Z][A-Za-z0-9&/+.-]{2,}(?:\s+[A-Z][A-Za-z0-9&/+.-]{2,}){0,2}\b/g) || [];
  [...moneyMatches, ...percentMatches, ...capitalizedMatches].forEach((token) => {
    const clean = token.trim();
    if (clean.length >= 3) entities.add(clean);
  });
  return [...entities].slice(0, 6);
}

function detectAttachmentThemes(text = "") {
  const lower = (text || "").toLowerCase();
  return FILE_THEME_RULES
    .filter((rule) => rule.keywords.some((keyword) => lower.includes(keyword)))
    .map((rule) => rule.label);
}

function getArtifactRecommendationsFromThemes(viewId, themes = [], text = "") {
  const key = normalizeGuideViewId(viewId);
  const defs = key === "discover"
    ? DISCOVER_DELIVERABLES
    : (PHASE_ARTIFACT_LIBRARY[key] || []);
  const lower = (text || "").toLowerCase();
  const picks = new Map();
  const addByKeyword = (needle, labels) => {
    if (!lower.includes(needle)) return;
    labels.forEach((label) => {
      const match = defs.find((artifact) => artifact.label === label);
      if (match) picks.set(match.id, { id: match.id, label: match.label, phaseId: key });
    });
  };
  if (themes.includes("Strategy & Outcomes")) {
    ["Opportunity Assessment", "Business Case", "Outcome Charter", "Executive Narrative"].forEach((label) => {
      const match = defs.find((artifact) => artifact.label === label);
      if (match) picks.set(match.id, { id: match.id, label: match.label, phaseId: key });
    });
  }
  if (themes.includes("Architecture & Systems")) {
    ["ADAM Capability DNA Canvas™", "Decision Catalog™", "Data & Application Architecture", "Architecture Starter Pack"].forEach((label) => {
      const match = defs.find((artifact) => artifact.label === label);
      if (match) picks.set(match.id, { id: match.id, label: match.label, phaseId: key });
    });
  }
  if (themes.includes("Delivery & Planning")) {
    ["Workplan", "RACI", "RAID Log", "Milestone Plan", "Pilot Plan"].forEach((label) => {
      const match = defs.find((artifact) => artifact.label === label);
      if (match) picks.set(match.id, { id: match.id, label: match.label, phaseId: key });
    });
  }
  if (themes.includes("Governance & Compliance")) {
    ["Governance Framework", "Human-in-the-Loop Model", "Risk Register", "Compliance Controls"].forEach((label) => {
      const match = defs.find((artifact) => artifact.label === label);
      if (match) picks.set(match.id, { id: match.id, label: match.label, phaseId: key });
    });
  }
  if (themes.includes("Financials & ROI")) {
    ["Business Case", "Value Realization Dashboard", "ROI Report", "Investment Recommendations"].forEach((label) => {
      const match = defs.find((artifact) => artifact.label === label);
      if (match) picks.set(match.id, { id: match.id, label: match.label, phaseId: key });
    });
  }
  addByKeyword("kpi", ["Outcome Charter", "Value Hypothesis", "Value Realization Dashboard"]);
  addByKeyword("risk", ["Risk Register", "AI Risk Assessment"]);
  addByKeyword("timeline", ["Transformation Roadmap", "Milestone Plan", "Pilot Plan"]);
  addByKeyword("architecture", ["Target State Architecture", "Data & Application Architecture"]);
  addByKeyword("budget", ["Business Case", "ROI Report"]);
  return [...picks.values()].slice(0, 4);
}

function getAttachmentConfidenceScore({ text = "", usableText = false, readMode = "reference-only" } = {}) {
  if (!usableText || readMode === "reference-only") return 28;
  const lengthScore = Math.min(50, Math.round((text.length || 0) / 40));
  const themeScore = Math.min(30, detectAttachmentThemes(text).length * 10);
  const entityScore = Math.min(20, extractAttachmentEntities(text).length * 4);
  return Math.max(32, Math.min(96, lengthScore + themeScore + entityScore));
}

function normalizeAttachmentVersionKey(name = "") {
  return String(name || "")
    .trim()
    .toLowerCase()
    .replace(/\.[a-z0-9]{1,8}$/i, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    || "attachment";
}

function buildDeterministicAttachmentHash(text = "") {
  let hash = 2166136261;
  const source = String(text || "");
  for (let index = 0; index < source.length; index += 1) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function buildAttachmentFingerprint(file, extraction = {}) {
  const text = extraction?.fullText || extraction?.text || extraction?.excerptText || "";
  return buildDeterministicAttachmentHash([
    file?.name || "",
    file?.size || 0,
    file?.type || "",
    text.slice(0, 24000),
  ].join("::"));
}

function buildAttachmentVersionMeta(viewId, file, extraction, existingAttachments = []) {
  const phaseKey = normalizeGuideViewId(viewId);
  const nameKey = normalizeAttachmentVersionKey(file?.name);
  const versionGroupId = `${phaseKey}-${nameKey}`;
  const contentFingerprint = buildAttachmentFingerprint(file, extraction);
  const priorVersions = (Array.isArray(existingAttachments) ? existingAttachments : [])
    .filter((attachment) => (
      attachment?.versionGroupId === versionGroupId
      || normalizeAttachmentVersionKey(attachment?.name) === nameKey
    ))
    .sort((left, right) => {
      const leftVersion = Number(left?.versionNumber || 1);
      const rightVersion = Number(right?.versionNumber || 1);
      if (leftVersion !== rightVersion) return leftVersion - rightVersion;
      return `${left?.addedAt || ""}`.localeCompare(`${right?.addedAt || ""}`);
    });
  const latestVersion = priorVersions[priorVersions.length - 1] || null;
  if (!latestVersion) {
    return {
      contentFingerprint,
      versionGroupId,
      versionNumber: 1,
      previousVersionId: "",
      isUpdatedVersion: false,
      isDuplicateVersion: false,
      versionNotice: "",
    };
  }
  const latestVersionNumber = Number(latestVersion.versionNumber || priorVersions.length || 1);
  const sameFingerprint = !!latestVersion.contentFingerprint && latestVersion.contentFingerprint === contentFingerprint;
  return {
    contentFingerprint,
    versionGroupId,
    versionNumber: sameFingerprint ? latestVersionNumber : latestVersionNumber + 1,
    previousVersionId: latestVersion.id || "",
    isUpdatedVersion: !sameFingerprint,
    isDuplicateVersion: sameFingerprint,
    versionNotice: sameFingerprint
      ? `${file?.name || "Document"} matches the latest attached version already on this phase.`
      : `Updated version detected for ${file?.name || "document"} (v${latestVersionNumber + 1}).`,
  };
}

function buildAttachmentContextRecord(viewId, file, extraction, notes = "", versionMeta = {}) {
  const text = extraction?.excerptText || extraction?.text || "";
  const themes = detectAttachmentThemes(text);
  const keyEntities = extractAttachmentEntities(text);
  const recommendations = getArtifactRecommendationsFromThemes(viewId, themes, text);
  return {
    ...createBlankAttachmentRecord(),
    id: `${normalizeGuideViewId(viewId)}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    name: file.name,
    mimeType: file.type || "application/octet-stream",
    size: file.size || 0,
    fileType: file.name.split(".").pop()?.toLowerCase() || file.type || "file",
    category: "document",
    notes: notes.trim(),
    manualDescription: file.type?.startsWith("image/") ? notes.trim() : "",
    addedAt: stampNow(),
    source: extraction?.usableText ? "Uploaded source material" : "Uploaded metadata reference",
    dataUrl: "",
    storedInline: false,
    usableText: !!extraction?.usableText,
    agentProcessed: false,
    extractedText: extraction?.fullText || text,
    fullText: extraction?.fullText || text,
    excerptText: extraction?.excerptText || text,
    extractedSummary: summarizeAttachmentText(text) || notes.trim(),
    keyEntities,
    keyThemes: themes,
    artifactRecommendations: recommendations,
    confidenceScore: getAttachmentConfidenceScore(extraction),
    processingStatus: extraction?.readMode === "parse-error" ? "partial" : extraction?.usableText ? "processed" : "reference_only",
    associatedStage: normalizeGuideViewId(viewId),
    associatedArtifact: recommendations[0]?.label || "",
    suggestedPhase: extraction?.suggestedPhase || "",
    readMode: extraction?.readMode || "reference-only",
    parseError: extraction?.parseError || "",
    contentFingerprint: versionMeta.contentFingerprint || "",
    versionGroupId: versionMeta.versionGroupId || "",
    versionNumber: Number(versionMeta.versionNumber || 1),
    previousVersionId: versionMeta.previousVersionId || "",
    isUpdatedVersion: !!versionMeta.isUpdatedVersion,
    isDuplicateVersion: !!versionMeta.isDuplicateVersion,
    versionNotice: versionMeta.versionNotice || "",
  };
}

function getPhaseFileInsights(viewId) {
  return getPhaseAttachments(viewId)
    .filter((attachment) => attachment.extractedSummary || attachment.manualDescription || attachment.notes)
    .map((attachment) => ({
      name: attachment.name,
      summary: attachment.extractedSummary || attachment.manualDescription || attachment.notes,
      themes: attachment.keyThemes || [],
      recommendations: attachment.artifactRecommendations || [],
      confidenceScore: attachment.confidenceScore || 0,
    }));
}

function buildPhaseAttachmentEvidence(viewId) {
  return getPhaseAttachments(viewId)
    .slice(-6)
    .map((attachment) => {
      const summary = attachment.extractedSummary || attachment.manualDescription || attachment.notes || "";
      return summary ? `${attachment.name}: ${summary}` : attachment.name;
    })
    .join("; ");
}

function getAllArtifactDefinitions() {
  return Object.values(PHASE_ARTIFACT_LIBRARY).flat();
}

function getSignatureArtifactDefinitions() {
  return getAllArtifactDefinitions().filter((artifact) => artifact.signature);
}

function getCoreArtifactDefinitions() {
  return getAllArtifactDefinitions().filter((artifact) => artifact.core);
}

function getArtifactLevelSummary() {
  return ADAM_ARTIFACT_LEVELS.map((level) => {
    const artifacts = getAllArtifactDefinitions().filter((artifact) => artifact.level === level.id);
    return {
      ...level,
      count: artifacts.length,
      signatureCount: artifacts.filter((artifact) => artifact.signature).length,
      coreCount: artifacts.filter((artifact) => artifact.core).length,
    };
  });
}

