function computeJourneyReadiness(data, fallback = 0) {
  const phases = Array.isArray(data?.phases) ? data.phases : [];
  if (phases.length) {
    const average = Math.round(
      phases.reduce((sum, phase) => sum + Number(phase?.pct || 0), 0) / phases.length,
    );
    if (Number.isFinite(average)) return average;
  }
  const lifecycle = Array.isArray(data?.lifecycle) ? data.lifecycle : [];
  if (lifecycle.length) {
    const legacyAverage = Math.round(
      lifecycle.reduce((sum, stage) => sum + Number(stage?.pct || 0), 0) / lifecycle.length,
    );
    if (Number.isFinite(legacyAverage)) return legacyAverage;
  }
  const parsedFallback = Number(fallback);
  return Number.isFinite(parsedFallback) ? parsedFallback : 0;
}

function hydrateProject(project) {
  const data = normalizeMethodologyProjectData(project.data ? JSON.parse(JSON.stringify(project.data)) : cloneProjectTemplate(project.industry));
  return {
    ...project,
    data,
    readiness: computeJourneyReadiness(data, project?.readiness ?? 0),
  };
}

