/* Runtime mutable project store */
let _projects = loadStoredProjects();
const UNDO_HISTORY_MAX = 20;
const _undoHistory = new Map();
const _stageGateCache = new Map();
const _artifactUndoStack = new Map();
let _pendingUndoLabel = null;
let _activeProjectId = loadStoredActiveProjectId(_projects);
let _aiSetup = loadAISetup();
let _currentPersonaId = loadStoredPersona();
let _operatingMode = loadOperatingMode();
let _storageWarningHandler = null;

function registerStorageWarningHandler(handler) {
  _storageWarningHandler = typeof handler === "function" ? handler : null;
}

function safeLocalStorageGet(key) {
  if (typeof window === "undefined") return null;
  try {
    return window.localStorage.getItem(key);
  } catch {
    return null;
  }
}

function safeJSONParse(value, fallback = null) {
  try {
    return value ? JSON.parse(value) : fallback;
  } catch {
    return fallback;
  }
}

function showStorageWarning() {
  _storageWarningHandler?.("Program data could not be saved — browser storage is full. Export your program now to avoid data loss.");
}

function pruneOldVersionHistory() {
  _projects = _projects.map((project) => {
    const data = normalizeMethodologyProjectData(JSON.parse(JSON.stringify(project?.data || EMPTY_PROJECT_DATA)));
    if (data.discoverArtifactMeta) {
      Object.values(data.discoverArtifactMeta).forEach((artifact) => {
        if (Array.isArray(artifact?.versionHistory)) artifact.versionHistory = artifact.versionHistory.slice(-3);
      });
    }
    if (data.phaseArtifacts) {
      Object.values(data.phaseArtifacts).forEach((phaseArtifacts) => {
        Object.values(phaseArtifacts || {}).forEach((artifact) => {
          if (Array.isArray(artifact?.versionHistory)) artifact.versionHistory = artifact.versionHistory.slice(-3);
        });
      });
    }
    return { ...project, data };
  });
}

function safeLocalStorageSet(key, value) {
  if (typeof window === "undefined") return false;
  try {
    window.localStorage.setItem(key, value);
    return true;
  } catch (error) {
    if (error?.name === "QuotaExceededError" || error?.code === 22) {
      console.error("ADAM: localStorage quota exceeded. Attempting cleanup.");
      pruneOldVersionHistory();
      try {
        window.localStorage.setItem(PROJECTS_STORAGE_KEY, JSON.stringify(_projects));
        if (key !== PROJECTS_STORAGE_KEY) window.localStorage.setItem(key, value);
        return true;
      } catch {
        showStorageWarning();
        return false;
      }
    }
    throw error;
  }
}

function getArtifactUndoKey(artifactId, phaseId = "") {
  return `${phaseId || "phase"}::${artifactId || "artifact"}`;
}

function pushArtifactUndo(artifactId, content, phaseId = "") {
  const key = getArtifactUndoKey(artifactId, phaseId);
  const stack = _artifactUndoStack.get(key) || [];
  stack.push({
    content: typeof content === "string" ? content : JSON.parse(JSON.stringify(content)),
    at: Date.now(),
  });
  if (stack.length > 10) stack.shift();
  _artifactUndoStack.set(key, stack);
}

function undoArtifactEdit(artifactId, phaseId) {
  const key = getArtifactUndoKey(artifactId, phaseId);
  const stack = _artifactUndoStack.get(key);
  if (!stack || !stack.length) return false;
  const previous = stack.pop();
  _artifactUndoStack.set(key, stack);
  updateActiveProjectData((data) => {
    if (phaseId === "discover") {
      data.discoverWorkspace = {
        ...createEmptyDiscoverWorkspace(),
        ...(data.discoverWorkspace || {}),
        [artifactId]: typeof previous.content === "string" ? previous.content : `${previous.content || ""}`,
      };
      if (data.discoverArtifactMeta?.[artifactId]) {
        data.discoverArtifactMeta[artifactId].content = typeof previous.content === "string" ? previous.content : `${previous.content || ""}`;
      }
      return;
    }
    if (data.phaseArtifacts?.[phaseId]?.[artifactId]) {
      data.phaseArtifacts[phaseId][artifactId].content = previous.content;
    }
  }, null, { skipUndoSnapshot: true });
  return true;
}

function _getUndoStack(projectId) {
  if (!_undoHistory.has(projectId)) {
    _undoHistory.set(projectId, { stack: [], cursor: -1 });
  }
  return _undoHistory.get(projectId);
}

function _pushUndoSnapshot(projectId, snapshot, label = "Action") {
  const entry = _getUndoStack(projectId);
  entry.stack = entry.stack.slice(0, entry.cursor + 1);
  entry.stack.push({
    data: JSON.parse(JSON.stringify(snapshot)),
    label,
    timestamp: Date.now(),
  });
  if (entry.stack.length > UNDO_HISTORY_MAX) {
    entry.stack = entry.stack.slice(entry.stack.length - UNDO_HISTORY_MAX);
  }
  entry.cursor = entry.stack.length - 1;
}

function addToTransformationLibrary(library, field, newEntry) {
  const existing = Array.isArray(library?.[field]) ? library[field] : [];
  return [...existing, { ...newEntry, addedAt: newEntry?.addedAt || Date.now(), reuseCount: Number(newEntry?.reuseCount || 0) }]
    .sort((a, b) => (Number(b.reuseCount || 0) - Number(a.reuseCount || 0)) || (Number(b.addedAt || 0) - Number(a.addedAt || 0)))
    .slice(0, 50);
}

function syncOrganizationAgentCatalogFromProgram(portfolio, programId, agents = []) {
  const existing = Array.isArray(portfolio?.organizationAgentCatalog) ? [...portfolio.organizationAgentCatalog] : [];
  agents.forEach((agent) => {
    const agentType = String(agent?.type || agent?.name || "").trim();
    if (!agentType) return;
    const nextEntry = {
      sourceProgramId: programId || "",
      agentType,
      skills: Array.isArray(agent?.skills) ? agent.skills : [],
      dataRequirements: Array.isArray(agent?.dataRequirements) ? agent.dataRequirements : [],
      trustLevel: agent?.trustLevel || agent?.status || "approved",
      deploymentCount: Number(agent?.deploymentCount || 1),
      averageROI: agent?.averageROI || agent?.roi || "",
    };
    const index = existing.findIndex((item) => String(item.agentType || "").toLowerCase() === agentType.toLowerCase());
    if (index >= 0) {
      existing[index] = {
        ...existing[index],
        ...nextEntry,
        deploymentCount: Math.max(Number(existing[index].deploymentCount || 0), Number(nextEntry.deploymentCount || 0)),
      };
    } else {
      existing.push(nextEntry);
    }
  });
  portfolio.organizationAgentCatalog = existing.slice(0, 100);
}

function canUndo(projectId) {
  const entry = _getUndoStack(projectId);
  return entry.cursor > 0;
}

function canRedo(projectId) {
  const entry = _getUndoStack(projectId);
  return entry.cursor < entry.stack.length - 1;
}

function getLastActionLabel(projectId) {
  const entry = _getUndoStack(projectId);
  if (entry.cursor < 1) return null;
  return entry.stack[entry.cursor]?.label || "Action";
}

const ADAM_PHASE_SEQUENCE = ["strategy", "mobilise", "discover", "design", "build", "operate", "govern", "optimize", "valuerealize"];

function _restoreProjectData(projectId, snapshotData) {
  const normalizedData = normalizeMethodologyProjectData(JSON.parse(JSON.stringify(snapshotData || EMPTY_PROJECT_DATA)));
  recalculateDiscoverReadiness(normalizedData);
  recalculatePhaseArtifactReadiness(normalizedData);
  _projects = _projects.map((project) => (
    project.id === projectId
      ? { ...project, data: normalizedData }
      : project
  ));
  syncJourneyPhaseProgressForProject(projectId);
  persistProjectStore();
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent(ADAM_PROJECT_DATA_UPDATED_EVENT, { detail: { projectId } }));
  }
}

function applyUndo(projectId) {
  const entry = _getUndoStack(projectId);
  if (entry.cursor < 1) return null;
  entry.cursor -= 1;
  const snapshot = entry.stack[entry.cursor].data;
  _restoreProjectData(projectId, snapshot);
  return snapshot;
}

function applyRedo(projectId) {
  const entry = _getUndoStack(projectId);
  if (entry.cursor >= entry.stack.length - 1) return null;
  entry.cursor += 1;
  const snapshot = entry.stack[entry.cursor].data;
  _restoreProjectData(projectId, snapshot);
  return snapshot;
}

function getProjects() { return _projects; }
function getActiveProject() { return _projects.find(p => p.id === _activeProjectId) || _projects[0] || null; }
function syncJourneyPhaseProgressForProject(projectId) {
  if (!projectId) return null;
  const project = _projects.find((item) => item.id === projectId);
  if (!project?.data) return project || null;
  const previousActiveProjectId = _activeProjectId;
  try {
    _activeProjectId = projectId;
    _stageGateCache.clear();
    const syncedData = normalizeMethodologyProjectData(JSON.parse(JSON.stringify(project.data)));
    syncedData.phases = (Array.isArray(syncedData.phases) ? syncedData.phases : []).map((phase) => {
      if (!ADAM_PHASE_SEQUENCE.includes(phase?.id)) return phase;
      const workflowGate = getWorkflowGateStatus(phase.id);
      const summary = getPhaseArtifactSummary(phase.id);
      const pct = workflowGate.complete
        ? 100
        : Math.max(0, Math.min(100, Math.round(Number(workflowGate.readiness || 0))));
      return {
        ...phase,
        pct,
        artifacts: Math.max(
          Number(phase?.artifacts || 0),
          Number(summary?.drafted || 0),
          Number(summary?.approved || 0),
        ),
        blockers: Array.isArray(workflowGate.blockers) ? workflowGate.blockers.length : Number(phase?.blockers || 0),
      };
    });
    const nextReadiness = computeJourneyReadiness(syncedData, project?.readiness ?? 0);
    const syncedProject = {
      ...project,
      data: syncedData,
      readiness: Number.isFinite(nextReadiness) ? nextReadiness : 0,
    };
    _projects = _projects.map((item) => (item.id === projectId ? syncedProject : item));
    return syncedProject;
  } finally {
    _activeProjectId = previousActiveProjectId;
    _stageGateCache.clear();
  }
}
function syncAllProjectJourneyProgress() {
  _projects.forEach((project) => {
    syncJourneyPhaseProgressForProject(project.id);
  });
}
function saveProjectRecord(project) {
  const hydrated = hydrateProject(project);
  _projects = [..._projects.filter((item) => item.id !== hydrated.id), hydrated];
  const syncedProject = syncJourneyPhaseProgressForProject(hydrated.id) || hydrated;
  persistProjectStore();
  saveProgramToSupabase(syncedProject).catch(() => {});
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent(ADAM_PROJECT_DATA_UPDATED_EVENT, { detail: { projectId: syncedProject.id } }));
  }
  return syncedProject;
}
syncAllProjectJourneyProgress();
function activateProjectRecord(projectId) {
  if (!_projects.some((project) => project.id === projectId)) return null;
  _activeProjectId = projectId;
  persistProjectStore();
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent(ADAM_PROJECT_DATA_UPDATED_EVENT, { detail: { projectId } }));
  }
  return getActiveProject();
}
function exportProgram(projectId) {
  const project = _projects.find((item) => item.id === projectId);
  const data = project?.data;
  if (!data || typeof document === "undefined") return false;
  const payload = JSON.stringify({ version: "ADAM-1.0", exportedAt: new Date().toISOString(), program: { ...project, data } }, null, 2);
  const blob = new Blob([payload], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = `adam-program-${String(project?.name || projectId).replace(/\s+/g, "-").toLowerCase()}-${Date.now()}.json`;
  anchor.click();
  URL.revokeObjectURL(url);
  writeAuditLog({ programId: projectId, action: "export", summary: `Program exported: ${project?.name || projectId}` }).catch(() => {});
  return true;
}
async function importProgram(file) {
  try {
    const text = await file.text();
    const payload = JSON.parse(text);
    if (!payload.version?.startsWith("ADAM") || !payload.program) throw new Error("Invalid ADAM program file.");
    const sourceProgram = payload.program;
    const importedId = `p${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
    const imported = hydrateProject({
      ...sourceProgram,
      id: importedId,
      data: normalizeMethodologyProjectData({
        ...createEmptyProjectMethodologyState(),
        ...(sourceProgram.data || {}),
      }),
      name: `${sourceProgram.name || sourceProgram.projectMeta?.name || "Imported Program"} (imported)`,
      projectMeta: {
        ...(sourceProgram.projectMeta || {}),
        name: `${sourceProgram.projectMeta?.name || sourceProgram.name || "Imported Program"} (imported)`,
        importedAt: new Date().toISOString(),
      },
    });
    saveProjectRecord(imported);
    activateProjectRecord(imported.id);
    writeAuditLog({ programId: imported.id, action: "import", summary: `Program imported: ${imported.name || imported.projectMeta?.name || "Imported Program"}` }).catch(() => {});
    return { success: true, programName: imported.name || imported.projectMeta?.name || "Imported Program", projectId: imported.id };
  } catch (error) {
    return { success: false, error: error?.message || "Could not import ADAM program." };
  }
}
