function getArchitectureReadinessScore(stack, pattern, decisions = [], nfrs = []) {
  if (!stack) return 0;
  let score = 0;
  if (pattern) score += 20;
  const requiredLayers = [
    !!stack.llm?.provider && !!stack.llm?.model,
    !!stack.agentFramework?.name,
    !!stack.deploymentPlatform?.cloudProvider,
    !!stack.security?.iamApproach,
    !!stack.observability?.loggingPlatform || !!stack.observability?.agentMonitoring,
  ];
  score += (requiredLayers.filter(Boolean).length / requiredLayers.length) * 30;
  score += Math.min(25, decisions.filter((item) => item.status !== "retired").length * 5);
  const nfrTypes = new Set(nfrs.map((nfr) => nfr.requirementType));
  if (nfrTypes.has("latency")) score += 8.34;
  if (nfrTypes.has("security")) score += 8.33;
  if (nfrTypes.has("compliance")) score += 8.33;
  return Math.round(Math.min(100, score));
}
