function recalculateDiscoverReadiness(data) {
  const workspace = { ...createEmptyDiscoverWorkspace(), ...(data.discoverWorkspace || {}) };
  const context = { ...createEmptyDiscoverContext(), ...(data.discoverContext || {}) };
  const meta = { ...createEmptyDiscoverArtifactMeta(), ...(data.discoverArtifactMeta || {}) };
  const completedDeliverables = DISCOVER_DELIVERABLES.filter((item) => workspace[item.id]?.trim()).length;
  const approvedDeliverables = DISCOVER_DELIVERABLES.filter((item) => meta[item.id]?.status === "approved").length;
  const contextCount = [context.problem, context.outcomes, context.kpis, context.compliance].filter((value) => value?.trim()).length;
  const totalEvidence = Math.min(DISCOVER_DELIVERABLES.length + 2, completedDeliverables + Math.min(2, Math.ceil(contextCount / 2)));
  const discoverPct = Math.round((((completedDeliverables * 0.6) + (approvedDeliverables * 0.4)) / DISCOVER_DELIVERABLES.length) * 100);

  data.phases = (data.phases || []).map((phase) =>
    phase.id === "discover"
      ? { ...phase, pct: discoverPct, artifacts: totalEvidence }
      : phase
  );

  const stageFill = {
    idea: workspace.transformationRoadmap?.trim() ? 100 : 0,
    opportunity: workspace.opportunityAssessment?.trim() ? 100 : 0,
    business_case: workspace.businessCase?.trim() ? 100 : 0,
    outcomes: Math.round(([
      workspace.valueHypothesis,
      workspace.executiveNarrative,
      workspace.outcomeCharter,
    ].filter((value) => value?.trim()).length / 3) * 100),
  };

  data.lifecycle = (data.lifecycle || []).map((stage) => {
    if (!Object.prototype.hasOwnProperty.call(stageFill, stage.id)) return stage;
    const artifacts = stage.id === "outcomes"
      ? [workspace.valueHypothesis, workspace.executiveNarrative, workspace.outcomeCharter].filter((value) => value?.trim()).length
      : stageFill[stage.id] ? 1 : 0;
    return { ...stage, pct: stageFill[stage.id], artifacts };
  });
}

function recalculatePhaseArtifactReadiness(data) {
  const phaseArtifacts = {
    ...createEmptyPhaseArtifacts(),
    ...(data.phaseArtifacts || {}),
  };
  const phaseToStageMap = {
    design: "capabilities",
    agents: "agents",
    build: "build",
    fde: "fde",
    delivery: "delivery",
    operate: "governance",
    adoption: "adoption",
    optimize: "value",
  };
  Object.entries(phaseToStageMap).forEach(([phaseId, stageId]) => {
    const artifacts = Object.values(phaseArtifacts[phaseId] || {});
    const drafted = artifacts.filter((artifact) => artifact.status !== "blank").length;
    const approved = artifacts.filter((artifact) => artifact.status === "approved").length;
    const reviewed = artifacts.filter((artifact) => artifact.status === "review" || artifact.status === "approved").length;
    const challenged = artifacts.filter((artifact) => artifact.status === "changes_requested" || artifact.status === "rejected").length;
    const total = Math.max(artifacts.length, 1);
    const pct = Math.max(0, Math.round((((drafted * 0.35) + (reviewed * 0.25) + (approved * 0.4) - (challenged * 0.15)) / total) * 100));
    const blockers = artifacts.filter((artifact) => (artifact.status !== "approved" && !artifact.evidence?.trim()) || artifact.status === "changes_requested" || artifact.status === "rejected").length;
    data.phases = (data.phases || []).map((phase) =>
      phase.id === phaseId
        ? { ...phase, pct: Math.max(phase.pct || 0, pct), artifacts: Math.max(phase.artifacts || 0, drafted), blockers }
        : phase
    );
    data.lifecycle = (data.lifecycle || []).map((stage) =>
      stage.id === stageId
        ? { ...stage, pct: Math.max(stage.pct || 0, pct), artifacts: Math.max(stage.artifacts || 0, drafted), blockers }
        : stage
    );
  });
}

function updateActiveProjectData(updater, undoLabel = null, options = {}) {
  const activeProject = getActiveProject();
  if (!activeProject) return null;
  const beforeSnapshot = JSON.parse(JSON.stringify(getProjectData(activeProject)));
  const nextData = normalizeMethodologyProjectData(JSON.parse(JSON.stringify(beforeSnapshot)));
  updater(nextData);
  if (nextData.phaseBriefings) {
    for (const phaseId of Object.keys(nextData.phaseBriefings)) {
      const briefing = nextData.phaseBriefings[phaseId];
      if (!briefing?.generatedAt) continue;
      const briefingTime = new Date(briefing.generatedAt).getTime();
      const lastArtifactChange = Object.values(
        nextData.phaseArtifacts?.[phaseId] ?? {},
      ).reduce((latest, artifact) => {
        const artifactTime = artifact?.approvedAt ? new Date(artifact.approvedAt).getTime() : 0;
        return Math.max(latest, artifactTime);
      }, 0);
      if (lastArtifactChange > briefingTime) {
        nextData.phaseBriefings[phaseId] = { ...briefing, stale: true };
      }
    }
  }
  if (nextData.programNarrative?.generatedAt) {
    const narrativeTime = new Date(nextData.programNarrative.generatedAt).getTime();
    const lastArtifactChange = ADAM_PHASE_SEQUENCE.reduce((latestByPhase, phaseId) => {
      const phaseLatest = Object.values(nextData.phaseArtifacts?.[phaseId] ?? {}).reduce((latest, artifact) => {
        const artifactTime = artifact?.approvedAt
          ? new Date(artifact.approvedAt).getTime()
          : artifact?.updatedAt
            ? new Date(artifact.updatedAt).getTime()
            : 0;
        return Math.max(latest, artifactTime);
      }, 0);
      return Math.max(latestByPhase, phaseLatest);
    }, 0);
    if (lastArtifactChange > narrativeTime) {
      nextData.programNarrative = {
        ...nextData.programNarrative,
        stale: true,
      };
    }
  }
  const normalizedData = normalizeMethodologyProjectData(nextData);
  recalculateDiscoverReadiness(normalizedData);
  recalculatePhaseArtifactReadiness(normalizedData);
  const health = computeProgramHealthScore({
    ...normalizedData,
    id: activeProject.id,
    programId: activeProject.id,
  });
  normalizedData.currentHealthScore = health;
  normalizedData.healthScoreHistory = [
    ...(normalizedData.healthScoreHistory || []),
    { ...health, ts: new Date().toISOString() },
  ].slice(-50);
  normalizedData.completionForecast = computeCompletionForecast({
    ...normalizedData,
    id: activeProject.id,
    programId: activeProject.id,
  });
  const projectId = activeProject.id;
  _projects = _projects.map((project) => project.id === projectId ? { ...project, data: normalizedData } : project);
  const syncedProject = syncJourneyPhaseProgressForProject(projectId);
  const persistedData = syncedProject?.data || normalizedData;
  const history = _getUndoStack(projectId);
  if (history.stack.length === 0) {
    _pushUndoSnapshot(projectId, beforeSnapshot, "Initial state");
  }
  const appliedLabel = undoLabel || _pendingUndoLabel || "Edit";
  if (!options.skipUndoSnapshot) {
    _pushUndoSnapshot(projectId, persistedData, appliedLabel);
  }
  persistProjectStore({ skipRemote: true });
  const updatedProject = _projects.find((project) => project.id === projectId);
  if (!isSupabaseConfigured || !supabase) {
    _syncStatusHandler?.("offline");
  } else if (updatedProject?.data) {
    _syncStatusHandler?.("syncing");
    saveProgramToSupabase(updatedProject)
      .then((success) => {
        _syncStatusHandler?.(success ? "synced" : "error");
      })
      .catch(() => {
        _syncStatusHandler?.("error");
      });
  }
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent(ADAM_PROJECT_DATA_UPDATED_EVENT, {
      detail: { projectId, undoLabel: options.skipUndoSnapshot ? null : appliedLabel, skipUndoSnapshot: !!options.skipUndoSnapshot },
    }));
  }
  return persistedData;
}

function updateActiveProjectMeta(updater) {
  const activeProject = getActiveProject();
  if (!activeProject) return null;
  const nextProject = { ...activeProject };
  updater(nextProject);
  _projects = _projects.map((project) => project.id === activeProject.id ? nextProject : project);
  _stageGateCache.clear();
  persistProjectStore();
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent(ADAM_PROJECT_DATA_UPDATED_EVENT, {
      detail: { projectId: activeProject.id },
    }));
  }
  return nextProject;
}

function stampNow() {
  return new Date().toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

function normalizeMobilisePhaseId(phaseId = "") {
  return phaseId;
}

function getJourneyPhaseIds() {
  return ["mobilise", "discover", "design", "build", "operate", "govern", "optimize", "valuerealize"];
}

function getChangeManagementCollections(viewId) {
  const mobilise = getMOBILISE();
  const phaseKey = normalizeGuideViewId(viewId) === "operate" ? "govern" : normalizeGuideViewId(viewId);
  const phaseState = getPhaseChangeManagement(phaseKey);
  const byIds = (items, ids) => {
    const set = new Set(Array.isArray(ids) ? ids.filter(Boolean) : []);
    if (!set.size) return [];
    return items.filter((item) => set.has(item.id));
  };
  return {
    phaseState,
    impacts: byIds(mobilise.changeImpacts, phaseState.impacts),
    engagements: byIds(mobilise.stakeholderEngagements, phaseState.engagements),
    communications: byIds(mobilise.communicationPlans, phaseState.communications),
    training: byIds(mobilise.trainingPlans, phaseState.training),
    adoptionSignals: byIds(mobilise.adoptionMetrics, phaseState.adoptionSignals),
    changeNetwork: mobilise.changeNetwork,
  };
}

function calculateMobiliseGate() {
  const key = "mobilise";
  const mobilise = getMOBILISE();
  const strategy = getSTRATEGY_DATA();
  const activeProject = getActiveProject();
  const readiness = getProjectData(getActiveProject()).readiness || {};
  const framework = getStageFramework(key);
  const summary = getPhaseArtifactSummary(key);
  const ops = getPHASE_GATE_OPS()[key] || createBlankGateOpsRecord();
  const guidance = getPHASE_GUIDANCE()[key]?.fields || {};
  const artifacts = getPhaseArtifactsForView(key);
  const deliveryRoles = mobilise.deliveryRoles || [];
  const recommendedRoleCount = getRecommendedDeliveryRoleCount(activeProject);
  const namedDeliveryRoles = deliveryRoles.filter((role) => `${role.personName || role.roleName || ""}`.trim());
  const discoverDesignStaffed = ["discover", "design"].every((phaseId) =>
    namedDeliveryRoles.some((role) => (role.activePhases || []).includes(phaseId))
  );
  const teamRosterDefined = namedDeliveryRoles.length > 0;
  const programLeadNamed = !!mobilise.deliveryRoles.find((role) => (
    role.roleType === "program lead" || role.roleType === "program sponsor"
  ) && `${role.personName || role.roleName || ""}`.trim())
    || !!`${guidance.programLead || ""}`.trim();
  const executiveSponsorNamed = !!`${guidance.executiveSponsor || getPROGRAM().sponsor || ""}`.trim();
  const workplanPhases = mobilise.workplan?.phases || [];
  const workplanExists = !!mobilise.workplan && workplanPhases.length > 0 && !!mobilise.workplan?.milestones?.length;
  const workplanCoversJourney = getJourneyPhaseIds().every((phaseId) =>
    workplanPhases.some((phase) =>
      normalizeMobilisePhaseId(phase.phaseId) === phaseId
      && `${phase.plannedStart || ""}`.trim()
    )
  );
  const raciExists = normalizeRaciRows(mobilise.raci).length > 0;
  const governanceDefined = !!(mobilise.governanceCadence?.steeringFrequency || "").trim()
    || !!`${guidance.governanceCadence || ""}`.trim();
  const governanceFrameworkEstablished = !!mobilise.governanceFramework?.established;
  const changeApproachDefined = !!`${guidance.changeApproach || ""}`.trim()
    || !!mobilise.changeImpacts.length
    || !!mobilise.stakeholderEngagements.length
    || !!mobilise.communicationPlans.length;
  const strategyComplete = [
    "mandate",
    "sponsorCommitment",
    "investmentEnvelope",
    "scopeBoundaries",
    "successDefinition",
  ].every((fieldId) => `${strategy?.[fieldId] || ""}`.trim());
  const requiredInputs = (framework?.requiredInputs || []).map((item) => {
    let complete = !!`${guidance[item.fieldId] || ""}`.trim();
    if (item.fieldId === "programLead") complete = programLeadNamed;
    if (item.fieldId === "executiveSponsor") complete = executiveSponsorNamed;
    if (item.fieldId === "targetCapability") complete = !!`${guidance.targetCapability || ""}`.trim() || !!getCAPABILITIES().length;
    if (item.fieldId === "programStartDate") complete = !!`${guidance.programStartDate || ""}`.trim() || !!`${mobilise.workplan?.startDate || ""}`.trim();
    if (item.fieldId === "governanceCadence") complete = governanceDefined;
    if (item.fieldId === "changeApproach") complete = changeApproachDefined;
    return {
      id: item.fieldId,
      label: item.label,
      complete,
    };
  });
  const exitCriteria = (framework?.exitCriteria || []).map((criterion) => {
    const lower = criterion.toLowerCase();
    let complete = false;
    if (lower.includes("program lead")) complete = programLeadNamed;
    else if (lower.includes("delivery team roles")) complete = discoverDesignStaffed;
    else if (lower.includes("team roster")) complete = teamRosterDefined;
    else if (lower.includes("raci")) complete = raciExists;
    else if (lower.includes("workplan covers")) complete = workplanCoversJourney;
    else if (lower.includes("workplan")) complete = workplanExists;
    else if (lower.includes("governance cadence")) complete = governanceDefined;
    else if (lower.includes("governance framework")) complete = governanceFrameworkEstablished;
    else if (lower.includes("change management approach")) complete = changeApproachDefined;
    return { label: criterion, complete };
  });
  const blockers = [
    ...(Array.isArray(readiness.blockers) ? readiness.blockers.slice(0, 3) : []),
    ...(strategyComplete ? [] : ["Strategy gate incomplete — Executive mandate, sponsor commitment, investment envelope, scope boundaries, and success definition are required before mobilising."]),
    ...requiredInputs.filter((item) => !item.complete).map((item) => `Missing input: ${item.label}`),
    ...exitCriteria.filter((item) => !item.complete).map((item) => `Unmet exit criterion: ${item.label}`),
  ];
  const inputCoverage = requiredInputs.length ? Math.round((requiredInputs.filter((item) => item.complete).length / requiredInputs.length) * 100) : 0;
  const exitCoverage = exitCriteria.length ? Math.round((exitCriteria.filter((item) => item.complete).length / exitCriteria.length) * 100) : 0;
  const artifactCoverage = artifacts.length ? Math.round((summary.drafted / artifacts.length) * 100) : 0;
  const approvalCoverage = artifacts.length ? Math.round((summary.approved / artifacts.length) * 100) : 0;
  const freshnessCoverage = artifacts.length ? Math.round((artifacts.filter((artifact) => getArtifactFreshness(key, artifact).id === "fresh").length / artifacts.length) * 100) : 0;
  const { coverage: decisionCoverage, approvedDecisionCount, recommendedDecisionCount } = getDecisionCoverageMetrics(getProjectData(getActiveProject()));
  const stakeholderCoverage = getStakeholderCoverageScore(getProjectData(getActiveProject()));
  const blockerPenalty = evaluateExitCriteria(key, getProjectData(getActiveProject())).failures.filter((failure) => /required/i.test(failure)).length * 10;
  const readinessScore = Math.max(0, Math.min(100, Math.round(
    (artifactCoverage * 0.35)
    + (decisionCoverage * 0.25)
    + (approvalCoverage * 0.20)
    + (stakeholderCoverage * 0.12)
    + (freshnessCoverage * 0.08)
    - blockerPenalty
  )));
  const confidence = Math.max(0, Math.min(100, Math.round(
    readinessScore
    - Math.min(18, blockers.length * 4)
    + Math.min(10, summary.evidence * 2)
  )));
  const recommendations = blockers.length
    ? blockers.slice(0, 3).map((item) => item.replace(/^Missing input:\s*/i, "Complete ").replace(/^Unmet exit criterion:\s*/i, "Close "))
    : (framework?.recommendedActions || []).slice(0, 3);
  const breakdown = {
    artifacts: { score: Math.round(artifactCoverage * 0.35), weight: 35, label: "Artifact Completeness" },
    decisions: { score: Math.round(decisionCoverage * 0.25), weight: 25, label: "Decision Coverage" },
    approvals: { score: Math.round(approvalCoverage * 0.20), weight: 20, label: "Approvals" },
    stakeholders: { score: Math.round(stakeholderCoverage * 0.12), weight: 12, label: "Stakeholder Coverage" },
    freshness: { score: Math.round(freshnessCoverage * 0.08), weight: 8, label: "Data Freshness" },
    blockers: { penalty: blockerPenalty, label: "Active Blockers" },
  };
  return {
    key,
    readiness: readinessScore,
    blockers,
    requiredInputs,
    exitCriteria,
    summary,
    artifacts,
    ops,
    framework,
    teamCoverage: recommendedRoleCount ? Math.min(100, Math.round((deliveryRoles.length / recommendedRoleCount) * 100)) : 0,
    workplanCoverage: getJourneyPhaseIds().length ? Math.round((workplanPhases.length / getJourneyPhaseIds().length) * 100) : 0,
    inputCoverage,
    exitCoverage,
    artifactCoverage,
    decisionCoverage,
    recommendedDecisionCount,
    approvedDecisionCount,
    approvalCoverage,
    stakeholderCoverage,
    freshnessCoverage,
    confidence,
    recommendations,
    breakdown,
    complete: readinessScore >= 70 && blockers.length === 0,
  };
}

async function streamSingleAIResponse(system, user) {
  let output = "";
  await callClaude(system, user, (chunk) => {
    output += chunk;
  });
  return output.trim();
}

function reportAsyncActionError(actionLabel, error) {
  console.error(`${actionLabel} failed`, error);
  // Errors are surfaced inline via AsyncButton error prop — no alert needed
}

function UndoToast() {
  const { undo, redo, canUndo: canUndoState, canRedo: canRedoState } = useUndoState();
  const [visible, setVisible] = useState(false);
  const [message, setMessage] = useState("");
  const timerRef = useRef(null);

  useEffect(() => {
    const handleUpdate = (event) => {
      if (event?.detail?.skipUndoSnapshot) return;
      const projectId = event?.detail?.projectId || _activeProjectId;
      const label = event?.detail?.undoLabel || getLastActionLabel(projectId);
      if (!canUndo(projectId) || !label || label === "Initial state") return;
      setMessage(label);
      setVisible(true);
      clearTimeout(timerRef.current);
      timerRef.current = setTimeout(() => setVisible(false), 6000);
    };
    window.addEventListener(ADAM_PROJECT_DATA_UPDATED_EVENT, handleUpdate);
    return () => {
      window.removeEventListener(ADAM_PROJECT_DATA_UPDATED_EVENT, handleUpdate);
      clearTimeout(timerRef.current);
    };
  }, []);

  useEffect(() => {
    setVisible(false);
  }, [_activeProjectId]);

  if (!visible) return null;

  return (
    <div style={{
      position: "fixed",
      bottom: 28,
      left: "50%",
      transform: "translateX(-50%)",
      background: "rgba(15,23,42,0.96)",
      border: "1px solid rgba(168,182,209,0.22)",
      borderRadius: 12,
      padding: "10px 16px",
      display: "flex",
      alignItems: "center",
      gap: 12,
      boxShadow: "0 8px 32px rgba(0,0,0,0.32)",
      zIndex: 9999,
      minWidth: 260,
      maxWidth: 440,
      backdropFilter: "blur(12px)",
    }}>
      <span style={{ fontSize: 12, color: "rgba(229,231,235,0.9)", flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
        {message}
      </span>
      {canUndoState && (
        <button type="button" onClick={() => { undo(); setVisible(false); }} style={{ height: 28, padding: "0 12px", borderRadius: 8, border: "1px solid rgba(168,182,209,0.28)", background: "rgba(255,255,255,0.08)", color: "rgba(229,231,235,0.9)", fontSize: 11.5, fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap", flexShrink: 0 }}>
          ↩ Undo
        </button>
      )}
      {canRedoState && (
        <button type="button" onClick={() => { redo(); setVisible(false); }} style={{ height: 28, padding: "0 12px", borderRadius: 8, border: "1px solid rgba(168,182,209,0.28)", background: "rgba(255,255,255,0.08)", color: "rgba(229,231,235,0.9)", fontSize: 11.5, fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap", flexShrink: 0 }}>
          ↪ Redo
        </button>
      )}
      <button type="button" onClick={() => setVisible(false)} style={{ background: "transparent", border: "none", color: "rgba(156,163,175,0.7)", fontSize: 14, cursor: "pointer", padding: "0 2px", flexShrink: 0 }}>✕</button>
    </div>
  );
}

async function generateDeliveryPlan(projectId = _activeProjectId, { teamOnly = false } = {}) {
  const project = getProjects().find((item) => item.id === projectId) || getActiveProject();
  if (!project) throw new Error("No active program is available.");
  const data = getProjectData(project);
  const existingMobiliseInputs = {
    ...createEmptyPhaseGuidance().mobilise.fields,
    ...(data.phaseGuidance?.mobilise?.fields || {}),
  };
  const autonomyLevel = highestAutonomyLevelAcrossCapabilities(project);
  const autonomyDescription = getAutonomyMeta(autonomyLevel).description;
  const deliveryPlanContext = {
    program: project.name,
    client: project.client,
    industry: project.industry,
    autonomyLevel,
    phases: getJourneyPhaseIds().map((id) => ({
      id,
      exitCriteria: (ADAM_METHODOLOGY.phases[id === "operate" ? "govern" : id]?.exitCriteria || []),
      artifacts: (ADAM_METHODOLOGY.phases[id === "operate" ? "govern" : id]?.artifacts || []),
    })),
    capabilities: (data.design?.capabilities || data.capabilities || []).map((capability) => ({
      name: capability.capabilityName || capability.name || "Capability",
      autonomyLevel: capability.autonomyLevel || "L0",
      linkedWorkflows: capability.linkedWorkflows?.length || 0,
    })),
    existingDeliveryRoles: data.mobilise?.deliveryRoles || [],
    readinessSignal: data.readiness || {},
    outcomes: data.discover?.outcomes || data.discoverContext || {},
    privacyFlags: data.discover?.privacyConstraints || data.discoverContext?.compliance || "",
    teamComposition: data.build?.teamComposition || data.phaseGuidance?.build?.fields?.teamPlan || "",
    existingMobiliseInputs,
  };
  const phaseList = deliveryPlanContext.phases.map((phase) => phase.id).join(", ");
  const capabilityList = deliveryPlanContext.capabilities.map((capability) => `${capability.name} (${capability.autonomyLevel})`).join(", ") || "No capabilities defined";
  const existingRoles = deliveryPlanContext.existingDeliveryRoles.map((role) => `${role.personName || "TBD"} — ${role.roleType}`).join(", ") || "No delivery roles defined";
  const system = `You are ADAM, Brillio's Agentic Transformation AI.
Generate a structured delivery plan for this program.
Improve the existing mobilisation inputs where they already exist. Refine, complete, and strengthen them.
Do not blank out good existing information. Only replace an existing value if the improved wording is clearer or more actionable.

Program: ${deliveryPlanContext.program} | ${deliveryPlanContext.client} | ${deliveryPlanContext.industry}
Autonomy level: ${autonomyLevel} — ${autonomyDescription}

Phases to deliver: ${phaseList}
Capabilities in scope: ${capabilityList}
Existing team: ${existingRoles}

Produce JSON only. Format it so it can be parsed into DeliveryRole, Workplan, RACI, ChangeImpact, CommunicationPlan, TrainingPlan, and ChangeNetwork objects.`;
  const user = `Context:
${JSON.stringify(deliveryPlanContext, null, 2)}

Return this shape only:
{
  "mobiliseInputs": {"programLead":"","executiveSponsor":"","targetCapability":"","programStartDate":"","governanceCadence":"","changeApproach":""},
  "deliveryRoles": [{"roleName":"","roleType":"","personName":"","allocation":"","activePhases":[],"responsibilities":[],"linkedWorkstreams":[],"linkedPersona":"","raci":{}}],
  "workplan": {"programName":"","startDate":"","targetEndDate":"","phases":[{"phaseId":"","plannedStart":"","plannedEnd":"","actualStart":"","actualEnd":"","status":"not started","workstreams":[{"name":"","lead":"","tasks":[{"name":"","owner":"","dueDate":"","status":"not started","linkedArtifacts":[],"linkedObjects":[],"dependencies":[]}],"status":"not started"}],"keyDependencies":[],"exitCriteriaStatus":{}}],"milestones":[{"name":"","targetDate":"","status":"","linkedPhase":"","linkedExitCriteria":""}],"criticalPath":[],"assumptions":[],"lastReviewedDate":""},
  "raci": {"entries":[{"item":"","phase":"","responsible":[],"accountable":"","consulted":[],"informed":[]}]},
  "changeImpacts": [{"impactedGroup":"","impactLevel":"medium","resistanceRisk":"medium","impactType":[],"currentState":"","futureState":"","resistanceDrivers":[],"readinessScore":2,"linkedCapability":""}],
  "stakeholderEngagements": [{"stakeholderName":"","stakeholderGroup":"","currentSentiment":"neutral","targetSentiment":"supportive","influenceLevel":"medium","engagementApproach":"","keyMessages":[],"engagementActions":[],"reviewCadence":""}],
  "communicationPlans": [{"audience":"","messageTheme":"","channel":"workshop","frequency":"","owner":"","plannedDate":"","status":"planned","linkedPhase":"mobilise","notes":""}],
  "trainingPlans": [{"targetAudience":"","trainingNeed":"","trainingType":"awareness","deliveryMethod":"workshop","plannedDate":"","completionDate":"","completionRate":0,"linkedCapability":"","linkedSkill":"","status":"planned"}],
  "changeNetwork": {"networkName":"ADAM Change Network","purpose":"","members":[],"activationDate":"","meetingCadence":"","linkedCapabilities":[],"coverageScore":0},
  "governanceCadence": {"steeringFrequency":"","gateOwner":"","reviewCadence":"","escalationPath":""}
}

For mobiliseInputs:
- improve the current wording rather than replacing with generic text
- preserve any field that is already strong if no better improvement is available
- targetCapability should be a concrete capability name, not a broad function label unless nothing more specific is known

If teamOnly is true, still return the full shape but prioritize mobiliseInputs, deliveryRoles, workplan, raci, and governanceCadence.
teamOnly=${teamOnly}`;
  const text = await streamSingleAIResponse(system, user);
  const parsed = extractJsonObject(text);
  if (!parsed || typeof parsed !== "object") {
    throw new Error("ADAM could not generate a structured delivery plan.");
  }
  updateActiveProjectData((nextData) => {
    const existingGuidance = {
      ...createEmptyPhaseGuidance().mobilise.fields,
      ...(nextData.phaseGuidance?.mobilise?.fields || {}),
    };
    const inferredMobiliseInputs = {
      programLead:
        parsed.mobiliseInputs?.programLead
        || existingGuidance.programLead
        || parsed.deliveryRoles?.find((role) => String(role.roleType || "").toLowerCase() === "program lead")?.personName
        || "",
      executiveSponsor:
        parsed.mobiliseInputs?.executiveSponsor
        || existingGuidance.executiveSponsor
        || project.sponsor
        || "",
      targetCapability:
        parsed.mobiliseInputs?.targetCapability
        || existingGuidance.targetCapability
        || parsed.workplan?.phases?.[0]?.linkedCapability
        || deliveryPlanContext.capabilities[0]?.name
        || "",
      programStartDate:
        parsed.mobiliseInputs?.programStartDate
        || existingGuidance.programStartDate
        || parsed.workplan?.startDate
        || "",
      governanceCadence:
        parsed.mobiliseInputs?.governanceCadence
        || existingGuidance.governanceCadence
        || parsed.governanceCadence?.steeringFrequency
        || "",
      changeApproach:
        parsed.mobiliseInputs?.changeApproach
        || existingGuidance.changeApproach
        || parsed.changeNetwork?.purpose
        || parsed.communicationPlans?.[0]?.messageTheme
        || "",
    };
    nextData.phaseGuidance = {
      ...createEmptyPhaseGuidance(),
      ...(nextData.phaseGuidance || {}),
      mobilise: {
        ...createEmptyPhaseGuidance().mobilise,
        ...(nextData.phaseGuidance?.mobilise || {}),
        lastUpdated: stampNow(),
        fields: {
          ...existingGuidance,
          ...Object.fromEntries(
            Object.entries(inferredMobiliseInputs).map(([fieldId, value]) => [
              fieldId,
              typeof value === "string" && value.trim() ? value.trim() : existingGuidance[fieldId] || "",
            ]),
          ),
        },
      },
    };
    const nextDeliveryRoles = (parsed.deliveryRoles || []).length
      ? mergeCapturedDeliveryRoles([], parsed.deliveryRoles)
      : (nextData.mobilise?.deliveryRoles || []);
    const nextWorkplan = parsed.workplan
      ? createMethodologyBaseObject(parsed.workplan.programName || `${project.name} Workplan`, "Workplan", "mobilise", parsed.workplan)
      : nextData.mobilise?.workplan || null;
    const nextRaci = parsed.raci
      ? createMethodologyBaseObject("Program RACI", "RACI", "mobilise", parsed.raci)
      : nextData.mobilise?.raci || null;
    const nextChangeImpacts = (parsed.changeImpacts || []).length
      ? (parsed.changeImpacts || []).map((impact, index) => createMethodologyBaseObject(impact.impactedGroup || `Change Impact ${index + 1}`, "ChangeImpact", "mobilise", impact))
      : (nextData.mobilise?.changeImpacts || []);
    const nextStakeholderEngagements = (parsed.stakeholderEngagements || []).length
      ? (parsed.stakeholderEngagements || []).map((plan, index) => createMethodologyBaseObject(plan.stakeholderName || `Stakeholder ${index + 1}`, "StakeholderEngagementPlan", "mobilise", plan))
      : (nextData.mobilise?.stakeholderEngagements || []);
    const nextCommunicationPlans = (parsed.communicationPlans || []).length
      ? (parsed.communicationPlans || []).map((plan, index) => createMethodologyBaseObject(plan.audience || `Communication ${index + 1}`, "CommunicationPlan", "mobilise", plan))
      : (nextData.mobilise?.communicationPlans || []);
    const nextTrainingPlans = (parsed.trainingPlans || []).length
      ? (parsed.trainingPlans || []).map((plan, index) => createMethodologyBaseObject(plan.targetAudience || `Training ${index + 1}`, "TrainingPlan", "mobilise", plan))
      : (nextData.mobilise?.trainingPlans || []);
    const nextChangeNetwork = parsed.changeNetwork
      ? createMethodologyBaseObject(parsed.changeNetwork.networkName || "ADAM Change Network", "ChangeNetwork", "mobilise", parsed.changeNetwork)
      : nextData.mobilise?.changeNetwork || null;
    const nextGovernanceCadence = {
      ...(nextData.mobilise?.governanceCadence || {}),
      ...(parsed.governanceCadence || {}),
    };
    nextData.mobilise = {
      ...createEmptyMobiliseData(),
      ...(nextData.mobilise || {}),
      ...(teamOnly ? {
        deliveryRoles: nextDeliveryRoles,
        workplan: nextWorkplan,
        raci: nextRaci,
        governanceCadence: nextGovernanceCadence,
      } : {
        deliveryRoles: nextDeliveryRoles,
        workplan: nextWorkplan,
        raci: nextRaci,
        changeImpacts: nextChangeImpacts,
        stakeholderEngagements: nextStakeholderEngagements,
        communicationPlans: nextCommunicationPlans,
        trainingPlans: nextTrainingPlans,
        changeNetwork: nextChangeNetwork,
        governanceCadence: nextGovernanceCadence,
      }),
    };
    nextData.discover = {
      ...(nextData.discover || {}),
      changeManagement: {
        ...createEmptyPhaseChangeManagement(),
        ...((nextData.discover || {}).changeManagement || {}),
        impacts: (nextChangeImpacts || []).map((item) => item.id),
        engagements: (nextStakeholderEngagements || []).map((item) => item.id),
        communications: (nextCommunicationPlans || []).filter((item) => !item.linkedPhase || item.linkedPhase === "discover" || item.linkedPhase === "mobilise").map((item) => item.id),
        training: (nextTrainingPlans || []).map((item) => item.id),
      },
    };
  });
  return parsed;
}

