const PHASE_AGENT_EVENT = "adam:phase-agent-event";
const AGENT_TRIGGER_EVENT = "adam:agent-trigger";
const APP_NAVIGATE_EVENT = "adam:navigate";

const GATE_REVIEW_OPEN_EVENT = "adam:gate-review-open";

const PhaseAgentEventBus = {
  _handlers: {},

  publish(payload) {
    if (typeof window === "undefined") return;
    window.dispatchEvent(new CustomEvent(PHASE_AGENT_EVENT, { detail: payload }));
  },

  subscribe(phaseId, handler) {
    if (typeof window === "undefined" || typeof handler !== "function") return () => {};
    const wrapped = (event) => {
      if (!event?.detail) return;
      handler(event.detail);
    };
    if (!PhaseAgentEventBus._handlers[phaseId]) {
      PhaseAgentEventBus._handlers[phaseId] = [];
    }
    PhaseAgentEventBus._handlers[phaseId].push({ handler, wrapped });
    window.addEventListener(PHASE_AGENT_EVENT, wrapped);
    return () => PhaseAgentEventBus.unsubscribe(phaseId, handler);
  },

  unsubscribe(phaseId, handler) {
    if (typeof window === "undefined") return;
    const list = PhaseAgentEventBus._handlers[phaseId] || [];
    const entry = list.find((item) => item.handler === handler);
    if (entry) {
      window.removeEventListener(PHASE_AGENT_EVENT, entry.wrapped);
      PhaseAgentEventBus._handlers[phaseId] = list.filter((item) => item.handler !== handler);
    }
  },
};

function dispatchAgentTrigger(rule, context) {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new CustomEvent(AGENT_TRIGGER_EVENT, {
    detail: { rule, context },
  }));
}

function queueAgentTriggers(eventType, context, programState = null) {
  evaluateTriggers(
    eventType,
    { ...context, programState },
    DEFAULT_TRIGGER_RULES,
    (rule) => dispatchAgentTrigger(rule, context),
  );
}

const PhaseAgentQueue = (() => {
  let running = 0;
  const queue = [];

  function priorityScore(item) {
    const urgencyMap = { overdue: 0, critical: 1, high: 2, medium: 3, none: 4 };
    const urgency = urgencyMap[item.urgencyLevel] ?? 4;
    const readiness = Number(item.gateReadiness ?? 0);
    const seqIndex = ADAM_PHASE_SEQUENCE.indexOf(item.phaseId);
    return (urgency * 1000) + (readiness * 10) + (seqIndex === -1 ? 99 : seqIndex);
  }

  function drain(maxConcurrent = 2) {
    while (running < maxConcurrent && queue.length) {
      queue.sort((left, right) => priorityScore(left) - priorityScore(right));
      const next = queue.shift();
      if (!next) return;
      running += 1;
      Promise.resolve()
        .then(() => next.run())
        .catch(() => {})
        .finally(() => {
          running -= 1;
          drain(maxConcurrent);
        });
    }
  }

  return {
    enqueue(phaseId, urgencyLevel, gateReadiness, runFn, maxConcurrent = 2) {
      if (queue.some((item) => item.phaseId === phaseId)) return;
      queue.push({ phaseId, urgencyLevel, gateReadiness, run: runFn });
      drain(maxConcurrent);
    },
    get queueLength() {
      return queue.length;
    },
    get activeCount() {
      return running;
    },
    get snapshot() {
      return queue.map((item) => ({
        phaseId: item.phaseId,
        urgencyLevel: item.urgencyLevel,
        gateReadiness: item.gateReadiness,
      }));
    },
  };
})();

