function normalizeRaciRows(raci) {
  if (Array.isArray(raci?.rows)) return raci.rows;
  if (Array.isArray(raci?.entries)) return raci.entries;
  if (Array.isArray(raci)) return raci;
  if (raci && typeof raci === "object") {
    return Object.entries(raci).map(([item, value]) => {
      if (value && typeof value === "object" && !Array.isArray(value)) {
        return {
          item,
          ...value,
        };
      }
      return { item, accountable: value };
    });
  }
  return [];
}
