function getIndustryArchetypes(industry) {
  const accelerator = INDUSTRY_ACCELERATOR_LIBRARY[industry] || INDUSTRY_ACCELERATOR_LIBRARY["Life Sciences"];
  const crmOverrides = industry === "Information Technology"
    ? [
        {
          label: "Agentic CRM",
          summary: "End-to-end CRM transformation archetype for pipeline, service, and revenue operations.",
          discoverProblem: "CRM teams are constrained by fragmented lead-to-revenue workflows, inconsistent account intelligence, and slow follow-through across sales, service, and customer success.",
          discoverOutcome: "Increase seller productivity, improve forecast quality, and reduce customer-response latency through an agentic CRM operating model.",
          designCapability: "Customer relationship orchestration capability spanning lead qualification, account research, opportunity progression, service resolution, and success planning.",
          agentMission: "Coordinate CRM work across sales, service, and customer success by surfacing next-best actions, automating follow-up, and escalating exceptions to human owners.",
          governanceFocus: `${accelerator.regulations?.join(", ") || "Enterprise controls"} plus customer-data stewardship, approval boundaries, and revenue-impact traceability.`,
          valueMetric: "Improve conversion, forecast accuracy, win rate, and retention while reducing admin time and response delays.",
        },
        {
          label: "Revenue Intelligence",
          summary: "Use AI to unify pipeline insight, account signals, and seller recommendations.",
          discoverProblem: "Revenue teams lack a trusted system that turns account data, activity history, and customer signals into actionable sales guidance.",
          discoverOutcome: "Give frontline teams a timely, trusted view of risk, opportunity quality, and next-best actions across the funnel.",
          designCapability: "Revenue intelligence capability for account research, opportunity scoring, forecast explanation, and executive pipeline insight.",
          agentMission: "Continuously synthesize CRM, activity, and customer data into seller guidance, pipeline warnings, and leadership-ready summaries.",
          governanceFocus: "Ensure model recommendations are explainable, auditable, and bounded by customer-data permissions and approval controls.",
          valueMetric: "Lift forecast confidence, improve pipeline hygiene, and shorten time to insight for account teams and leaders.",
        },
      ]
    : [];
  const industryPatterns = crmOverrides.length
    ? crmOverrides
    : (accelerator.patterns || []).slice(0, 4).map((pattern) => ({
        label: pattern,
        summary: `${pattern} operating archetype built for ${industry}.`,
        discoverProblem: `${pattern} is constrained by fragmented workflows, slow decisions, and inconsistent operating controls across ${industry} teams.`,
        discoverOutcome: `Improve cycle time, quality, and enterprise control posture for ${pattern.toLowerCase()} in ${industry}.`,
        designCapability: `${pattern} orchestration capability with clear human, agent, and governance boundaries.`,
        agentMission: `${pattern} agent that coordinates work, proposes next actions, and escalates exceptions.`,
        governanceFocus: `${accelerator.regulations?.join(", ") || "Enterprise controls"} readiness must be embedded from the start.`,
        valueMetric: `Reduce latency and improve throughput for ${pattern.toLowerCase()} while tracking quality and compliance.`,
      }));
  const basePatterns = [...industryPatterns, ...USE_CASE_ACCELERATORS].slice(0, 6);
  return basePatterns.map((pattern, idx) => ({
    id: `${industry.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${idx + 1}`,
    ...pattern,
  }));
}

