function buildPhasePlaybookSummary(phaseId) {
  const playbook = ADAM_PHASE_PLAYBOOK[normalizeGuideViewId(phaseId)];
  if (!playbook) return "No playbook defined.";
  return [
    playbook.intro || "",
    playbook.fields?.length ? `Fields: ${playbook.fields.map((field) => field.label).join(", ")}.` : "",
    playbook.nextPhase ? `Next phase: ${playbook.nextPhase}.` : "",
  ].filter(Boolean).join(" ");
}

function buildArtifactDependencyChain(phaseId) {
  const key = normalizeGuideViewId(phaseId);
  return getPhaseArtifactsForView(key)
    .filter((artifact) => artifact.status !== "blank")
    .slice(0, 6)
    .map((artifact) => `${artifact.label}${artifact.dependencies?.length ? ` ← ${artifact.dependencies.slice(0, 2).join(", ")}` : ""}`)
    .join("\n");
}

function upsertTwinNodeInGraph(graph, node) {
  const existingIndex = graph.nodes.findIndex((item) =>
    (node.linkedArtifactId && item.linkedArtifactId === node.linkedArtifactId)
    || (item.type === node.type && String(item.label || "").toLowerCase() === String(node.label || "").toLowerCase())
  );
  if (existingIndex >= 0) {
    graph.nodes[existingIndex] = { ...graph.nodes[existingIndex], ...node };
    return graph.nodes[existingIndex];
  }
  graph.nodes.push(node);
  return node;
}

function ensureTwinEdge(graph, edge) {
  const exists = graph.edges.some((item) => item.from === edge.from && item.to === edge.to && item.type === edge.type);
  if (!exists) graph.edges.push(edge);
}

function pruneTwinOrphans(twinGraph, projectData) {
  const nodes = [...(twinGraph?.nodes || [])];
  const edges = [...(twinGraph?.edges || [])];
  const validArtifactIds = new Set();
  (projectData?.discoverContext?.capabilityDNA || []).forEach((item) => validArtifactIds.add(item.id));
  (projectData?.architecture?.decisions || []).forEach((item) => validArtifactIds.add(item.id));
  (projectData?.architecture?.skillCatalog || []).forEach((item) => validArtifactIds.add(item.id));
  const activeNodeIds = new Set();
  const prunedNodes = nodes.filter((node) => {
    if (node.linkedArtifactId && validArtifactIds.size && !validArtifactIds.has(node.linkedArtifactId) && ["Capability", "Decision", "Skill"].includes(node.type)) {
      return false;
    }
    activeNodeIds.add(node.id);
    return true;
  });
  const prunedEdges = edges.filter((edge) => activeNodeIds.has(edge.from) && activeNodeIds.has(edge.to));
  return { ...twinGraph, nodes: prunedNodes, edges: prunedEdges, lastUpdated: new Date().toISOString() };
}

function syncTwinFromProjectState(phaseId, data, twinGraph = data?.twinGraph || { nodes: [], edges: [] }) {
  const nodes = [...(twinGraph.nodes || [])];
  const edges = [...(twinGraph.edges || [])];

  function upsertNode(type, label, phaseCreated, extra = {}) {
    const existing = nodes.find((node) => node.type === type && node.label === label);
    if (existing) {
      const mergedProperties = extra.properties
        ? { ...(existing.properties || {}), ...extra.properties }
        : (existing.properties || {});
      Object.assign(existing, extra);
      existing.properties = mergedProperties;
      return existing.id;
    }
    const nextNode = createTwinNode(type, label, phaseCreated, {
      ...extra,
      properties: { ...(extra.properties || {}) },
    });
    nodes.push(nextNode);
    return nextNode.id;
  }

  function upsertEdge(fromId, toId, edgeType) {
    if (!fromId || !toId) return;
    const fromNode = nodes.find((node) => node.id === fromId);
    const toNode = nodes.find((node) => node.id === toId);
    if (!fromNode || !toNode) return;
    const allowedPairs = TWIN_EDGE_RULES[edgeType] || [];
    if (allowedPairs.length && !allowedPairs.some(([fromType, toType]) => fromNode.type === fromType && toNode.type === toType)) {
      return;
    }
    const exists = edges.find((edge) => edge.from === fromId && edge.to === toId && edge.type === edgeType);
    if (!exists) edges.push(createTwinEdge(fromId, toId, edgeType));
  }

  const normalizedPhase = normalizeGuideViewId(phaseId);

  if (normalizedPhase === "strategy" && data.strategyData) {
    const strategyData = data.strategyData;
    const strategyId = upsertNode("Strategy", strategyData.mandate || "Program Mandate", "strategy", { confidence: 0.9 });
    (strategyData.successDefinition || "")
      .split(/[;,\n]/)
      .map((item) => item.trim())
      .filter(Boolean)
      .forEach((item) => {
        const outcomeId = upsertNode("Outcome", item, "strategy");
        upsertEdge(outcomeId, strategyId, "achieves");
      });
  }

  if (normalizedPhase === "discover" && data.discoverContext) {
    const discoverContext = data.discoverContext;
    const outcomeLabels = String(discoverContext.outcomes || "")
      .split(/[;,\n]/)
      .map((item) => item.trim())
      .filter(Boolean);
    outcomeLabels.forEach((outcome) => {
      upsertNode("Outcome", outcome, "discover", { confidence: 0.8 });
    });
    const kpis = Array.isArray(discoverContext.kpis)
      ? discoverContext.kpis
      : String(discoverContext.kpis || "")
        .split(/[;,\n]/)
        .map((item) => item.trim())
        .filter(Boolean);
    kpis.forEach((kpi) => {
      const kpiLabel = typeof kpi === "string" ? kpi : kpi.name || kpi.label;
      if (kpiLabel) {
        const kpiId = upsertNode("KPI", kpiLabel, "discover", {
          properties: { baseline: kpi?.baseline, target: kpi?.target },
        });
        const matchingOutcome = nodes.find((node) => node.type === "Outcome");
        if (matchingOutcome) upsertEdge(kpiId, matchingOutcome.id, "measures");
      }
    });
    (discoverContext.capabilityDNA || []).forEach((capability) => {
      const capabilityId = upsertNode("Capability", capability.name, "discover", {
        status: capability.status || "draft",
        confidence: capability.status === "approved" ? 0.9 : 0.5,
        linkedArtifactId: capability.id,
        properties: {
          autonomyLevel: capability.autonomyLevel || "L1",
          hitlPolicy: capability.hitlPolicy || "",
          dependsOn: Array.isArray(capability.dependsOn) ? capability.dependsOn : [],
        },
      });
      (capability.linkedOutcomes || []).forEach((outLabel) => {
        const outcomeNode = nodes.find((node) => node.type === "Outcome" && node.label === outLabel);
        if (outcomeNode) upsertEdge(capabilityId, outcomeNode.id, "enables");
      });
    });
    (discoverContext.capabilityDNA || []).forEach((capability) => {
      const capabilityNode = nodes.find((node) => node.type === "Capability" && (node.linkedArtifactId === capability.id || node.label === capability.name));
      (Array.isArray(capability.dependsOn) ? capability.dependsOn : []).forEach((dependencyRef) => {
        const dependencyNode = nodes.find((node) => node.type === "Capability" && (node.linkedArtifactId === dependencyRef || node.label === dependencyRef));
        if (capabilityNode && dependencyNode) upsertEdge(capabilityNode.id, dependencyNode.id, "depends_on");
      });
    });
  }

  if (normalizedPhase === "design" && data.architecture) {
    (data.architecture.decisions || []).forEach((decision) => {
      const decisionId = upsertNode("Decision", decision.title || decision.name, "design", {
        status: decision.status || "draft",
        confidence: decision.status === "approved" ? 0.9 : 0.6,
        linkedArtifactId: decision.id,
      });
      (decision.linkedCapabilityIds || []).forEach((capId) => {
        const capNode = nodes.find((node) => node.linkedArtifactId === capId || node.label === capId);
        if (capNode) upsertEdge(decisionId, capNode.id, "governs");
      });
    });
    const skillCatalog = data.architecture?.skillCatalog || data.design?.skillCatalog || [];
    skillCatalog.forEach((skill) => {
      const skillId = upsertNode("Skill", skill.name || skill.label, "design", {
        linkedArtifactId: skill.id,
        status: skill.status || "draft",
        properties: { skillType: skill.skillType || skill.type, autonomyLevel: skill.autonomyLevel },
      });
      const relatedCapability = nodes.find((node) => node.type === "Capability" && (skill.linkedCapabilityIds || []).includes(node.linkedArtifactId));
      if (relatedCapability) upsertEdge(skillId, relatedCapability.id, "implements");
    });
    const dataRequirements = data.architecture?.dataArchitectureDecision?.dataSources
      || data.discoverContext?.capabilityDNA?.flatMap((item) => item.dataRequirements || [])
      || [];
    [...new Set(dataRequirements.map((item) => typeof item === "string" ? item : item?.name).filter(Boolean))].forEach((dataSource) => {
      const dataId = upsertNode("Data", dataSource, "design");
      nodes.filter((node) => node.type === "Capability").forEach((capabilityNode) => {
        upsertEdge(dataId, capabilityNode.id, "consumed_by");
      });
    });
  }

  if (normalizedPhase === "mobilise" && data.mobilise) {
    (data.mobilise.deliveryRoles || []).forEach((role) => {
      const roleId = upsertNode("Role", role.personName || role.roleName, "mobilise", {
        properties: { roleType: role.roleType, allocation: role.allocation },
      });
      const capNodes = nodes.filter((node) => node.type === "Capability");
      if (capNodes.length > 0) upsertEdge(roleId, capNodes[0].id, "implements");
    });
  }

  if (normalizedPhase === "govern" && data.govern) {
    (data.govern?.risks || data.govern?.capturedRisks || []).forEach((risk) => {
      upsertNode("Risk", risk.title || risk.label || risk || "Unnamed Risk", "govern", {
        properties: { severity: risk?.severity },
      });
    });
    const governanceId = upsertNode("Governance", "Governance Framework", "govern", { confidence: 0.8 });
    nodes.filter((node) => node.type === "Risk").forEach((riskNode) => upsertEdge(governanceId, riskNode.id, "mitigates"));
  }

  if ((normalizedPhase === "build" || normalizedPhase === "operate" || normalizedPhase === "govern") && data) {
    const agentRegistry = Array.isArray(data?.govern?.agentRegistry)
      ? data.govern.agentRegistry
      : Array.isArray(data?.build?.agentRegistry)
        ? data.build.agentRegistry
        : [];
    agentRegistry.forEach((agent) => {
      const agentId = upsertNode("Agent", agent.name || agent.agentType, "build", {
        linkedArtifactId: agent.id || null,
        status: agent.status || "draft",
        confidence: agent.status === "approved" ? 0.9 : 0.6,
        properties: { autonomyLevel: agent.autonomyLevel, trustLevel: agent.trustLevel },
      });
      (agent.linkedCapabilityIds || []).forEach((capId) => {
        const capNode = nodes.find((node) => node.linkedArtifactId === capId);
        if (capNode) upsertEdge(agentId, capNode.id, "implements");
      });
      (agent.skills || agent.requiredSkills || []).forEach((skillLabel) => {
        const skillNode = nodes.find((node) => node.type === "Skill" && node.label === skillLabel);
        if (skillNode) upsertEdge(agentId, skillNode.id, "requires");
      });
    });
  }

  if (normalizedPhase === "valuerealize" && data.valueRealizeData) {
    const valueData = data.valueRealizeData;
    const valueId = upsertNode("Value", "Realized Value", "valuerealize", {
      properties: { report: valueData.executiveValueReport, roi: valueData.agentRoiAttribution },
    });
    const kpiActuals = Array.isArray(valueData.kpiActuals)
      ? valueData.kpiActuals
      : String(valueData.kpiActuals || "")
        .split(/[;,\n]/)
        .map((item) => item.trim())
        .filter(Boolean)
        .map((name) => ({ name, actual: "" }));
    kpiActuals.forEach((kpi) => {
      const kpiLabel = typeof kpi === "string" ? kpi : kpi.name;
      const existing = nodes.find((node) => node.type === "KPI" && node.label === kpiLabel);
      if (existing) {
        existing.properties = { ...(existing.properties || {}), actual: kpi.actual };
      } else {
        const kpiId = upsertNode("KPI", kpiLabel || "KPI", "valuerealize");
        upsertEdge(kpiId, valueId, "measures");
      }
    });
    if (valueData.lessonsForNextCycle) {
      upsertNode("Learning", String(valueData.lessonsForNextCycle).slice(0, 80), "valuerealize");
    }
  }

  nodes.forEach((node) => {
    if (node.type !== "Capability") return;
    const hasOutcomeLink = edges.some((edge) => edge.from === node.id && edge.type === "enables" && nodes.find((candidate) => candidate.id === edge.to)?.type === "Outcome");
    node.properties = {
      ...(node.properties || {}),
      outcomeLinked: hasOutcomeLink,
    };
    if (!hasOutcomeLink) {
      node.properties.warning = "No linked outcome";
    } else if (node.properties.warning === "No linked outcome") {
      delete node.properties.warning;
    }
  });

  const pruned = pruneTwinOrphans({ nodes, edges }, data);
  const nextGraph = { nodes: pruned.nodes, edges: pruned.edges, lastUpdated: new Date().toISOString() };
  data.twinGraph = nextGraph;
  return nextGraph;
}

function buildTwinExecutiveSummary(twinGraph = { nodes: [], edges: [] }) {
  if (!twinGraph || (twinGraph.nodes || []).length === 0) return "";
  const nodes = twinGraph.nodes || [];
  const count = (type) => nodes.filter((node) => node.type === type).length;
  const approved = (type) => nodes.filter((node) => node.type === type && node.status === "approved").length;
  const outcomes = nodes.filter((node) => node.type === "Outcome").map((node) => node.label).slice(0, 3);
  const kpis = nodes.filter((node) => node.type === "KPI");
  const kpisWithActuals = kpis.filter((node) => node.properties?.actual).length;
  const risks = nodes.filter((node) => node.type === "Risk");
  const criticalRisks = risks.filter((node) => node.properties?.severity === "critical" || node.properties?.severity === "high").length;

  return [
    count("Strategy") > 0 ? `Strategy: ${nodes.find((node) => node.type === "Strategy")?.label || "defined"}` : null,
    count("Outcome") > 0 ? `Outcomes: ${count("Outcome")} (top: ${outcomes.join(", ")})` : null,
    count("Capability") > 0 ? `Capabilities: ${count("Capability")} total, ${approved("Capability")} approved` : null,
    count("Agent") > 0 ? `Agents: ${count("Agent")} designed, ${approved("Agent")} approved` : null,
    count("KPI") > 0 ? `KPIs: ${kpisWithActuals}/${kpis.length} with actuals captured` : null,
    risks.length > 0 ? `Risks: ${risks.length} tracked (${criticalRisks} critical/high)` : null,
  ].filter(Boolean).join(" | ");
}

function simulateTwinNodeRemoval(nodeId, twinGraph = { nodes: [], edges: [] }) {
  const nodes = Array.isArray(twinGraph?.nodes) ? twinGraph.nodes : [];
  const edges = Array.isArray(twinGraph?.edges) ? twinGraph.edges : [];
  const removedNode = nodes.find((node) => node.id === nodeId) || null;
  if (!removedNode) return { removedNode: null, impactedNodes: [], impactSummary: "No matching Twin node was found." };
  const seen = new Set();
  const walk = (currentId) => {
    edges.filter((edge) => edge.from === currentId).forEach((edge) => {
      if (seen.has(edge.to)) return;
      seen.add(edge.to);
      walk(edge.to);
    });
  };
  walk(nodeId);
  const impactedNodes = nodes.filter((node) => seen.has(node.id));
  const impactSummary = `Removing '${removedNode.label}' (${removedNode.type}) impacts ${impactedNodes.length} downstream nodes: ${impactedNodes.slice(0, 5).map((node) => node.label).join(", ")}${impactedNodes.length > 5 ? ` and ${impactedNodes.length - 5} more` : ""}.`;
  return { removedNode, impactedNodes, impactSummary };
}

function parseMagnitudeValue(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return 0;
  const numeric = Number(raw.replace(/[^0-9.]/g, "")) || 0;
  if (/b(illion)?/i.test(raw)) return numeric * 1000;
  if (/m(illion)?/i.test(raw)) return numeric;
  if (/k(?!pi|pis|ey)/i.test(raw) || /thousand/i.test(raw)) return numeric / 1000;
  return numeric;
}

function formatMagnitudeMillions(value = 0) {
  if (!Number.isFinite(value) || value <= 0) return "$0";
  if (value >= 1000) return `$${(value / 1000).toFixed(1)}B`;
  if (value >= 1) return `$${value.toFixed(1)}M`;
  const thousands = value * 1000;
  if (thousands >= 1) return `$${thousands.toFixed(1)}K`;
  return `$${Math.round(value * 1000000)}`;
}

function parseTimelineMonths(value = "") {
  const raw = String(value || "").trim().toLowerCase();
  const numeric = Number(raw.match(/[0-9]+(?:\.[0-9]+)?/)?.[0] || 0);
  if (!numeric) return 0;
  if (raw.includes("year")) return Math.round(numeric * 12);
  if (raw.includes("week")) return Math.round(numeric / 4.345);
  if (raw.includes("day")) return Math.max(1, Math.round(numeric / 30));
  return Math.round(numeric);
}

function formatMoneyMillions(value = 0) {
  if (!Number.isFinite(value) || value <= 0) return "$0.0M";
  return `$${value.toFixed(1)}M`;
}

function calculateTwinScenarioMetrics(program = {}, sliders = {}, projectData = getProjectData(getActiveProject())) {
  const budgetPct = Number(sliders?.budget ?? 100);
  const timelinePct = Number(sliders?.timeline ?? 100);
  const teamPct = Number(sliders?.team ?? 100);
  const governancePct = Number(sliders?.governance ?? 100);
  const projectedValue = parseMagnitudeValue(program?.projectedValue);
  const deliveredValue = parseMagnitudeValue(program?.valueDelivered);
  const baselineMonths = parseTimelineMonths(program?.timeline) || 12;
  const capabilityCount = Math.max(1, getCAPABILITIES().length || 0);
  const gatePhasesAtRisk = ADAM_PHASE_SEQUENCE
    .map((phaseId) => ({ phaseId, gate: buildStageGateMemo(phaseId, projectData) }))
    .filter((entry) => entry.gate.readiness < 70)
    .slice(0, 3)
    .map((entry) => `${getPhaseDisplayLabel(entry.phaseId)} (${entry.gate.readiness}%)`);
  const stress = {
    budget: Math.max(0, 1 - budgetPct / 100),
    timeline: Math.max(0, 1 - timelinePct / 100),
    team: Math.max(0, 1 - teamPct / 100),
    governance: Math.max(0, 1 - governancePct / 100),
  };
  const weightedStress = (stress.budget * 0.35) + (stress.timeline * 0.25) + (stress.team * 0.2) + (stress.governance * 0.2);
  const valueAtRisk = projectedValue * Math.min(0.85, weightedStress * 0.95);
  const netValue = Math.max(0, projectedValue - valueAtRisk);
  const monthsSlip = Math.max(0, Math.round(baselineMonths * ((stress.timeline * 0.45) + (stress.team * 0.25) + (stress.governance * 0.2) + (stress.budget * 0.1))));
  const capabilitiesAtRisk = Math.max(0, Math.min(capabilityCount, Math.round(capabilityCount * ((stress.budget * 0.4) + (stress.team * 0.35) + (stress.governance * 0.25)))));
  const readinessDrop = Math.round(weightedStress * 28);
  const estimatedConfidence = Math.max(35, 88 - readinessDrop);
  const riskPosture = weightedStress >= 0.35 ? "High" : weightedStress >= 0.18 ? "Moderate" : "Contained";
  const mitigations = [
    stress.budget > 0.15 ? "Protect the highest-value capabilities and defer lower-value scope from the next release wave." : null,
    stress.timeline > 0.15 ? "Re-baseline milestones and lock decision turnaround times before compressing delivery windows further." : null,
    stress.team > 0.15 ? "Backfill specialist delivery roles or reduce concurrent capability build to match available capacity." : null,
    stress.governance > 0.15 ? "Shorten approval loops with pre-read packs and named decision owners for each stage gate." : null,
  ].filter(Boolean);
  const recommendation = weightedStress >= 0.35
    ? "Do not commit this scenario without re-scoping the transformation and protecting the core value path."
    : weightedStress >= 0.18
      ? "Proceed only with explicit mitigation owners and a tightened weekly risk review."
      : "This scenario is viable with routine monitoring and no major design changes.";

  return {
    budgetPct,
    timelinePct,
    teamPct,
    governancePct,
    projectedValue,
    deliveredValue,
    baselineMonths,
    capabilityCount,
    gatePhasesAtRisk,
    weightedStress,
    scenarioPressure: Math.round(weightedStress * 100),
    valueAtRisk,
    netValue,
    monthsSlip,
    capabilitiesAtRisk,
    readinessDrop,
    estimatedConfidence,
    riskPosture,
    mitigations,
    recommendation,
  };
}

function buildTwinScenarioFallbackReport(program = {}, sliders = {}, projectData = getProjectData(getActiveProject())) {
  const metrics = calculateTwinScenarioMetrics(program, sliders, projectData);
  return [
    "# Scenario Analysis — Brillio ADAM™",
    "",
    "## Executive Summary",
    `This local scenario estimate models the effect of changing budget, timeline, team capacity, and governance speed for ${program?.name || "the active program"}. Delivery confidence is estimated at ${metrics.estimatedConfidence}% with a ${metrics.riskPosture.toLowerCase()} risk posture under the current slider settings.`,
    "",
    "## Scenario Inputs",
    `- Budget retained: ${metrics.budgetPct}%`,
    `- Timeline retained: ${metrics.timelinePct}%`,
    `- Team capacity retained: ${metrics.teamPct}%`,
    `- Governance speed retained: ${metrics.governancePct}%`,
    "",
    "## Quantified Impact",
    `- Projected value at risk: ${formatMoneyMillions(metrics.valueAtRisk)}`,
    `- Remaining projected value: ${formatMoneyMillions(metrics.netValue)}`,
    `- Realized value already protected: ${formatMoneyMillions(metrics.deliveredValue)}`,
    `- Likely timeline slip: ${metrics.monthsSlip} month${metrics.monthsSlip === 1 ? "" : "s"}`,
    `- Capabilities at risk: ${metrics.capabilitiesAtRisk} of ${metrics.capabilityCount}`,
    "",
    "## Gate and Readiness Effect",
    `- Estimated delivery confidence after scenario shift: ${metrics.estimatedConfidence}%`,
    `- Phases currently most sensitive: ${metrics.gatePhasesAtRisk.join(", ") || "No immediate gate exposure detected"}`,
    "",
    "## Recommended Mitigations",
    ...(metrics.mitigations.length ? metrics.mitigations.map((item) => `- ${item}`) : ["- Maintain the current plan and continue monitoring readiness weekly."]),
    "",
    "## Recommendation",
    `- ${metrics.recommendation}`,
    "",
    "_Generated locally because live AI runtime is not configured. Connect AI Setup to receive narrative scenario modeling on top of this estimate._",
  ].join("\n");
}

function buildExecutiveDashboard(projectData = getProjectData(getActiveProject())) {
  const program = getPROGRAM();
  const twinSummary = buildTwinExecutiveSummary(projectData.twinGraph || {});
  const phaseStatuses = ADAM_PHASE_SEQUENCE.map((phase) => {
    const gate = buildStageGateMemo(phase, projectData);
    return {
      phase,
      readiness: gate.readiness,
      status: gate.readiness >= 70 && !gate.blockers.length ? "on-track" : gate.readiness >= 40 ? "at-risk" : "blocked",
    };
  });
  const governGate = buildStageGateMemo("govern", projectData);
  const nextGatePhase = phaseStatuses.find((item) => item.status !== "on-track")?.phase || "valuerealize";
  const nextGateState = buildStageGateMemo(nextGatePhase, projectData);
  return {
    programName: program.name || "Unnamed Program",
    client: program.client || "",
    overallReadiness: Math.round(phaseStatuses.reduce((sum, item) => sum + Number(item.readiness || 0), 0) / Math.max(phaseStatuses.length, 1)),
    phaseStatuses,
    outcomes: String(projectData.discoverContext?.outcomes || "").split(/[;\n]+/).map((label) => label.trim()).filter(Boolean).slice(0, 5).map((label) => ({
      label,
      kpi: projectData.discoverContext?.kpis || "",
      baseline: projectData.discoverContext?.baselineKpi || "",
      actual: projectData.valueRealizeData?.kpiActuals || "",
      onTrack: !!`${projectData.valueRealizeData?.kpiActuals || ""}`.trim(),
    })),
    agentsDeployed: Array.isArray(projectData.agents) ? projectData.agents.length : 0,
    agentROI: projectData.valueRealizeData?.agentRoiAttribution || program.roi || "",
    topRisks: (projectData.risks || []).slice(0, 3).map((risk) => ({ label: risk.title || risk.label || "Risk", severity: risk.severity || "amber" })),
    governanceHealth: governGate.readiness >= 70 ? "green" : governGate.readiness >= 40 ? "amber" : "red",
    nextGate: {
      phase: nextGatePhase,
      daysUntil: "",
      blocking: (nextGateState.blockers || []).slice(0, 3),
    },
    valueRealized: program.valueDelivered || "",
    valueProjected: program.projectedValue || "",
    twinSummary,
  };
}

async function generateProactiveCopilotBriefing(phaseId, projectData = getProjectData(getActiveProject()), runtimeConfig = getActiveAIRuntimeConfig()) {
  const exitCheck = evaluateExitCriteria(phaseId, projectData);
  if (exitCheck.passed && (projectData?.discoverContext?.capabilityDNA || []).length > 0) return null;

  const blockerText = exitCheck.failures.slice(0, 3).join("; ") || "No specific blockers identified";
  const ambientSnippet = buildCopilotAmbientContext(phaseId, []).slice(0, 800);
  const system = `You are Brillio ADAM™ Copilot. Generate a proactive briefing for a transformation team entering the ${phaseId} workspace. Be specific and concise.`;
  const user = `Phase: ${phaseId}\nCurrent blockers: ${blockerText}\nContext: ${ambientSnippet}\n\nRespond in this exact format:\nACTION: [single most important next action, one sentence]\nBLOCKERS:\n1. [blocker]\n2. [blocker]\n3. [blocker]\nMax 80 words total.`;

  try {
    if (!runtimeConfig?.available) return null;
    const result = await requestAIText(system, user);
    return result || null;
  } catch {
    return null;
  }
}

function extractCustomRuleValues(source, pathExpression = "") {
  const normalizedPath = String(pathExpression || "").trim();
  if (!normalizedPath) return [];
  const aliasMap = {
    strategy: "strategyData",
    discover: "discoverContext",
    operate: "operateData",
    valuerealize: "valueRealizeData",
  };
  const segments = normalizedPath.split(".").filter(Boolean);
  const walk = (value, index) => {
    if (index >= segments.length) return [value];
    const rawSegment = segments[index];
    const mappedSegment = aliasMap[rawSegment] || rawSegment;
    const isArraySegment = mappedSegment.endsWith("[]");
    const key = isArraySegment ? mappedSegment.slice(0, -2) : mappedSegment;
    const nextValue = value?.[key];
    if (isArraySegment) {
      if (!Array.isArray(nextValue)) return [];
      return nextValue.flatMap((item) => walk(item, index + 1));
    }
    if (Array.isArray(nextValue)) {
      return nextValue.flatMap((item) => walk(item, index + 1));
    }
    return walk(nextValue, index + 1);
  };
  return walk(source, 0).filter((value) => value !== undefined);
}

function evaluateCustomRule(condition, data) {
  const normalized = String(condition || "").trim();
  if (!normalized) return false;
  const match = normalized.match(/^([A-Za-z0-9_.[\]]+)\s*(==|!=|>=|<=|>|<)\s*(.+)$/);
  if (!match) {
    return extractCustomRuleValues(data, normalized).some((value) => !!value);
  }
  const [, pathExpression, operator, rawExpected] = match;
  const expectedToken = rawExpected.trim();
  const expected = /^-?\d+(\.\d+)?$/.test(expectedToken)
    ? Number(expectedToken)
    : expectedToken.replace(/^['"]|['"]$/g, "");
  return extractCustomRuleValues(data, pathExpression).some((value) => {
    const actual = typeof value === "string" && typeof expected === "number" ? Number(value) : value;
    switch (operator) {
      case ">":
        return Number(actual) > Number(expected);
      case ">=":
        return Number(actual) >= Number(expected);
      case "<":
        return Number(actual) < Number(expected);
      case "<=":
        return Number(actual) <= Number(expected);
      case "!=":
        return `${actual}` !== `${expected}`;
      case "==":
      default:
        return `${actual}` === `${expected}`;
    }
  });
}

function detectCopilotContradictions(phaseIdOrProjectData, capturedInputs = {}, maybeProjectData = null) {
  const projectData = maybeProjectData
    || (phaseIdOrProjectData && typeof phaseIdOrProjectData === "object" && !Array.isArray(phaseIdOrProjectData)
      ? phaseIdOrProjectData
      : getProjectData(getActiveProject()));
  const contradictions = [];
  const decisions = projectData?.architecture?.decisions || [];
  const roles = projectData?.mobilise?.deliveryRoles || [];
  const compliance = projectData?.discoverContext?.complianceNeeds || "";
  const securityArtifacts = (projectData?.architecture?.artifacts || []).filter((artifact) => artifact.type === "SecurityArchitectureReview");
  const capDNA = projectData?.discoverContext?.capabilityDNA || [];
  const agentRegistry = Array.isArray(projectData?.govern?.agentRegistry)
    ? projectData.govern.agentRegistry
    : Array.isArray(projectData?.build?.agentRegistry)
      ? projectData.build.agentRegistry
      : [];
  const vrKpis = (Array.isArray(projectData?.valueRealizeData?.kpiActuals)
    ? projectData.valueRealizeData.kpiActuals
    : String(projectData?.valueRealizeData?.kpiActuals || "")
      .split(/[;,\n]/)
      .map((item) => item.trim())
      .filter(Boolean)
  ).map((kpi) => (typeof kpi === "string" ? kpi : kpi.name) || "");
  const discoverKpis = (Array.isArray(projectData?.discoverContext?.kpis)
    ? projectData.discoverContext.kpis
    : String(projectData?.discoverContext?.kpis || "")
      .split(/[;,\n]/)
      .map((item) => item.trim())
      .filter(Boolean)
  ).map((kpi) => (typeof kpi === "string" ? kpi : kpi.name) || "");

  decisions.forEach((decision) => {
    const isHighAutonomy = /L3|L4|autonomous/i.test(`${decision.title || ""} ${decision.chosenApproach || ""}`);
    if (isHighAutonomy) {
      const hasMlEngineer = roles.some((role) => /ml|machine learning|ai engineer|data scientist/i.test(`${role.roleType || ""} ${role.roleName || ""}`));
      if (!hasMlEngineer) {
        contradictions.push(`Decision "${decision.title}" requires L3/L4 autonomy but no ML/AI Engineer role is on the roster.`);
      }
    }
  });

  if (/soc2|hipaa|gdpr|pci/i.test(compliance) && securityArtifacts.length === 0) {
    contradictions.push(`Compliance requirement "${String(compliance).slice(0, 40)}" requires a Security Architecture Review artifact — none exists in Design.`);
  }

  capDNA.forEach((capability) => {
    (capability.agentsRequired || []).forEach((agentType) => {
      const registered = agentRegistry.some((agent) => String(agent.agentType || agent.type || "").toLowerCase().includes(String(agentType).toLowerCase()));
      if (!registered) {
        contradictions.push(`Capability "${capability.name}" requires agent type "${agentType}" which is not in the agent registry.`);
      }
    });
  });

  vrKpis.forEach((kpi) => {
    if (kpi && !discoverKpis.some((discoverKpi) => discoverKpi.toLowerCase().includes(kpi.toLowerCase()) || kpi.toLowerCase().includes(discoverKpi.toLowerCase()))) {
      contradictions.push(`Value Realization KPI "${kpi}" does not match any KPI defined in Discover. Verify alignment.`);
    }
  });

  const dataResidency = projectData?.architecture?.complianceProfile?.dataResidency
    || projectData?.discoverContext?.complianceNeeds
    || "";
  if (/on.?prem|data.?residen|sovereign|in.?country|local.?host/i.test(dataResidency)) {
    const allDecisionText = (projectData?.architecture?.decisions || [])
      .map((decision) => `${decision.title || ""} ${decision.chosenApproach || ""} ${decision.rationale || ""}`)
      .join(" ")
      .toLowerCase();
    if (/\baws\b|\bazure\b|\bgcp\b|\bgoogle cloud\b|\bpublic cloud\b|\bmulti.?cloud\b/i.test(allDecisionText)) {
      contradictions.push(
        `Data residency requirement "${String(dataResidency).slice(0, 50)}" conflicts with public cloud architecture decisions. Review data architecture and consider private cloud, on-premise deployment, or data sovereignty controls.`,
      );
    }
  }

  const agentCount = agentRegistry.length;
  const budget = projectData?.strategyData?.investmentEnvelope || "";
  if (agentCount > 10 && /small|limited|tight|\$[0-9]{1,4}k/i.test(String(budget))) {
    contradictions.push(`${agentCount} agents in registry may exceed stated budget envelope "${String(budget).slice(0, 40)}". Review cost projections.`);
  }

  const highAutonomyAgents = agentRegistry.filter((agent) => /L3|L4/i.test(agent.autonomyLevel || ""));
  const hitlPolicy = projectData?.govern?.hitlPolicy || projectData?.phaseArtifacts?.govern?.hitlPolicy;
  if (highAutonomyAgents.length > 0 && !hitlPolicy) {
    contradictions.push(`${highAutonomyAgents.length} L3/L4 agent(s) have no Human-in-the-Loop policy defined. HITL policy is required for high-autonomy agents.`);
  }

  const approvedCapabilities = capDNA.filter((item) => item.status === "approved");
  const raciRows = normalizeRaciRows(projectData?.mobilise?.raci);
  if (approvedCapabilities.length > 0 && raciRows.filter((row) => row.accountable).length === 0) {
    contradictions.push(`${approvedCapabilities.length} approved capability/capabilities have no Accountable owner in the RACI matrix.`);
  }

  const approvedCapabilityCount = (projectData?.discoverContext?.capabilityDNA || []).filter((item) => item.status === "approved" || item.approved).length;
  const deliveryTeamSize = (projectData?.mobilise?.deliveryRoles || []).length;
  if (approvedCapabilityCount > 0 && deliveryTeamSize > 0) {
    const ratio = approvedCapabilityCount / deliveryTeamSize;
    if (ratio > 3) {
      contradictions.push({
        rule: "capacity-capability-ratio",
        severity: "warning",
        message: `${approvedCapabilityCount} approved capabilities with only ${deliveryTeamSize} delivery roles (ratio ${ratio.toFixed(1)}:1 exceeds recommended 3:1 maximum). Consider phasing capability delivery or expanding the team.`,
      });
    }
  }

  for (const rule of (projectData?.customContradictionRules || [])) {
    try {
      if (evaluateCustomRule(rule.condition, projectData)) {
        contradictions.push({
          rule: rule.id,
          severity: rule.severity || "warning",
          message: rule.message,
          custom: true,
        });
      }
    } catch (error) {
      console.warn("Custom rule evaluation failed:", rule?.id, error);
    }
  }

  return contradictions;
}

function addProgramAccelerator(accelerator) {
  if (!accelerator?.id) return;
  updateActiveProjectData((data) => {
    const existing = [...(data.selectedAccelerators || [])];
    if (existing.some((item) => item.id === accelerator.id)) return;
    data.selectedAccelerators = [
      ...existing,
      {
        id: accelerator.id,
        label: accelerator.label,
        summary: accelerator.summary || "",
        source: accelerator.source || "Marketplace accelerator",
        category: accelerator.category || "accelerator",
        addedAt: stampNow(),
      },
    ];
  });
  window.dispatchEvent(new CustomEvent(ADAM_ACCELERATORS_UPDATED_EVENT));
}

function removeProgramAccelerator(acceleratorId) {
  updateActiveProjectData((data) => {
    data.selectedAccelerators = [...(data.selectedAccelerators || [])].filter((item) => item.id !== acceleratorId);
  });
  window.dispatchEvent(new CustomEvent(ADAM_ACCELERATORS_UPDATED_EVENT));
}

function setMarketplaceIndustry(industry) {
  updateActiveProjectData((data) => {
    data.marketplaceSelection = {
      ...(data.marketplaceSelection || {}),
      industry,
    };
  });
}

