    capacity: "Capacity",
    milestones: "Milestones",
    gantt: "Timeline",
    criticalpath: "Critical Path",
    burndown: "Burndown",
    heatmap: "Health Heatmap",
    resources: "Resources",
    changeimpact: "Change Impact",
    twin: "Transformation Twin",
    delivery: "Delivery",
