function getPhaseOutcomeLabel(viewId) {
  const normalizedViewId = normalizeGuideViewId(viewId);
  const phaseOutcomeLabels = {
    strategy: "Define the Bet",
    mobilise: "Align the Team",
    discover: "Find the Value",
    design: "Design the Capability",
    build: "Launch the MVP",
    operate: "Operationalise",
    govern: "Govern the Risk",
    governance: "Govern the Risk",
    optimize: "Scale the Value",
    valuerealize: "Realize the Value",
    value: "Realize the Value",
  };
  return phaseOutcomeLabels[normalizedViewId] || getPhaseDisplayLabel(viewId);
}

function getApprovedArtifactSourcesUpToPhase(targetPhaseId) {
  const targetIndex = ADAM_PHASE_SEQUENCE.indexOf(normalizeGuideViewId(targetPhaseId));
  const discoverWorkspace = getDISCOVER_WORKSPACE();
  const discoverMeta = getDISCOVER_ARTIFACT_META();
  const immediatePriorPhase = targetIndex > 0 ? ADAM_PHASE_SEQUENCE[targetIndex - 1] : null;
  const sources = [];
  if (targetIndex <= 0) return sources;
  DISCOVER_DELIVERABLES.forEach((item) => {
    const content = discoverWorkspace[item.id]?.trim();
    const meta = discoverMeta[item.id] || {};
    const allowDraftCarryForward = immediatePriorPhase === "discover" && hasPhaseUnlockSignal("discover");
    if (content && (meta.status === "approved" || meta.status === "review" || allowDraftCarryForward)) {
      sources.push({
        phaseId: "discover",
        title: item.label,
        status: meta.status || "draft",
        owner: meta.owner || "Program owner",
        content,
        evidence: meta.evidence || "",
      });
    }
  });
  ADAM_PHASE_SEQUENCE.slice(1, targetIndex).forEach((phaseId) => {
    getPhaseArtifactsForView(phaseId).forEach((artifact) => {
      const allowDraftCarryForward = immediatePriorPhase === phaseId && hasPhaseUnlockSignal(phaseId);
      if (trimArtifactTextContent(artifact.content) && (artifact.status === "approved" || artifact.status === "review" || (allowDraftCarryForward && artifact.status !== "blank"))) {
        sources.push({
          phaseId,
          title: artifact.label,
          status: artifact.status,
          owner: artifact.owner || "Program owner",
          content: trimArtifactTextContent(artifact.content),
          evidence: artifact.evidence || "",
        });
      }
    });
  });
  return sources;
}

function getCompilerTargets() {
  return ADAM_PHASE_SEQUENCE.map((id) => ({ id, label: getPhaseDisplayLabel(id) }));
}

function getSuggestedTargetPhase() {
  const phases = getCompilerTargets();
  return phases.find((phase) => {
    const gate = getWorkflowGateStatus(phase.id);
    return gate.accessible && !gate.complete;
  })?.id || "design";
}

async function generatePhaseDrafts(targetPhaseId, { artifactId = null, onStart, onProgress, onComplete } = {}) {
  const key = normalizeGuideViewId(targetPhaseId);
  const defs = (PHASE_ARTIFACT_LIBRARY[key] || []).filter((artifact) => !artifactId || artifact.id === artifactId);
  if (!defs.length) return [];
  const provider = getAIProvider();
  const program = getPROGRAM();
  const discover = getDISCOVER_CONTEXT();
  const guide = getPHASE_GUIDANCE()[key] || { fields: {}, aiBrief: "" };
  const gate = PHASE_GATE_LIBRARY[key] || { requiredInputs: [], exitCriteria: [] };
  const template = getTEMPLATE_SELECTION();
  const sources = getApprovedArtifactSourcesUpToPhase(key);
  const capabilities = getCAPABILITIES();
  const architectureCapability = capabilities.find((item) => getArchitectureStackForCapability(item)) || capabilities[0] || null;
  const stack = architectureCapability ? getArchitectureStackForCapability(architectureCapability) : null;
  const pattern = architectureCapability ? getArchitecturePatternForCapability(architectureCapability) : null;
  const nfrs = architectureCapability ? getArchitectureNfrsForCapability(architectureCapability) : [];
  const buildArchitectureContext = key === "build" && stack ? {
    llm: `${stack.llm?.provider || "tbd"} ${stack.llm?.model || ""} — context: ${stack.llm?.contextWindowTokens || "n/a"} tokens`,
    agentFramework: `${stack.agentFramework?.name || "tbd"} (${stack.agentFramework?.pattern || "tbd"})`,
    memoryLayer: stack.memory?.vectorDatabase
      ? `${stack.memory.vectorDatabase} with ${stack.memory.embeddingModel || "embedding model TBD"}, ${stack.memory.retrievalStrategy || "retrieval TBD"} retrieval`
      : "no vector memory",
    deploymentPlatform: `${stack.deploymentPlatform?.cloudProvider || "tbd"} / ${stack.deploymentPlatform?.containerOrchestration || "tbd"}`,
    observability: stack.observability?.agentMonitoring || "not yet defined",
    securityModel: `${stack.security?.iamApproach || "tbd"} IAM, ${stack.security?.promptInjectionProtection || "tbd"} prompt protection`,
    nfrs: nfrs.map((item) => `${item.requirementType}: ${item.target}`).join(" | ") || "No NFRs defined",
    costCeiling: `$${stack.costModel?.monthlyBudgetCeiling || 0}/month estimated`,
    pattern: pattern?.patternName || "Custom",
    patternFailureModes: (Object.values(ARCHITECTURE_PATTERNS).find((item) => item.name === pattern?.patternName)?.commonFailureModes || []).join(", ") || "Not defined",
  } : null;
  if (!sources.length && !["discover", "design"].includes(key)) {
    throw new Error(`Approve prior-stage artifacts before generating ${getPhaseDisplayLabel(key)} drafts.`);
  }
  const generated = [];
  for (const artifact of defs) {
    onStart?.(artifact);
    let output = "";
    const level = getArtifactLevelMeta(artifact.level || 1);
    const sys = `You are Brillio ADAM™, operating as an AI transformation methodology generator using ${provider.label} as the preferred AI workflow. Generate a complete working draft for the ${artifact.label} artifact in the ${getPhaseDisplayLabel(key)} stage of ADAM. This artifact belongs to ${level.label} and the ${artifact.family || "ADAM"} family. The draft should be enterprise-grade, structured, specific, and ready for human review. Use prior approved artifacts as the source of truth and maintain traceability to business outcomes, controls, delivery evidence, and the ADAM artifact hierarchy.${buildArchitectureContext ? ` The Build package must reference the concrete technology stack, architecture pattern, NFRs, security choices, observability tooling, and cost ceiling rather than generic placeholders.` : ""}`;
    const user = `Program: ${program.name}
Client: ${program.client}
Industry: ${program.industry}
Target phase: ${getPhaseDisplayLabel(key)}
Target artifact: ${artifact.label}
Target artifact purpose: ${artifact.desc}
Artifact level: ${level.label}
Artifact family: ${artifact.family || "ADAM"}
Core ADAM artifact: ${artifact.core ? "Yes" : "No"}
Signature IP artifact: ${artifact.signature ? "Yes" : "No"}
Selected industry archetype: ${template.selectedArchetype}

Discovery context:
- Problem: ${discover.problem || "Not provided"}
- Outcomes: ${discover.outcomes || "Not provided"}
- KPIs: ${discover.kpis || "Not provided"}
- Compliance: ${discover.compliance || "Not provided"}

${buildArchitectureContext ? `Architecture context:
- Capability: ${architectureCapability?.capabilityName || architectureCapability?.name || "Not provided"}
- Pattern: ${buildArchitectureContext.pattern}
- LLM: ${buildArchitectureContext.llm}
- Agent framework: ${buildArchitectureContext.agentFramework}
- Memory layer: ${buildArchitectureContext.memoryLayer}
- Deployment platform: ${buildArchitectureContext.deploymentPlatform}
- Observability: ${buildArchitectureContext.observability}
- Security: ${buildArchitectureContext.securityModel}
- NFRs: ${buildArchitectureContext.nfrs}
- Cost ceiling: ${buildArchitectureContext.costCeiling}
- Pattern failure modes: ${buildArchitectureContext.patternFailureModes}` : ""}

Phase guide inputs:
${Object.entries(guide.fields || {}).map(([fieldId, value]) => `- ${fieldId}: ${value || "Not provided"}`).join("\n") || "- None provided"}

Required inputs:
${(gate.requiredInputs || []).map((item) => `- ${item}`).join("\n") || "- None"}

Exit criteria:
${(gate.exitCriteria || []).map((item) => `- ${item}`).join("\n") || "- None"}

Approved prior-stage evidence:
${sources.map((source, idx) => `## Source ${idx + 1}: ${source.title} [${getPhaseDisplayLabel(source.phaseId)} | ${source.status}]
Owner: ${source.owner}
Evidence: ${source.evidence || "None"}
Content:
${source.content}`).join("\n\n")}

Instructions:
- Generate a polished first draft of ${artifact.label}.
- Respect its place in the ADAM hierarchy and make that role visible in the structure.
- Make dependencies, owners, checkpoints, and acceptance conditions explicit where relevant.
- Reference prior-stage decisions and evidence naturally.
- ${key === "build" ? "Reference the concrete architecture stack throughout, including model selection, deployment platform, security controls, observability tooling, NFR validation, and cost posture." : "Reference prior-stage decisions and evidence naturally."}
- Include concise headings and bullets when helpful.
- End with a short section called "Open Review Questions".`;
    await callClaude(sys, user, (chunk) => {
      output += chunk;
      onProgress?.(artifact, output);
    });
    const active = getPHASE_ARTIFACTS()[key]?.[artifact.id] || createBlankArtifactRecord();
    const evidenceTrail = sources.slice(0, 6).map((source) => `${getPhaseDisplayLabel(source.phaseId)}: ${source.title}`).join("; ");
    const dependencyTrail = sources.slice(0, 6).map((source) => `${getPhaseDisplayLabel(source.phaseId)} → ${source.title}`);
    const generatedMeta = buildGeneratedArtifactMetadata(key, artifact, output.trim(), "draft");
    const lifecycleStatus = generatedMeta.lifecycleStatus || "draft";
    savePhaseArtifact(key, artifact.id, {
      content: output.trim(),
      status: lifecycleStatus,
      version: (active.version || 0) + 1,
      owner: active.owner || program.sponsor?.split(",")[0] || "Program owner",
      reviewer: active.reviewer || program.sponsor?.split(",")[0] || "Program owner",
      updatedAt: stampNow(),
      source: `AI compiler draft via ${provider.label}`,
      evidence: evidenceTrail,
      dependencies: dependencyTrail.length ? dependencyTrail : generatedMeta.dependencies,
      qualityScore: generatedMeta.qualityScore,
      readinessScore: generatedMeta.readinessScore,
      generatedStatus: generatedMeta.generatedStatus,
      approvalStatus: generatedMeta.approvalStatus,
      traceability: generatedMeta.traceability,
      reviewComment: "AI-generated draft created from approved upstream evidence.",
    });
    generated.push({ ...artifact, content: output.trim() });
    onComplete?.(artifact, output);
  }
  return generated;
}

async function regenerateAffectedDownstreamArtifacts(startPhaseId, sourceArtifactId) {
  const startKey = normalizeGuideViewId(startPhaseId);
  const startIndex = ADAM_PHASE_SEQUENCE.indexOf(startKey);
  const phaseIdsToCheck = startIndex >= 0 ? ADAM_PHASE_SEQUENCE.slice(startIndex) : [];
  const refreshedPhases = [];
  const refreshedArtifacts = [];
  for (const phaseId of phaseIdsToCheck) {
    const staleArtifactIds = getStaleArtifactIdsForPhase(phaseId);
    if (!staleArtifactIds.length) continue;
    for (const artifactId of staleArtifactIds) {
      await generatePhaseDrafts(phaseId, { artifactId });
      refreshedArtifacts.push(`${phaseId}:${artifactId}`);
    }
    updateActiveProjectData((data) => {
      Object.assign(data, clearArtifactStaleFlagsOnData(data, phaseId, staleArtifactIds));
    });
    refreshedPhases.push(phaseId);
  }
  return {
    sourcePhaseId: startKey,
    sourceArtifactId,
    refreshedPhases,
    refreshedArtifacts,
  };
}

async function generatePhaseSequence(finalPhaseId, hooks = {}) {
  const finalKey = normalizeGuideViewId(finalPhaseId);
  const targetIndex = ADAM_PHASE_SEQUENCE.indexOf(finalKey);
  if (targetIndex < 0) return [];
  const generatedPhases = [];
  for (const phaseId of ADAM_PHASE_SEQUENCE.slice(0, targetIndex + 1)) {
    hooks.onPhaseStart?.(phaseId);
    const phaseArtifacts = await generatePhaseDrafts(phaseId, {
      onStart: (artifact) => hooks.onArtifactStart?.(phaseId, artifact),
      onProgress: (artifact, text) => hooks.onArtifactProgress?.(phaseId, artifact, text),
      onComplete: (artifact, text) => hooks.onArtifactComplete?.(phaseId, artifact, text),
    });
    generatedPhases.push({ phaseId, artifacts: phaseArtifacts });
    hooks.onPhaseComplete?.(phaseId, phaseArtifacts);
  }
  return generatedPhases;
}

async function refreshPhaseArtifactsFromInputs(viewId) {
  const key = normalizeGuideViewId(viewId);
  const defs = PHASE_ARTIFACT_LIBRARY[key] || [];
  const generated = [];
  const updated = [];
  const proposed = [];
  const currentArtifacts = getPhaseArtifactsForView(key);
  const attachmentEvidence = buildPhaseAttachmentEvidence(key);
  defs.forEach((artifactDef) => {
    const current = currentArtifacts.find((artifact) => artifact.id === artifactDef.id) || createBlankArtifactRecord();
    const nextContent = buildArtifactDraftFromInputs(key, artifactDef).trim();
    if (!nextContent) return;
    const updatedAt = stampNow();
    const generatedMeta = buildGeneratedArtifactMetadata(key, artifactDef, nextContent, trimArtifactTextContent(current.content) ? "updated" : "draft");
    if (!trimArtifactTextContent(current.content)) {
      const lifecycleStatus = generatedMeta.lifecycleStatus || "draft";
      savePhaseArtifact(key, artifactDef.id, {
        content: nextContent,
        status: lifecycleStatus,
        version: (current.version || 0) + 1,
        updatedAt,
        source: "Generated from saved inputs",
        editedByUser: false,
        proposedUpdate: null,
        lastGeneratedFromInputsAt: updatedAt,
        evidence: attachmentEvidence || current.evidence || "",
        dependencies: generatedMeta.dependencies,
        qualityScore: generatedMeta.qualityScore,
        readinessScore: generatedMeta.readinessScore,
        generatedStatus: generatedMeta.generatedStatus,
        approvalStatus: generatedMeta.approvalStatus,
        traceability: generatedMeta.traceability,
      });
      generated.push(artifactDef.label);
      return;
    }
    if (!current.editedByUser && current.status !== "approved") {
      const lifecycleStatus = generatedMeta.lifecycleStatus || "draft";
      savePhaseArtifact(key, artifactDef.id, {
        content: nextContent,
        status: lifecycleStatus,
        version: (current.version || 0) + 1,
        updatedAt,
        source: "Updated from saved inputs",
        editedByUser: false,
        proposedUpdate: null,
        lastGeneratedFromInputsAt: updatedAt,
        evidence: attachmentEvidence || current.evidence || "",
        dependencies: generatedMeta.dependencies,
        qualityScore: generatedMeta.qualityScore,
        readinessScore: generatedMeta.readinessScore,
        generatedStatus: generatedMeta.generatedStatus,
        approvalStatus: generatedMeta.approvalStatus,
        traceability: generatedMeta.traceability,
      });
      updated.push(artifactDef.label);
      return;
    }
    const normalizedNextContent = normalizeArtifactTextContent(nextContent);
    const diffItems = buildArtifactDiff(normalizedNextContent, current.content || "");
    const proposalRecord = {
      id: `${artifactDef.id}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
      artifactId: artifactDef.id,
      artifactTitle: artifactDef.label,
      phaseId: key,
      proposedAt: new Date().toISOString(),
      proposedContent: normalizedNextContent,
      diffItems,
      status: "pending",
    };
    savePhaseArtifact(key, artifactDef.id, {
      proposedUpdate: {
        content: normalizedNextContent,
        at: updatedAt,
        source: "Proposed update from saved inputs",
        diffItems,
      },
      status: "update_proposed",
      updatedAt,
      source: current.source || "User edited artifact",
      evidence: attachmentEvidence || current.evidence || "",
      qualityScore: generatedMeta.qualityScore,
      readinessScore: generatedMeta.readinessScore,
      approvalStatus: "update_proposed",
      traceability: generatedMeta.traceability,
    });
    updateActiveProjectData((data) => {
      data.pendingArtifactProposals = [
        ...(data.pendingArtifactProposals || []).filter((item) => !(item.phaseId === key && item.artifactId === artifactDef.id && item.status === "pending")),
        proposalRecord,
      ].slice(-50);
    }, "Queue artifact proposal", { skipUndoSnapshot: true });
    proposed.push(artifactDef.label);
  });
  return {
    generated,
    updated,
    proposed,
    missingQuestions: getMissingInputQuestions(key),
    impacts: getDownstreamArtifactImpacts(key, getMissingInputQuestions(key)),
  };
}

function getWorkflowGateStatus(viewId) {
  const key = normalizeGuideViewId(viewId);
  const activeProjectData = getProjectData(getActiveProject());
  const phaseOrder = ["strategy", "mobilise", "discover", "design", "build", "operate", "govern", "optimize", "valuerealize"];
  const gate = key === "mobilise" ? calculateMobiliseGate() : buildStageGateMemo(key, activeProjectData);
  const previousPhases = phaseOrder.slice(0, Math.max(phaseOrder.indexOf(key), 0));
  const previousComplete = previousPhases.every((phaseId) => {
    if (phaseId === "mobilise") return calculateMobiliseGate().complete;
    return hasPhaseUnlockSignal(phaseId);
  });
  const moduleAccessRules = {
    decisions: true,
    team: true,
    workplan: true,
    twin: hasPhaseUnlockSignal("discover"),
    marketplace: true,
    assets: true,
    operations: true,
    coe: true,
    raid: true,
    search: true,
    onboarding: true,
    portfolio_dashboard: true,
    crossprogram: true,
    narrative: true,
    testplan: true,
    pcr: true,
    stakeholders: true,
    benefits: true,
    budget: true,
    statusreport: true,
    calendar: true,
    retro: true,
    customtasks: true,
    notifications: true,
    workshop: true,
    lessons: true,
    milestones: true,
    graph: true,
    glossary: true,
    burndown: true,
    heatmap: true,
    riskmatrix: true,
    faq: true,
    capacity: true,
    decisionlog: true,
    explain: true,
  };
  const entryGuard = getPhaseEntryGuard(key, activeProjectData);
  const baseAccessible = key === "strategy"
    ? true
    : key === "mobilise"
    ? hasPhaseUnlockSignal("strategy")
    : key === "discover"
    ? true
    : Object.prototype.hasOwnProperty.call(moduleAccessRules, viewId)
      ? moduleAccessRules[viewId]
      : previousComplete;
  const accessible = baseAccessible && entryGuard.canEnter;
  const complete = key === "strategy"
    ? hasPhaseUnlockSignal("strategy")
    : key === "mobilise"
    ? gate.complete
    : key === "discover"
    ? hasPhaseUnlockSignal("discover") && (gate.summary?.approved || 0) >= 1
    : gate.readiness >= 70 && gate.blockers.length === 0;
  const reason = !entryGuard.canEnter
    ? entryGuard.reason
    : Object.prototype.hasOwnProperty.call(moduleAccessRules, viewId) && !accessible
    ? "Complete discovery so journey-linked modules inherit a real transformation context."
    : gate.blockers[0] || "Complete the required inputs and exit criteria to proceed.";
  return { ...gate, accessible, complete, reason };
}

function getPrimaryJourneyFlow() {
  const hasActiveProgram = !!getActiveProject();
  return [
    { id: "strategy", label: getPhaseOutcomeLabel("strategy"), desc: "Set the mandate, scope, sponsor, and measurable success case" },
    { id: "mobilise", label: getPhaseOutcomeLabel("mobilise"), desc: "Align the team, cadence, ownership, and operating rhythm" },
    { id: "discover", label: getPhaseOutcomeLabel("discover"), desc: "Size the opportunity, evidence, and value case" },
    { id: "design", label: getPhaseOutcomeLabel("design"), desc: "Shape the capability, operating model, and decision path" },
    { id: "build", label: getPhaseOutcomeLabel("build"), desc: "Package the implementation and launch the first release" },
    { id: "operate", label: getPhaseOutcomeLabel("operate"), desc: "Run live operations with controls, SLAs, and support" },
    { id: "govern", label: getPhaseOutcomeLabel("govern"), desc: "Manage trust, controls, and compliance with confidence" },
    { id: "optimize", label: getPhaseOutcomeLabel("optimize"), desc: "Expand value, maturity, adoption, and reuse" },
    { id: "valuerealize", label: getPhaseOutcomeLabel("valuerealize"), desc: "Prove realized value and capture next-cycle learning" },
  ].map((step) => {
    const gate = getWorkflowGateStatus(step.id);
    const progress = hasActiveProgram ? (gate.complete ? 100 : gate.readiness || 0) : 0;
    return { ...step, ...gate, progress };
  });
}

const JOURNEY_WORKSPACE_GROUPS = [
  {
    id: "define",
    label: "Define",
    detail: "Mandate, team, and scope",
    phases: ["strategy", "mobilise"],
  },
  {
    id: "discover",
    label: "Discover",
    detail: "Opportunity, evidence, and value",
    phases: ["discover"],
  },
  {
    id: "design",
    label: "Design",
    detail: "Capability, architecture, and rollout intent",
    phases: ["design"],
  },
  {
    id: "deliver",
    label: "Deliver",
    detail: "Build, launch, and run",
    phases: ["build", "operate"],
  },
  {
    id: "govern-scale",
    label: "Govern & Scale",
    detail: "Controls, optimization, and realized value",
    phases: ["govern", "optimize", "valuerealize"],
  },
];

function buildJourneyWorkspaceGroups() {
  const flow = getPrimaryJourneyFlow();
  return JOURNEY_WORKSPACE_GROUPS.map((group) => {
    const steps = group.phases
      .map((phaseId) => flow.find((step) => step.id === phaseId))
      .filter(Boolean);
    const completeCount = steps.filter((step) => step.complete).length;
    const accessibleCount = steps.filter((step) => step.accessible).length;
    const activeStep = steps.find((step) => step.accessible && !step.complete) || null;
    const avgReadiness = steps.length
      ? Math.round(steps.reduce((sum, step) => sum + (step.progress || 0), 0) / steps.length)
      : 0;
    const status = completeCount === steps.length
      ? "complete"
      : activeStep
        ? "active"
        : accessibleCount > 0
          ? "available"
          : "locked";
    const hint = completeCount === steps.length
      ? "All workspaces complete"
      : activeStep
        ? `${activeStep.label} is the current focus`
        : accessibleCount > 0
          ? `${accessibleCount} workspace${accessibleCount === 1 ? "" : "s"} ready`
          : "Waiting on earlier work to close";
    return {
      ...group,
      steps,
      completeCount,
      accessibleCount,
      activeStep,
      avgReadiness,
      status,
      hint,
    };
  });
}

