  marketplace:  { role: "Marketplace Lead",           hint: "Browse reusable assets, industry accelerators, and ADAM patterns before starting from scratch.", prompts: ["Show a best-practice example", "Generate a marketplace asset", "Find reusable agent patterns", "Recommend an industry accelerator"] },
  assets:       { role: "Asset Curator",              hint: "Use the Asset Library for reusable insights, prompts, benchmarks, and executive artifacts.", prompts: ["Show a best-practice example", "Generate a benchmark summary", "Create a reusable prompt package", "Identify reusable assets"] },
  fde:          { role: "Forward Deployed Engineer",  hint: "Use FDE to bridge strategy and engineering through rapid proof and validation.", prompts: ["Create an opportunity canvas", "Generate a prototype brief", "Build a pilot plan", "Write a production readiness checklist"] },
  delivery:     { role: "Delivery Lead",              hint: "Use expert delivery studios for team planning, RAID, and execution management.", prompts: ["Generate a kickoff deck", "Create a 30-60-90 day plan", "Write a RAID log", "Generate a learning cycle plan"] },
  adoption:     { role: "Change Management Lead",     hint: "Use adoption studios to strengthen rollout, training, and champion networks.", prompts: ["Create a change management plan", "Generate a training plan", "Build a champion network guide", "Assess adoption risk"] },
  govern:       { role: "Governance Lead",            hint: "Manage the trust layer through controls, risk assessment, and human oversight.", prompts: ["Generate a compliance checklist", "Create an AI risk assessment", "Write a HITL policy", "Build an audit framework"] },
  valuerealize: { role: "Value Realization Lead",     hint: "Measure realized value against baseline, attribute agent ROI, and capture lessons for the next cycle.", prompts: ["Draft the executive value report", "Compare KPI actuals to baseline", "Capture lessons learned", "Summarize unrealized value"] },
