function getPersonaCopilotContext(activeView) {
  const base = COPILOT_CONTEXT[activeView] || COPILOT_CONTEXT.home;
  const persona = getCurrentPersona();
  const personaActions = getPersonaActionsForView(activeView, persona.id);
  const roleMap = {
    executive: "Executive Advisor",
    program: "Program Director",
    architecture: "Architecture Strategist",
    governance: "Governance Counsel",
    change: "Adoption Coach",
  };
  return {
    ...base,
    role: persona.id === "executive" ? (roleMap[persona.id] || base.role) : `${persona.label} ${roleMap[persona.id] || base.role}`,
    hint: base.hint,
    prompts: [...personaActions, ...base.prompts].slice(0, 4),
  };
}

function buildCopilotAmbientContext(activeView, attachedDocs = []) {
  const normalizedView = normalizeGuideViewId(activeView);
  const prog = getPROGRAM();
  const activeProjectData = getProjectData(getActiveProject());
  const discover = getDISCOVER_CONTEXT();
  const portfolio = getPortfolioState();
  const gate = buildStageGate(normalizedView);
  const personaId = _currentPersonaId || "executive";
  const isExecutivePersona = personaId === "executive";
  const executiveDashboard = buildExecutiveDashboard(activeProjectData);
  const artifacts = getPhaseArtifactsForView(normalizedView)
    .filter((artifact) => artifact.status !== "blank").slice(0, 4)
    .map((artifact) => `${artifact.label} (${formatArtifactStatus(artifact.status)})`).join(", ");
  const missing = getPhaseUnlockExplanation(normalizedView).slice(0, 4).join(", ");
  const designArtifacts = getPhaseArtifactsForView("design")
    .filter((artifact) => artifact.status === "approved").slice(0, 3)
    .map((artifact) => artifact.label).join(", ");
  const governArtifacts = getPhaseArtifactsForView("operate")
    .filter((artifact) => artifact.status !== "blank").slice(0, 2)
    .map((artifact) => artifact.label).join(", ");
  const team = ((prog.deliveryRoles || getMOBILISE().deliveryRoles || [])).slice(0, 5)
    .map((role) => `${role.personName || "TBD"} (${role.roleName})`).join(", ");
  const docInsights = (activeProjectData.documentInsights || []).slice(0, 3)
    .map((insight) => insight.summary || insight.label).filter(Boolean).join("; ");
  const artifactSummaries = getPhaseArtifactsForView(normalizedView)
    .filter((artifact) => artifact.status !== "blank" && trimArtifactTextContent(artifact.content))
    .slice(0, 3)
    .map((artifact) => `${artifact.label}: ${trimArtifactTextContent(artifact.content).slice(0, 150).replace(/\s+/g, " ")}`)
    .join("; ");
  const staleArtifacts = getPhaseArtifactsForView(normalizedView)
    .filter((artifact) => artifact.downstreamRefreshRequired)
    .slice(0, 3)
    .map((artifact) => artifact.label)
    .join(", ");
  const priorPhaseKey = ADAM_PHASE_SEQUENCE[ADAM_PHASE_SEQUENCE.indexOf(normalizedView) - 1];
  const upstreamApprovals = priorPhaseKey
    ? getPhaseArtifactsForView(priorPhaseKey)
      .filter((artifact) => artifact.status === "approved")
      .slice(0, 3)
      .map((artifact) => artifact.label)
      .join(", ")
    : "";
  const complianceNeeds = discover?.complianceNeeds || discover?.compliance || getPHASE_GUIDANCE()?.discover?.fields?.complianceNeeds || "";
  const valueActuals = getVALUE_REALIZE_DATA()?.kpiActuals || "";
  const priorLessons = (activeProjectData?.transformationLibrary?.lessons || [])
    .slice(-2)
    .map((lesson) => lesson.text?.slice(0, 100))
    .filter(Boolean)
    .join("; ");
  const mismatchedDocs = (attachedDocs || [])
    .filter((doc) => doc.suggestedPhase && doc.suggestedPhase !== normalizedView)
    .slice(0, 2)
    .map((doc) => `${doc.name} (suggested: ${getPhaseDisplayLabel(doc.suggestedPhase)})`)
    .join(", ");
  const phasePlaybookContent = buildPhasePlaybookSummary(normalizedView);
  const artifactDependencyChain = buildArtifactDependencyChain(normalizedView);
  const twinSummary = buildTwinExecutiveSummary(activeProjectData.twinGraph || {});
  const priorCycleInsights = (activeProjectData.transformationLibrary?.completedCycleInsights || [])
    .slice(-3)
    .map((item) => item.text || item.summary || item.label || "")
    .filter(Boolean)
    .join("; ");
  const strategyData = activeProjectData?.strategyData || {};
  const strategyComplete = strategyData.mandate && strategyData.sponsorCommitment && strategyData.investmentEnvelope;
  const capDNA = activeProjectData?.discoverContext?.capabilityDNA || [];
  const approvedCaps = capDNA.filter((item) => item.status === "approved");
  const currentPhaseId = getCopilotCapturePhaseId(activeView);
  const exitCheck = evaluateExitCriteria(currentPhaseId, activeProjectData || {});
  const localGlobalInsights = activeProjectData?.transformationLibrary?.globalInsights || [];
  const relevantInsights = localGlobalInsights.length
    ? localGlobalInsights
        .filter((item) => !prog.industry || item.industry === prog.industry || !item.industry)
        .sort((a, b) => Number(b.reuseCount || 0) - Number(a.reuseCount || 0) || Number(b.addedAt || 0) - Number(a.addedAt || 0))
        .slice(0, 2)
    : (portfolio.globalTransformationLibrary?.lessons || [])
        .filter((item) => !prog.industry || item.industry === prog.industry || !item.industry)
        .sort((a, b) => Number(b.reuseCount || 0) - Number(a.reuseCount || 0) || Number(b.addedAt || 0) - Number(a.addedAt || 0))
        .slice(0, 2);
  const orgAgents = activeProjectData?.organizationAgentCatalog || portfolio.organizationAgentCatalog || [];
  const globalLessons = (portfolio.globalTransformationLibrary?.lessons || [])
    .filter((item) => item.industry === prog.industry || (Array.isArray(item.capabilityTypes) && item.capabilityTypes.some((type) => String(discover.capabilityDirection || "").toLowerCase().includes(String(type).toLowerCase()))))
    .slice(0, 2)
    .map((item) => `Relevant insight from prior ${item.industry || "cross-industry"} engagement: ${item.summary || item.text || ""}`)
    .join(" ");
  const reusableAgentTypes = (orgAgents || [])
    .filter((item) => !discover.capabilityDirection || String(item.agentType || "").toLowerCase().includes(String(discover.capabilityDirection || "").toLowerCase()))
    .slice(0, 4)
    .map((item) => item.agentType)
    .filter(Boolean)
    .join(", ");
  const finalizeContext = (parts) => {
    const contextString = parts.filter(Boolean).join("\n\n");
    if (typeof contextString !== "string") return contextString;
    if (contextString.length <= MAX_CONTEXT_CHARS) return contextString;

    const sections = contextString.split("\n\n").filter(Boolean);
    const highPriorityCutoff = Math.ceil(sections.length * 0.65);
    const highPriority = sections.slice(0, highPriorityCutoff).join("\n\n").slice(0, MAX_CONTEXT_CHARS - 60);
    const remainingBudget = MAX_CONTEXT_CHARS - highPriority.length - 60;
    const lowPriority = remainingBudget > 200
      ? sections.slice(highPriorityCutoff).join("\n\n").slice(0, remainingBudget)
      : "";
    const trimmed = highPriority + (lowPriority ? `\n\n${lowPriority}` : "") + "\n[context trimmed for length]";
    return trimmed.slice(0, MAX_CONTEXT_CHARS);
  };
  if (isExecutivePersona) {
    return finalizeContext([
      `Executive dashboard for ${executiveDashboard.programName} (${executiveDashboard.client}).`,
      `Overall readiness: ${executiveDashboard.overallReadiness}%.`,
      `Phase statuses: ${executiveDashboard.phaseStatuses.map((item) => `${getPhaseDisplayLabel(item.phase)} ${item.readiness}%`).join(", ")}.`,
      `Top risks: ${executiveDashboard.topRisks.map((risk) => `${risk.label} (${risk.severity})`).join(", ") || "None"}.`,
      `Value realized: ${executiveDashboard.valueRealized || "n/a"} vs projected ${executiveDashboard.valueProjected || "n/a"}.`,
      `Next gate: ${getPhaseDisplayLabel(executiveDashboard.nextGate.phase)}; blockers: ${executiveDashboard.nextGate.blocking.join(", ") || "None"}.`,
      `Transformation Twin:\n${executiveDashboard.twinSummary}`,
    ]);
  }
  const contextParts = [
    `Program: ${prog.name} for ${prog.client} in ${prog.industry}.`,
    discover.problem ? `Business problem: ${discover.problem}` : "",
    discover.outcomes ? `Desired outcome: ${discover.outcomes}` : "",
    discover.kpis ? `KPI context: ${discover.kpis}` : "",
    discover.baselineKpi ? `Baseline KPI: ${discover.baselineKpi}` : "",
    `Current stage: ${getPhaseDisplayLabel(normalizedView)} with gate strength ${gate.readiness}%.`,
    artifacts ? `Active artifacts: ${artifacts}.` : "",
    missing ? `Still needed: ${missing}.` : "",
    phasePlaybookContent ? `Phase playbook: ${phasePlaybookContent}` : "",
    artifactDependencyChain ? `Active artifact dependency chain:\n${artifactDependencyChain}` : "",
    designArtifacts ? `Approved design decisions: ${designArtifacts}.` : "",
    governArtifacts ? `Govern artifacts in progress: ${governArtifacts}.` : "",
    team ? `Delivery team: ${team}.` : "",
    docInsights ? `Document insights: ${docInsights}.` : "",
    artifactSummaries ? `Artifact context: ${artifactSummaries}.` : "",
    staleArtifacts ? `Stale and needing refresh: ${staleArtifacts}.` : "",
    upstreamApprovals ? `Approved in prior phase: ${upstreamApprovals}.` : "",
    complianceNeeds && normalizedView === "operate"
      ? `Compliance needs from Discover: ${String(complianceNeeds).slice(0, 120)}.`
      : "",
    normalizedView === "valuerealize"
      ? `Prompt the user to review KPI actuals vs. the baselines captured in Discover. ${valueActuals ? "If actuals are present, offer to generate the Executive Value Report artifact. Format the offer as a single actionable question: 'Your KPIs show achievement versus baseline. Shall I generate the Executive Value Report now?'" : "If KPI actuals are missing, ask for the actuals before recommending the Executive Value Report."}`
      : "",
    priorLessons && normalizedView === "discover"
      ? `Prior program lessons: ${priorLessons}.`
      : "",
    priorCycleInsights && normalizedView === "discover"
      ? `Prior Cycle Insights (apply to current discovery): ${priorCycleInsights}.`
      : "",
    globalLessons ? globalLessons : "",
    reusableAgentTypes && normalizedView === "design"
      ? `Organization Agent Catalog: ${(orgAgents || []).length} reusable agent types available. Relevant to current capabilities: ${reusableAgentTypes}. Consider reusing before designing new agents.`
      : "",
    twinSummary ? `Transformation Twin:\n${twinSummary}` : "",
    mismatchedDocs ? `Note: some documents may belong to a different phase: ${mismatchedDocs}.` : "",
  ];

  contextParts.push(
    strategyComplete
      ? `Strategy: Mandate="${String(strategyData.mandate || "").slice(0, 80)}" | Sponsor confirmed | Investment: ${strategyData.investmentEnvelope}`
      : "⚠ Strategy gate incomplete — mandate, sponsor commitment, or investment envelope missing.",
  );
  if (capDNA.length > 0) {
    contextParts.push(`Capability DNA: ${capDNA.length} defined, ${approvedCaps.length} approved. Top capabilities: ${capDNA.slice(0, 3).map((item) => item.name).join(", ")}`);
  }
  if (!exitCheck.passed && exitCheck.failures.length > 0) {
    contextParts.push(`Open blockers for ${currentPhaseId} exit: ${exitCheck.failures.slice(0, 3).join("; ")}`);
  }
  if (twinSummary) contextParts.push(`Transformation Twin: ${twinSummary}`);
  if (relevantInsights.length > 0) {
    contextParts.push(`Prior program insights: ${relevantInsights.map((item) => String(item.summary || item.text || "").slice(0, 100)).join(" | ")}`);
  }
  if (orgAgents.length > 0 && (currentPhaseId === "design" || currentPhaseId === "build")) {
    const reusable = orgAgents.slice(0, 3).map((item) => item.agentType || item.type || item.label).filter(Boolean);
    contextParts.push(`Organization Agent Catalog: ${orgAgents.length} reusable agent types available. Examples: ${reusable.join(", ")}`);
  }
  const pendingADRs = activeProjectData?.pendingADRProposals ?? [];
  if (pendingADRs.length) {
    contextParts.push(
      `PENDING ADR PROPOSALS: ${pendingADRs.length}\n${pendingADRs.slice(0, 4).map((item) => `- "${item?.title || "Untitled"}" (${item?.sourceArtifactPhase || "unknown"}/${item?.sourceArtifactId || "artifact"}): ${(item?.chosenApproach || "").slice(0, 80)}`).join("\n")}`,
    );
  }
  const predictiveGateRisks = ["strategy", "mobilise", "discover", "design", "build", "operate", "govern", "optimize", "valuerealize"]
    .map((phaseId) => {
      try {
        return predictGateFailure(phaseId, activeProjectData);
      } catch {
        return null;
      }
    })
    .filter((risk) => risk && risk.level !== "low")
    .slice(0, 5);
  if (predictiveGateRisks.length > 0) {
    contextParts.push(
      `PREDICTIVE GATE RISKS:\n${predictiveGateRisks.map((risk) => `- ${risk.phaseId}: ${risk.level} (score ${risk.riskScore}) — ${risk.reasons?.[0]?.msg ?? ""}`).join("\n")}`,
    );
  }
  return finalizeContext(contextParts);
}

function buildCopilotSystemPrompt(activeView, copilotRole, attachedDocs = [], responseInstructions = `Keep the response under ${AI_COPILOT_RESPONSE_MAX_WORDS_CONVERSATIONAL} words.`) {
  const phaseId = getCopilotCapturePhaseId(activeView);
  const workspaceLabel = NAV.find((item) => item.id === activeView)?.label || getPhaseDisplayLabel(phaseId);
  const projectMeta = getPROGRAM();
  const activeProjectData = getProjectData(getActiveProject());
  const ambientContext = buildCopilotAmbientContext(activeView, attachedDocs);
  const phasePlaybookContent = buildPhasePlaybookSummary(phaseId);
  const artifactDependencyChain = buildArtifactDependencyChain(phaseId);
  const exitCheckForPrompt = evaluateExitCriteria(getCopilotCapturePhaseId(activeView), activeProjectData || {});
  const openBlockers = exitCheckForPrompt.failures.slice(0, 3).join("\n");
  return [
    "You are Brillio ADAM™ Copilot — an enterprise transformation methodology engine, not a general-purpose assistant.",
    `ROLE: ${copilotRole || "Transformation Advisor"}`,
    `WORKSPACE: ${workspaceLabel} (Phase: ${String(getCopilotCapturePhaseId(activeView) || "").toUpperCase()})`,
    `PROGRAM: ${projectMeta.name || "Unnamed"} | Client: ${projectMeta.client || "Unknown"} | Industry: ${projectMeta.industry || "Unknown"}`,
    ambientContext ? `\nCONTEXT:\n${ambientContext}` : "",
    phasePlaybookContent ? `\nADAM PHASE PLAYBOOK FOR ${String(phaseId || "").toUpperCase()}:\n${phasePlaybookContent}` : "",
    artifactDependencyChain ? `\nACTIVE ARTIFACT DEPENDENCY CHAIN:\n${artifactDependencyChain}` : "",
    openBlockers ? `\nOPEN BLOCKERS (must resolve before phase exit):\n${openBlockers}` : "",
    `\nINSTRUCTIONS:
- Ground every response in ADAM methodology and the program context above.
- Do not give generic AI advice. Give transformation-specific, artifact-linked guidance.
- If the user is missing a required artifact, name it and explain how to create it.
- If you detect a methodology contradiction (e.g., L4 autonomy decision with no ML engineer on roster), flag it explicitly.
- ${responseInstructions}
- Never invent program facts not present in context. If context is insufficient, ask a clarifying question.`,
  ].filter(Boolean).join("\n");
}

const COPILOT_ARTIFACT_GENERATION_SPECS = [
  { label: "Business Case", artifactId: "businessCase", phaseId: "discover", patterns: [/business case/i] },
  { label: "Outcome Charter", artifactId: "outcomeCharter", phaseId: "discover", patterns: [/outcome charter/i] },
  { label: "Value Hypothesis", artifactId: "valueHypothesis", phaseId: "discover", patterns: [/value hypothesis/i] },
  { label: "Capability DNA Canvas", artifactId: "capabilityBlueprint", phaseId: "design", patterns: [/capability dna/i, /capability blueprint/i] },
  { label: "Architecture Decision", artifactId: "decisionCatalog", phaseId: "design", patterns: [/architecture decision/i, /decision catalog/i] },
  { label: "Workforce Blueprint", artifactId: "workforceBlueprint", phaseId: "design", patterns: [/workforce blueprint/i, /workforce design/i] },
  { label: "Executive Value Report", artifactId: "executiveValueReport", phaseId: "valuerealize", patterns: [/value report/i, /executive value report/i] },
];

function detectArtifactGenerationIntent(userText = "", activeView = "") {
  const normalized = String(userText || "").trim();
  if (!/\b(draft|generate|create|produce|write)\b/i.test(normalized)) return null;
  const currentPhaseId = getCopilotCapturePhaseId(activeView);
  const match = COPILOT_ARTIFACT_GENERATION_SPECS.find((spec) => spec.patterns.some((pattern) => pattern.test(normalized)));
  if (!match) return null;
  return {
    ...match,
    phaseId: match.phaseId || currentPhaseId,
  };
}

function renderGeneratedArtifactMarkdown(payload = {}, fallbackLabel = "Artifact Draft") {
  const title = String(payload.title || fallbackLabel).trim();
  const sections = Array.isArray(payload.sections) ? payload.sections : [];
  const openQuestions = Array.isArray(payload.openQuestions) ? payload.openQuestions : [];
  const lines = [title ? `# ${title}` : `# ${fallbackLabel}`];
  if (payload.executiveSummary) lines.push("", String(payload.executiveSummary).trim());
  sections.forEach((section) => {
    const heading = String(section?.heading || "").trim();
    const body = String(section?.body || "").trim();
    const bullets = Array.isArray(section?.bullets) ? section.bullets.filter(Boolean) : [];
    if (heading) lines.push("", `## ${heading}`);
    if (body) lines.push("", body);
    if (bullets.length) {
      lines.push("", ...bullets.map((item) => `- ${String(item).trim()}`));
    }
  });
  if (openQuestions.length) {
    lines.push("", "## Open Review Questions", "", ...openQuestions.map((item) => `- ${String(item).trim()}`));
  }
  return lines.join("\n").trim();
}

async function generateArtifactDraftFromCopilotRequest(activeView, userText, attachedDocs = []) {
  const intent = detectArtifactGenerationIntent(userText, activeView);
  if (!intent) return null;
  const context = buildCopilotAmbientContext(activeView, attachedDocs);
  const schema = {
    title: "",
    executiveSummary: "",
    sections: [{ heading: "", body: "", bullets: [""] }],
    openQuestions: [""],
  };
  const response = await requestAIText(
    `You are generating a ${intent.label} for a Brillio ADAM transformation program.
Use the following program context to produce a complete, structured draft.
Output ONLY JSON in this schema: ${JSON.stringify(schema)}.
Do not include commentary. Base all content on stated facts in the context; mark inferred content with [INFERRED].`,
    `Phase: ${getPhaseDisplayLabel(intent.phaseId)}
Program context:
${context}

User request:
${userText}`,
  );
  const parsed = extractJsonObject(response) || {
    title: intent.label,
    executiveSummary: response.trim(),
    sections: [],
    openQuestions: [],
  };
  createArtifactEntry(intent.label, intent.phaseId, { title: parsed.title || intent.label, content: parsed });
  const artifactRecord = getPhaseArtifactsForView(intent.phaseId).find((artifact) => artifact.id === intent.artifactId) || createBlankArtifactRecord();
  savePhaseArtifact(intent.phaseId, intent.artifactId, {
    content: renderGeneratedArtifactMarkdown(parsed, intent.label),
    status: "draft",
    version: (artifactRecord.version || 0) + 1,
    updatedAt: stampNow(),
    source: "Copilot artifact generation",
    editedByUser: false,
  });
  queueArtifactOpen(intent.phaseId, intent.artifactId);
  return intent;
}

function detectTwinImpactIntent(userText = "", twinGraph = null) {
  if (!/\b(what happens if|impact of removing|remove|removed)\b/i.test(String(userText || ""))) return null;
  const graph = twinGraph || getProjectData(getActiveProject())?.twinGraph || { nodes: [] };
  const text = String(userText || "").toLowerCase();
  const match = (graph.nodes || [])
    .map((node) => ({ node, score: node.label ? (text.includes(String(node.label).toLowerCase()) ? String(node.label).length : 0) : 0 }))
    .sort((a, b) => b.score - a.score)[0];
  if (!match?.node || !match.score) return null;
  return simulateTwinNodeRemoval(match.node.id, graph);
}

