function isStandaloneDebugView(viewId = "") {
  return viewId === "validation" || viewId === "sanity" || viewId === "walkthrough";
}

function resolveViewFromPathname(pathname = "/") {
  const normalizedPath = String(pathname || "/").trim().toLowerCase();
  if (!normalizedPath || normalizedPath === "/" || normalizedPath === "/home") return "home";
  if (normalizedPath === "/portfolio") return "portfolio";
  if (normalizedPath === "/validation") return "validation";
  if (normalizedPath === "/sanity") return "sanity";
  if (normalizedPath === "/walkthrough") return "walkthrough";
  const segment = normalizedPath.replace(/^\/+/, "").split("/")[0] || "home";
  const rawCandidate = normalizeGuideViewId(segment);
  const candidate = isStandaloneDebugView(rawCandidate) || rawCandidate === "portfolio"
    ? rawCandidate
    : resolveActionDrilldownView(rawCandidate);
  return VIEW_MAP[candidate] ? candidate : "home";
}

function buildPathForView(viewId = "home") {
  const rawNormalized = normalizeGuideViewId(viewId);
  const normalized = isStandaloneDebugView(rawNormalized) || rawNormalized === "portfolio"
    ? rawNormalized
    : resolveActionDrilldownView(rawNormalized);
  if (!normalized || normalized === "home" || normalized === "portfolio") return "/";
  if (normalized === "validation") return "/validation";
  if (normalized === "sanity") return "/sanity";
  if (normalized === "walkthrough") return "/walkthrough";
  return VIEW_MAP[normalized] ? `/${normalized}` : "/";
}

function syncBrowserPath(viewId = "home", replace = false) {
  if (typeof window === "undefined" || !window.history) return;
  const nextPath = buildPathForView(viewId);
  if (window.location.pathname === nextPath) return;
  try {
    if (replace) {
      window.history.replaceState({ viewId }, "", nextPath);
    } else {
      window.history.pushState({ viewId }, "", nextPath);
    }
  } catch (error) {
    console.warn("ADAM route sync skipped.", error);
  }
}

const ADAM_UI_WORKSPACE_SESSION_KEY = "adam_ui_workspace_session_v1";

function readWorkspaceSessionState() {
  if (typeof window === "undefined") return {};
  try {
    return JSON.parse(window.localStorage.getItem(ADAM_UI_WORKSPACE_SESSION_KEY) || "{}") || {};
  } catch {
    return {};
  }
}

function writeWorkspaceSessionState(projectId, viewId, patch = {}) {
  if (typeof window === "undefined" || !projectId) return;
  const normalizedViewId = normalizeGuideViewId(viewId || "home");
  try {
    const current = readWorkspaceSessionState();
    const existingProgramState = current?.[projectId] || {};
    const existingViewState = existingProgramState?.views?.[normalizedViewId] || {};
    safeLocalStorageSet(
      ADAM_UI_WORKSPACE_SESSION_KEY,
      JSON.stringify({
        ...current,
        [projectId]: {
          ...existingProgramState,
          lastViewId: normalizedViewId,
          lastUpdatedAt: Date.now(),
          views: {
            ...(existingProgramState.views || {}),
            [normalizedViewId]: {
              ...existingViewState,
              ...patch,
            },
          },
        },
      }),
    );
  } catch {
    // Ignore persistence issues and keep session behavior in-memory.
  }
}

function getSavedProgramLastView(projectId) {
  if (!projectId) return "home";
  const session = readWorkspaceSessionState();
  const savedViewId = session?.[projectId]?.lastViewId;
  return VIEW_MAP[savedViewId] || savedViewId === "home" ? savedViewId : "home";
}

function getSavedProgramScrollTop(projectId, viewId) {
  if (!projectId) return 0;
  const session = readWorkspaceSessionState();
  const saved = session?.[projectId]?.views?.[normalizeGuideViewId(viewId || "home")]?.scrollTop;
  return Number.isFinite(saved) ? saved : 0;
}

function buildWorkspaceBreadcrumbs(viewId, surfaceOverride = null) {
  const normalized = normalizeGuideViewId(viewId);
  const navLabel = NAV.find((item) => item.id === normalized)?.label || getPhaseDisplayLabel(normalized) || "Workspace";
  const surfaceId = surfaceOverride || resolveTopSurface(normalized);
  const surfaceLabel = TOP_SURFACE_ITEMS.find((item) => item.id === surfaceId)?.label || "Command Center";
  const currentLabelOverrides = {
    home: "Command Center",
    search: "Mission Control",
    faq: "Mission Control",
    onboarding: "Mission Control",
    narrative: "Plan",
    simulation: "Scenario Lab",
    intelligence: "Intelligence Hub",
  };
  if (!normalized || normalized === "home") {
    return [{ label: "Command Center", viewId: "home" }];
  }
  if (normalized === "portfolio") {
    return [
      { label: "Command Center", viewId: "home" },
      { label: "Portfolio", viewId: "portfolio", current: true },
    ];
  }
  if (ADAM_PHASE_SEQUENCE.includes(normalized)) {
    return [
      { label: "Workspaces", viewId: getDefaultWorkspaceSurfaceTarget() },
      { label: getPhaseDisplayLabel(normalized), viewId: normalized, current: true },
    ];
  }
  return [
    { label: surfaceLabel, viewId: resolveTopSurfaceTarget(surfaceId, normalized) },
    { label: currentLabelOverrides[normalized] || navLabel, viewId: normalized, current: true },
  ];
}

function formatWorkspaceTimestampLabel(value) {
  if (!value) return "";
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return String(value);
  const deltaMs = Date.now() - parsed.getTime();
  if (deltaMs < 60_000) return "just now";
  if (deltaMs < 3_600_000) return `${Math.max(1, Math.round(deltaMs / 60_000))} min ago`;
  if (deltaMs < 86_400_000) return `${Math.max(1, Math.round(deltaMs / 3_600_000))} hr ago`;
  if (deltaMs < 604_800_000) return `${Math.max(1, Math.round(deltaMs / 86_400_000))} day${Math.round(deltaMs / 86_400_000) === 1 ? "" : "s"} ago`;
  return parsed.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

function buildExecutiveInboxUpdates(projectData = getProjectData(getActiveProject()), phaseAgentStateMap = {}) {
  const programId = projectData?.id || projectData?.programId || "";
  const updates = [];

  ((projectData?.milestoneSlips || []).slice().reverse()).slice(0, 3).forEach((slip) => {
    if (!slip?.milestoneName) return;
    updates.push({
      id: `slip-${slip.id || slip.milestoneId || slip.milestoneName}`,
      title: `Milestone at risk: ${slip.milestoneName}`,
      summary: slip.impactSummary || `Forecast slip of ${slip.slipDays || 0} day${Number(slip.slipDays || 0) === 1 ? "" : "s"} detected. Review dependencies and re-baseline the plan if needed.`,
      actionLabel: "Open delivery",
      viewId: "delivery",
      occurredAt: slip.detectedAt || slip.createdAt || Date.now(),
      tone: Number(slip.slipDays || 0) >= 14 ? "red" : "amber",
    });
  });

  ((projectData?.notificationLog || []).filter((entry) => entry?.status === "sent").slice().reverse()).slice(0, 3).forEach((entry) => {
    updates.push({
      id: `notification-${entry.id}`,
      title: "Notification delivered",
      summary: `${String(entry.itemType || "Program update").replace(/_/g, " ")} was delivered to a configured channel.`,
      actionLabel: "Open log",
      viewId: "notifications",
      occurredAt: entry.sentAt || Date.now(),
      tone: "green",
    });
  });

  ADAM_PHASE_SEQUENCE
    .map((phaseId) => ({ phaseId, state: phaseAgentStateMap?.[phaseId] || loadAgentState(programId, phaseId) }))
    .filter((entry) => entry?.state?.lastRanAt && !entry?.state?.running)
    .sort((left, right) => new Date(right.state.lastRanAt).getTime() - new Date(left.state.lastRanAt).getTime())
    .slice(0, 4)
    .forEach(({ phaseId, state }) => {
      if (state?.escalated) {
        updates.push({
          id: `agent-escalation-${phaseId}-${state.lastRanAt}`,
          title: `${getPhaseDisplayLabel(phaseId)} needs attention`,
          summary: state.escalationSummary || "The phase agent escalated a blocker that should be reviewed by the team.",
          actionLabel: "Open workspace",
          viewId: phaseId,
          occurredAt: state.lastRanAt,
          tone: "amber",
        });
        return;
      }
      if ((state?.lastObservedReadiness ?? 0) <= 0) return;
      updates.push({
        id: `agent-update-${phaseId}-${state.lastRanAt}`,
        title: `${getPhaseDisplayLabel(phaseId)} agent updated`,
        summary: (state?.lastObservedReadiness ?? 0) >= 85
          ? `Readiness is now ${state.lastObservedReadiness}% and the workspace looks ready for review.`
          : `Latest pass observed ${state.lastObservedReadiness}% readiness${state?.lastBenchmarkDelta?.message ? ` · ${state.lastBenchmarkDelta.message}` : "."}`,
        actionLabel: "Review workspace",
        viewId: phaseId,
        occurredAt: state.lastRanAt,
        tone: (state?.lastObservedReadiness ?? 0) >= 85 ? "green" : "blue",
      });
    });

  return updates
    .sort((left, right) => new Date(right.occurredAt || 0).getTime() - new Date(left.occurredAt || 0).getTime())
    .slice(0, 8);
}

